    const cols=['#fff3dc','#f7a8c4','#7a4a2a'];const sc=[];for(let i=0;i<3;i++){const a=i*2.1;sc.push(M(sph(.036,16,12),rfm('ice'+i,cols[i],{roughness:.6}),Math.sin(a)*.025,.135+(i===2?.035:0),Math.cos(a)*.025,g));}
