    const spine=this.spine=new THREE.Group();hips.add(spine);
    const chest=B(new THREE.CapsuleGeometry(.12,.2,6,20),spine,0,.24,0);chest.scale.set((this.look.style!=='cute'?1.0:1.12)+(guy?.15:0),1,this.look.style!=='cute'?.74:.78);
