// put one thing on a look (for buying, wearing, and trying things on in the store)
const SLOT_TABS=['dresses','tops','bottoms','shoes','hats','extras'];
function findItem(id){for(const tab of SLOT_TABS){const it=(CAT[tab]||[]).concat(GUY_CAT[tab]||[]).find(x=>x[0]===id);if(it)return [tab,it];}return [null,null];}
function applyItem(L,id,c){const [tab,it]=findItem(id);if(!it)return null;c=c||it[3];
  if(tab==='extras'){L.extras=L.extras||{};if(GLASSES.includes(id))GLASSES.forEach(g=>{if(g!==id)delete L.extras[g];});L.extras[id]=L.extras[id]||c;return tab;}
  L[KEY[tab]]={id,c};
  if(tab==='dresses'){L.top=L.bottom=null;}
  if(tab==='tops'){L.dress=null;if(!L.bottom)L.bottom=plainBottom(L);}
  if(tab==='bottoms'){L.dress=null;if(!L.top)L.top=plainTop(L);}
  return tab;}

/* ---------- put it all on the avatar (14-avatar.js calls this at the end of dress) ---------- */
function barberDress(k,look){const av=k.av,h=look.hair||{},cut=BCUT[h.id];
  if(cut){const cap=av.hairMeshes[0];if(cap){cap.visible=false;av.hairMeshes=av.hairMeshes.filter(m=>m!==cap);}
    const m=k.mat(h.c||'#2b1d16','hair');const n0=av.parts.length;
    if(h.id!=='bald'){const g=shellGeo(av,av.guy?guyHatPress(look,cut[3]):cut[3]);fuzz(g,.0012,200);k.P(g,m,k.head);}
    if(cut[4])cut[4](k,m);av.hairMeshes=av.hairMeshes.concat(av.parts.slice(n0).filter(o=>o.isMesh));}
  if(look.beard&&look.beard.id&&look.beard.id!=='none')buildBeard(k,look.beard);}
// ---- src/14d-dances.js ----
/* ================= DANCES AND GUY MOVES ================= */
// Tap Dance in the action buttons to pick a dance from the list (19c-dance-picker.js). Each dance here moves the
// avatar's joints over time: go(k,tgt,av) gets the seconds since the dance started (k) and sets the targets the
// avatar eases toward (tgt, see Avatar.update in 14-avatar.js), and t is how long it lasts. Walking stops a dance.
// Joints: l0/l1 legs forward(-)/back(+), k0/k1 knees, l0z/l1z legs out to the side, an ankles,
// a0x/a1x arms forward(-)/back(+), a0z/a1z arms out and up (arm 0 goes negative, arm 1 positive), e0/e1 elbows bend,
// a0y/a1y elbows bend sideways, bob hips up/down, hx hips side to side, sy turn the body, st twist the shoulders,
// lean bend forward, sz bend sideways, hr tilt the hips, hd tilt the head, hy turn the head, spin whole turns
// (end on a full turn), tilt the whole body forward.
// The same dances work for girls and guys.
const DANCES=[['dance','💃','Party'],['floss','🧵','The floss'],['twostep','🤠','Two step'],['breakdance','🔄','Breakdance'],['robot','🤖','Robot'],
  ['runningman','🏃','Running man'],['disco','🪩','Disco'],['sprinkler','💦','Sprinkler'],['macarena','🎶','Macarena'],['dab','😎','Dab'],['ballet','🩰','Ballet']];
const DANCE_IDS=new Set(DANCES.map(d=>d[0]));
const dEase=x=>x<=0?0:x>=1?1:x*x*(3-2*x),dPos=x=>Math.max(0,x);
// one arm in a named spot; side 0 is arm 0, side 1 mirrors it
const ARM_AT={down:[0,-.08,-.1,0],out:[-1.5,0,0,0],shoulder:[-.95,.75,-1.3,0],head:[-.2,-2.5,0,-1.5],hip:[-.55,.55,-.6,0],pocket:[.15,-.55,-.2,1.5]};
function armAt(tgt,side,spot){const [x,z,e,y]=ARM_AT[spot],m=side?-1:1;tgt['a'+side+'x']=x;tgt['a'+side+'z']=z*m;tgt['e'+side]=e;tgt['a'+side+'y']=y*m;}

const MOVE_ANIMS={
  // the floss: straight arms swing side to side, one in front and one behind, hips swing the other way
  floss:{t:4.4,go(k,tgt){const f=Math.sin(k*7);tgt.a0z=tgt.a1z=f*.85;tgt.a0x=-.5*f;tgt.a1x=.5*f;tgt.e0=tgt.e1=-.08;
    tgt.hx=-f*.06;tgt.l0z=tgt.l1z=f*.13;tgt.sz=f*.05;tgt.bob=-Math.abs(f)*.02;tgt.hd=f*.06;tgt.l0=tgt.l1=0;tgt.k0=tgt.k1=.05;}},
  // two step: step side to side with a bounce, elbows bent and snapping
  twostep:{t:4.8,go(k,tgt){const w=k*Math.PI*1.8,s=Math.sin(w),b=Math.abs(Math.cos(w));tgt.hx=s*.08;tgt.l0z=-dPos(-s)*.22;tgt.l1z=dPos(s)*.22;
    tgt.l0=tgt.l1=0;tgt.k0=tgt.k1=.15+.15*b;tgt.bob=-.02-.035*b;tgt.e0=tgt.e1=-1.5;tgt.a0x=-.25+s*.25;tgt.a1x=-.25-s*.25;tgt.a0z=-.2;tgt.a1z=.2;
    tgt.sy=s*.18;tgt.hd=s*.08;tgt.sz=-s*.05;}},
  // breakdance: toprock steps, drop down, spin on the floor with the legs out, then freeze with a hand in the air
  breakdance:{t:5.6,go(k,tgt){
    if(k<1.5){const s=Math.sin(k*7);tgt.l0=-.5*dPos(s);tgt.k0=.7*dPos(s);tgt.l1=-.5*dPos(-s);tgt.k1=.7*dPos(-s);tgt.sy=s*.35;tgt.st=-s*.2;
      tgt.a0z=-.7-.3*s;tgt.a1z=.7-.3*s;tgt.a0x=tgt.a1x=-.3;tgt.e0=tgt.e1=-1.2;tgt.bob=-.05;tgt.lean=.12;return;}
    if(k<1.9){const u=dEase((k-1.5)/.4);tgt.bob=-.5*u;tgt.l0=tgt.l1=-1.3*u;tgt.k0=tgt.k1=1.9*u;tgt.lean=.4*u;tgt.a0x=tgt.a1x=-.7*u;tgt.e0=tgt.e1=-.3;return;}
    if(k<4.4){const u=k-1.9;tgt.spin=dEase(u/2.5)*Math.PI*6;tgt.bob=-.5;tgt.tilt=.25;tgt.lean=.35;
      tgt.l0=-1.1+.35*Math.sin(u*12);tgt.l1=-.5-.35*Math.sin(u*12);tgt.k0=.3;tgt.k1=.5;tgt.l0z=-.6;tgt.l1z=.6;
      tgt.a0x=-.5;tgt.a0z=-.5;tgt.e0=0;tgt.a1z=1.2;tgt.a1x=-.2;tgt.e1=-.4;tgt.hd=.1;return;}
    tgt.spin=Math.PI*6;tgt.bob=-.45;tgt.a1z=2.7;tgt.e1=0;tgt.a1x=0;tgt.a0x=-.3;tgt.a0z=-.6;tgt.e0=0;
    tgt.l0=-1.4;tgt.k0=1.8;tgt.l1=-.6;tgt.k1=.4;tgt.l1z=.5;tgt.tilt=.15;tgt.sz=-.25;tgt.hd=-.2;}},
  // robot: stiff, choppy poses with the elbows bent at right angles
  robot:{t:4.8,go(k,tgt){const q=Math.floor(k*2.5)%4;tgt.a0x=tgt.a1x=0;tgt.a0z=-.1;tgt.a1z=.1;tgt.e0=tgt.e1=-1.57;tgt.k0=tgt.k1=.08;tgt.l0=tgt.l1=0;
    if(q===0)tgt.hy=.45;
    if(q===1){tgt.a0z=-1.57;tgt.a0y=-1.57;tgt.e0=0;tgt.sy=.3;tgt.hy=-.2;}
    if(q===2){tgt.a1z=1.57;tgt.a1y=1.57;tgt.e1=0;tgt.sy=-.3;tgt.hy=.2;}
    if(q===3){tgt.hy=-.45;tgt.bob=-.06;tgt.k0=tgt.k1=.3;tgt.l0=tgt.l1=-.15;tgt.a0x=tgt.a1x=-.3;}}},
  // running man: one knee comes up while the other foot slides back, arms pumping
  runningman:{t:4.4,go(k,tgt){const s=Math.sin(k*Math.PI*2.2);tgt.l0=-.9*dPos(s)+.3*dPos(-s);tgt.k0=1.3*dPos(s)+.1;tgt.l1=-.9*dPos(-s)+.3*dPos(s);tgt.k1=1.3*dPos(-s)+.1;
    tgt.bob=.03*Math.abs(s)-.06;tgt.a0x=.55*s;tgt.a1x=-.55*s;tgt.e0=tgt.e1=-1.6;tgt.a0z=-.15;tgt.a1z=.15;tgt.lean=.1;tgt.hd=s*.05;}},
  // disco: point up to the sky, then down across the hips, the other hand on the hip
  disco:{t:4.6,go(k,tgt){const w=k*Math.PI*1.8,u=(Math.sin(w)+1)/2;tgt.a0z=.5-2.9*u;tgt.a0x=-.35;tgt.e0=0;tgt.hy=-.3*u;
    tgt.a1z=.6;tgt.a1y=-1.5;tgt.e1=-.2;tgt.a1x=0;tgt.sy=(u-.5)*.3;tgt.hx=(.5-u)*.05;tgt.k0=.25*u;tgt.l0=-.1*u;tgt.k1=.05;tgt.l1=0;
    tgt.bob=-.02-.03*Math.abs(Math.cos(w*2));tgt.hd=(u-.5)*-.15;}},
  // sprinkler: one hand behind the head, the other arm out front, click-click-click around and sweep back
  sprinkler:{t:4.8,go(k,tgt){const c=k%2.4;let r;if(c<1.6)r=-.7+Math.floor(c/.27)*.28;else r=.7-dEase((c-1.6)/.8)*1.4;
    tgt.sy=r;tgt.a1z=2.5;tgt.a1y=1.6;tgt.a1x=.2;tgt.e1=0;tgt.a0x=-1.5;tgt.a0z=-.1;tgt.e0=0;tgt.l0=tgt.l1=0;tgt.k0=tgt.k1=.2;
    tgt.bob=-.03-(c<1.6?.02*Math.abs(Math.sin(c*Math.PI/.27)):0);tgt.hd=.1;}},
  // macarena: arms out, flip, shoulders, behind the head, hips, back pockets, wiggle and hop
  macarena:{t:6.4,go(k,tgt){const c=Math.floor(k*2.5)%16,frac=k*2.5%1;
    const R=['out','out','shoulder','head','hip','pocket'],r=Math.min(5,Math.floor(c/2)),l=Math.min(5,Math.floor((c-1)/2));
    armAt(tgt,1,R[r]);armAt(tgt,0,c<1?'down':R[l]);tgt.l0=tgt.l1=0;tgt.k0=tgt.k1=.08;
    if(c>=12&&c<15){tgt.hr=Math.sin(k*14)*.12;tgt.sy=Math.sin(k*14)*.15;tgt.bob=-.04;}
    if(c===15){tgt.bob=Math.sin(frac*Math.PI)*.08;tgt.k0=tgt.k1=.35;}
    if(c===2||c===3)tgt.hd=.05*(c===2?1:-1);}},
  // dab: duck your head into one elbow and throw the other arm up, then switch sides
  dab:{t:4,go(k,tgt){const c=k%2,d=Math.floor(k/2)%2;tgt.l0=tgt.l1=0;
    if(c<.5){const b=Math.sin(c/.5*Math.PI);tgt.bob=-.06*b;tgt.k0=tgt.k1=.3*b;tgt.e0=tgt.e1=-.6;tgt.a0x=tgt.a1x=-.2;return;}
    const up=d?0:1,bent=d?1:0,m=up?1:-1;tgt['a'+up+'z']=2.2*m;tgt['a'+up+'x']=-.3;tgt['e'+up]=0;
    tgt['a'+bent+'x']=-1.9;tgt['a'+bent+'z']=.7*m;tgt['e'+bent]=-1.5;tgt.hd=.3*m;tgt.hy=.35*m;tgt.lean=.25;tgt.sy=-.2*m;tgt.bob=-.03;}},
  // ballet: a pirouette on your toes with arms over your head, then an arabesque
  ballet:{t:5,go(k,tgt){
    if(k<2.6){const u=dEase(k/2.4);tgt.spin=u*Math.PI*4;tgt.a0z=-2.7;tgt.a1z=2.7;tgt.a0x=tgt.a1x=-.25;tgt.e0=tgt.e1=-.5;tgt.a0y=-.6;tgt.a1y=.6;
      tgt.l0=0;tgt.k0=0;tgt.l1=-.8;tgt.k1=1.7;tgt.l1z=.45;tgt.an=.4;tgt.bob=.04;tgt.hd=0;return;}
    tgt.spin=Math.PI*4;tgt.lean=.55;tgt.l1=1.15;tgt.k1=0;tgt.l0=0;tgt.k0=.05;tgt.a0x=-1.5;tgt.a0z=-.1;tgt.e0=0;tgt.a1z=1.4;tgt.a1x=.2;tgt.e1=-.2;tgt.hd=-.1;tgt.bob=-.02;}},

  /* the guy versions of the girly moves (Avatar.play swaps them in through GUY_MOVES) */
  // cool pose: arms crossed, chin up, standing wide at an angle
  coolpose:{t:2.4,go(k,tgt){tgt.a0x=tgt.a1x=-.6;tgt.a0z=-.15;tgt.a1z=.15;tgt.e0=tgt.e1=-1.55;tgt.a0y=1.1;tgt.a1y=-1.1;tgt.lean=-.06;tgt.sy=.3;tgt.hy=-.25;tgt.hd=.08;
    tgt.l0=tgt.l1=0;tgt.k0=tgt.k1=0;tgt.l0z=-.12;tgt.l1z=.12;tgt.bob=-.01+Math.sin(Math.min(k,.5)*Math.PI*2)*.01;}},
  // finger guns: both hands become finger guns (index out, thumb up, the other fingers curled; see gunHandGeo),
  // aim, fire "pew pew pew pew" with a kick of the wrist and elbow on each shot, then blow the smoke off one finger
  guns:{t:2.3,go(k,tgt,a){const e=a.emote,up=dEase(k/.3);if(e&&e.n==null)e.n=0;
    while(e&&e.n<PEW_AT.length&&k>=PEW_AT[e.n]){pewShot(a,e.n%2);e.n++;}
    tgt.sy=.25*up;tgt.hd=-.1*up;tgt.hy=-.15*up;tgt.lean=-.04*up;tgt.l0z=-.08;tgt.l1z=.08;
    for(const side of [0,1]){const kick=pewKick(k,side),A=a.arms[side];
      tgt['a'+side+'x']=-.08-(1.4+kick*.18)*up;tgt['a'+side+'z']=(side?-.16:.16)*up;tgt['e'+side]=-.15-kick*.3;
      if(A&&A.gun)A.gun.rotation.x=-kick*.4;}
    // blow the smoke off the tip of the finger: one hand comes up to the lips, the other drops to the side
    if(k>1.5){const b=dEase((k-1.5)/.3);tgt.a0x=-1.48+.38*b;tgt.e0=-.15-1.95*b;tgt.a0z=.16+.19*b;tgt.hd=.1*b;tgt.hy=-.15+.15*b;
      tgt.a1x=-1.48+1.4*b;tgt.a1z=-.16+.24*b;tgt.e1=-.15-.1*b;
      if(e&&!e.puff&&k>1.8){e.puff=1;pewPuff(a);}}}},
  // bow: one hand on the chest, the other behind the back
  gbow:{t:1.8,go(k,tgt){const b=Math.sin(Math.min(1,k/1.6)*Math.PI);tgt.lean=b*.6;tgt.bob=-b*.04;tgt.a0x=-.9;tgt.a0z=.45;tgt.e0=-1.6;tgt.a1x=.5;tgt.a1z=-.1;tgt.e1=-1.2;
    tgt.l0=tgt.l1=0;tgt.k0=tgt.k1=0;}},
  // spin: a quick turn that ends pointing up
  spin:{t:1.4,go(k,tgt){const u=dEase(k/.9);tgt.spin=u*Math.PI*2;tgt.a0z=-.5;tgt.a1z=.5+(k>.9?1.9:0);tgt.a0x=tgt.a1x=0;tgt.e0=-.8;tgt.e1=k>.9?0:-.8;tgt.bob=-.03;}},
  // flex: show off both arms
  flex:{t:2,go(k,tgt){const p=Math.sin(Math.min(k,1.8)*8)*.08;tgt.a0z=-1.5;tgt.a0y=-1.7-p;tgt.a1z=1.5;tgt.a1y=1.7+p;tgt.e0=tgt.e1=0;tgt.a0x=tgt.a1x=0;
    tgt.l0z=-.12;tgt.l1z=.12;tgt.bob=-.04;tgt.lean=-.05;tgt.hd=Math.sin(k*3)*.06;}}};

// girls' move -> guys' move
const GUY_MOVES={pose:'coolpose',kiss:'guns',bow:'gbow',twirl:'spin'};

// walking the runway: girls put one foot in front of the other with swinging hips, guys stride with their shoulders
function runwayWalk(a,tgt,sp){const s=Math.sin(a.phase),k=Math.min(1,sp);
  if(a.guy){tgt.st=-s*.16*k;tgt.sy=s*.05*k;tgt.a0x*=1.35;tgt.a1x*=1.35;tgt.a0z=-.2;tgt.a1z=.2;tgt.e0=tgt.e1=-.4;tgt.lean=-.05;tgt.l0z=-.04;tgt.l1z=.04;tgt.hd=0;tgt.hy=0;return;}
  tgt.l0z=.08*k;tgt.l1z=-.08*k;tgt.hr=s*.09*k;tgt.hx=s*.025*k;tgt.sy=s*.12*k;tgt.st=-s*.06*k;tgt.a0x*=.6;tgt.a1x*=.6;tgt.a0z=-.16;tgt.a1z=.16;tgt.e0=tgt.e1=-.25;tgt.lean=-.03;tgt.hd=-s*.03;}

/* ---- 👉 hands for hand gestures ----
   Hand gestures (wave, clap, blow a kiss, pew pew, cheer, flex, cool pose) need empty hands, so whatever you're holding
   (the skateboard, a purse, a wand, a ball, flowers...) is put away until the move is done and comes back after.
   Avatar.update does it for everyone, so friends online see it too: they get the same move from online.js.
   Things you WEAR on a hand (a baseball glove) have userData.worn and stay on. */
const HANDS_FREE=new Set(['wave','clap','kiss','guns','cheer','flex','coolpose']);
// the finger-gun hand: the palm and the index finger pointing straight out, the thumb sticking up and the other three
// fingers curled into the palm. Same size and spot as the normal hand (handGeo) so it fits the same wrist.
function gunHandGeo(sx){const k='g'+sx;if(LIMB[k])return LIMB[k];const parts=[],X=-sx;
  const palm=new RoundedBoxGeometry(.048,.052,.0135,4,.0064);{const pp=palm.attributes.position;for(let i=0;i<pp.count;i++){const y=pp.getY(i),t=Math.min(1,Math.max(0,(y+.004)/.03));pp.setX(i,pp.getX(i)*(1-.22*t));pp.setZ(i,pp.getZ(i)*(1+.25*t));}}palm.translate(0,-.027,0);parts.push(palm);
  const seg=(b,d,L,r0,r1)=>{d=d.clone().normalize();parts.push(limbPart(new THREE.CylinderGeometry(r0,r1,L,12),b.clone().addScaledVector(d,L/2),d.clone().negate()));
    const j=new THREE.SphereGeometry(r1,12,8);const e=b.clone().addScaledVector(d,L);j.translate(e.x,e.y,e.z);parts.push(j);return e;};
  const knuckle=(b,r)=>{const g=new THREE.SphereGeometry(r*1.05,12,8);g.translate(b.x,b.y,b.z);parts.push(g);};
  // the index finger: the "barrel", straight out
  {const b=new THREE.Vector3(X*.0158,-.049,0);knuckle(b,.0054);seg(b,new THREE.Vector3(0,-1,0),.047,.0054,.0045);}
  // middle, ring and pinky curl down into the palm
  [[.0053,.0056],[-.0053,.0053],[-.0155,.0048]].forEach(([fx,r])=>{const b=new THREE.Vector3(X*fx,-.049,0);knuckle(b,r);
    const m=seg(b,new THREE.Vector3(0,-.45,-1),.019,r,r*.95);const t=seg(m,new THREE.Vector3(0,1,-.35),.016,r*.95,r*.85);});
  // the thumb sticks up: the "hammer" of the finger gun
  {const b=new THREE.Vector3(X*.022,-.016,.002);knuckle(b,.0068);seg(b,new THREE.Vector3(X,-.12,.12),.034,.0068,.0055);}
  const g=mergeGeometries(parts.map(x=>{x=x.index?x.toNonIndexed():x;['uv1','uv2'].forEach(a=>x.deleteAttribute(a));return x;}));g.computeVertexNormals();
  return LIMB[k]={g,tip:new THREE.Vector3(X*.0158,-.1,0)};}
// the four shots of pew pew (which hand fires goes back and forth) and how hard each hand is kicking back right now
const PEW_AT=[.42,.66,.98,1.22];
function pewKick(k,side){let m=0;PEW_AT.forEach((s,i)=>{if(i%2===side&&k>=s)m=Math.max(m,Math.exp(-(k-s)*16));});return m;}
// louder for you, softer for a friend further away, silent across town
function pewVol(a){if(!av||a===av)return 1;const d=a.g.position.distanceTo(av.g.position);return Math.max(0,1-d/14);}
function pewTip(a,side){const A=a.arms&&a.arms[side];if(!A||!A.gunAim)return null;return A.gunAim.localToWorld(A.gunTip.clone());}
// one "pew": a quick zappy sound that slides down, and a little flash of sparkles out of the fingertip
function pewShot(a,side){const v=pewVol(a);
  if(v>.05){const f=1+(Math.random()-.5)*.12;tone(1700*f,.15,'square',.03*v,0,330*f);tone(2400*f,.11,'sine',.07*v,0,480*f);}
  if(v>0){const p=pewTip(a,side);if(p)burst(p,'#ffe27a',8,1.3,.05);}}
// blowing the smoke off the finger
function pewPuff(a){const v=pewVol(a);if(v>.05)tone(420,.28,'sawtooth',.012*v,0,240);if(v>0){const p=pewTip(a,0);if(p)burst(p,'#e6e6ee',10,.5,.07);}}
// ---- src/14d-fashion.js ----
/* ================= 🛍️ NEW FASHION AT THE CLOTHING STORE ================= */
// More outfits to buy with coins, for guys and for girls. They're sold at the 👔 Clothing Store and at the
// 🛍️ racks in the Sparkle Studio, and once bought they're in your closet. Every one is in the 2D studio too
// (index.html), with the same id. Guy tops all have sleeves, so the shoulders are covered.

/* ---------- fabrics ---------- */
const FAB_TEX={};
function fabMat(k,c,kind,o={}){const key=kind+c+(o.c2||'');const t=FAB_TEX[key]||(FAB_TEX[key]=canvasTex(128,128,(x,w,h)=>{x.fillStyle=c;x.fillRect(0,0,w,h);const c2=o.c2||trimOf(c);
    // wide bands across, like a rugby shirt
    if(kind==='bands'){x.fillStyle=c2;for(let y=0;y<h;y+=64)x.fillRect(0,y,w,26);}
    // thin stripes across, like a sailor top
    if(kind==='breton'){x.fillStyle=c2;for(let y=4;y<h;y+=21)x.fillRect(0,y,w,8);}
    // little checks
    if(kind==='gingham'){x.fillStyle='rgba(255,255,255,.55)';for(let i=0;i<w;i+=32){x.fillRect(i,0,16,h);x.fillRect(0,i,w,16);}x.fillStyle='rgba(255,255,255,.35)';for(let i=0;i<w;i+=32)for(let j=0;j<h;j+=32)x.fillRect(i,j,16,16);}
    // corduroy ribs that run up and down
    if(kind==='cord'){for(let i=0;i<w;i+=8){x.fillStyle='rgba(0,0,0,.22)';x.fillRect(i,0,2,h);x.fillStyle='rgba(255,255,255,.12)';x.fillRect(i+4,0,2,h);}}
    // a soft knit with ribs
    if(kind==='knit'){for(let i=0;i<w;i+=16){x.fillStyle='rgba(0,0,0,.14)';x.fillRect(i,0,3,h);}x.strokeStyle='rgba(255,255,255,.18)';x.lineWidth=2;
      for(let i=8;i<w;i+=16)for(let j=0;j<h;j+=10){x.beginPath();x.moveTo(i-3,j);x.lineTo(i,j+5);x.lineTo(i+3,j);x.stroke();}}
  },o.rep||4));
  const m=new THREE.MeshPhysicalMaterial({color:'#ffffff',map:t,roughness:o.rough??.85,sheen:.7,sheenColor:new THREE.Color('#ffffff'),sheenRoughness:.5});k.av.mats.push(m);return m;}
const satin=(k,c)=>{const m=k.mat(c,'shiny');m.roughness=.22;m.sheen=1;return m;};
// a band all the way round the top at height y (for color blocks and hems)
const bodyBand=(k,m,y,t=.016)=>{const o=beltRing(k,m,k.spine,.129,t,y);o.scale.set(k.av.shellX,1,.8);return o;};
const standCollar=(k,m,r=.06,h=.05)=>{const o=k.P(new THREE.CylinderGeometry(r,r*1.06,h,24,1,true),m,k.spine,0,.485,0);o.material.side=THREE.DoubleSide;return o;};
const zipper=(k,y0=.47,y1=.03)=>frontStrip(k,k.mat('#d9d9d9','metal'),lineOf(0,y0,0,y1,.004,.004,10),.005);

const FASHION_WEAR={
  /* ===== guys ===== */
  // 🛩️ Bomber jacket: shiny, with ribbed collar, cuffs and hem, a zipper and a little pocket on the sleeve
  bomber(k,c){const m=k.mat(c,'shiny');m.roughness=.4;k.topShell(m,'long');const rib=k.mat(shadeC(c,-.3));crewNeck(k,rib,.058,.015);cuffs(k,rib,.045,.016);waistband(k,rib);zipper(k);
    const a=k.arms[1];k.P(box(.012,.045,.035),k.mat('#d9d9d9','metal'),a.sh,a.sx*.05,-.09,0);},
  // 🏉 Rugby shirt: wide stripes, a white collar and a button placket
  rugby(k,c){const m=fabMat(k,c,'bands');k.topShell(m,'long');const w=k.mat('#ffffff');shirtCollar(k,w);frontStrip(k,w,lineOf(0,.46,0,.36,.013,.013,4),.003);
    const bm=k.mat(shadeC(c,-.3),'shiny');frontDot(k,bm,.43,0,.005);frontDot(k,bm,.39,0,.005);cuffs(k,w,.044,.012);},
  // 🌬️ Windbreaker: shiny with a white band across the chest, a stand-up collar and a half zip
  windbreaker(k,c){const m=k.mat(c,'shiny');m.roughness=.3;k.topShell(m,'long');const w=k.mat(trimOf(c),'shiny');w.roughness=.3;
    bodyBand(k,w,.33,.03);for(const a of k.arms)k.P(new THREE.CylinderGeometry(.05,.05,.05,20,1,true),w,a.sh,0,-.06,0).material.side=THREE.DoubleSide;
    standCollar(k,m);zipper(k,.5,.33);cuffs(k,k.mat(shadeC(c,-.25)),.042,.012);waistband(k,k.mat(shadeC(c,-.25)));},
  // 🧥 Corduroy shirt-jacket: ribbed fabric, a collar, two chest pockets with flaps and big buttons
  shacket(k,c){const m=fabMat(k,c,'cord');k.topShell(m,'long');shirtCollar(k,m);const dk=fabMat(k,shadeC(c,-.15),'cord');
    for(const s of [-1,1]){frontStrip(k,dk,lineOf(s*.065,.38,s*.065,.32,.028,.028,2),.004);frontStrip(k,m,lineOf(s*.065,.388,s*.065,.37,.03,.03,1),.007);}
    const bm=k.mat(shadeC(c,-.45),'shiny');[.43,.35,.27,.19,.11].forEach(y=>frontDot(k,bm,y,0,.0065));cuffs(k,dk,.046,.013);},
  // 🏃 Track jacket: shiny zip-up with stripes down the sleeves
  trackjacket(k,c){const m=k.mat(c,'shiny'),w=k.mat(trimOf(c));k.topShell(m,'long');standCollar(k,m);zipper(k);waistband(k,m);
    for(const a of k.arms){k.P(box(.008,.17,.02),w,a.sh,a.sx*.048,-.13,0);k.P(box(.008,.15,.02),w,a.el,a.sx*.042,-.1,0);}
    for(const s of [-1,1])frontStrip(k,w,lineOf(s*.05,.47,s*.06,.2,.004,.004,6),.004);},
  // 〰️ Striped tee: a soft tee with thin stripes, sleeves that cover the shoulders
  stripetee(k,c){const m=fabMat(k,c,'breton');k.topShell(m,'short');for(const a of k.arms)k.P(capTop(.055,.05),m,a.sh,0,-.02,0);crewNeck(k,k.mat(c));},
  // 🏃 Track pants: shiny with stripes down the sides and cuffs at the ankles
  trackpants(k,c){const m=k.mat(c,'shiny');k.waist(m);k.legsShell(m,.074,true);sideStripes(k,k.mat(trimOf(c)),true);ankleCuffs(k,m,.064);drawstrings(k);},
  // 🟫 Corduroys: ribbed straight pants with a belt
  cords(k,c){const m=fabMat(k,c,'cord');k.waist(m);looseLegs(k,m,.082,{hem:.96});guyBelt(k,'#3a2a1e');},
  // 🩳 Jean shorts: long denim shorts with a frayed hem
  jorts(k,c){const m=k.mat(c,'denim');k.waist(m);looseLegs(k,m,.088,{thigh:.4,shin:0});const f=k.mat('#e8eef7');for(const l of k.legs)beltRing(k,f,l.hp,.089,.006,.02-.4+.008);guyBelt(k,'#1a1a1a');},
  // 🥾 Chelsea boots: shiny ankle boots with stretchy sides and a pull tab
  chelsea(k,c){const m=k.mat(c,'shiny');m.clearcoat=1;shoeShell(k,m,.9,1.02);bootLeg(k,m,.064,.14);solePad(k,k.mat('#1a1a1a','shiny'),.02,.112,.232);
    const e=k.mat('#1a1a1a');k.legs.forEach(l=>{const X=k.av.legX;for(const s of [-1,1])k.P(box(.006,.08,.035),e,l.kn,s*.064,-.37-X+.08,0);k.P(box(.02,.03,.006),e,l.kn,0,-.37-X+.15,-.066);});},
  // 👟 Retro sneakers: a cream sole, a toe cap and a colored stripe on the side
  retrokicks(k,c){const m=k.mat('#ffffff');shoeShell(k,m,.86,1.04);solePad(k,k.mat('#f2e6c8','shiny'),.034,.118,.235);const cm=k.mat(c,'shiny');
    k.legs.forEach(l=>{for(const s of [-1,1]){const st=k.P(box(.005,.012,.09),cm,l.an,s*.064,-.015,.05);st.rotation.x=-.3;}k.P(sph(.04,12,8),cm,l.an,0,-.025,.13).scale.set(1.3,.6,.9);});},
  // ⛵ Boat shoes: low and shiny with a white sole and laces around the top
  boatshoes(k,c){const m=k.mat(c,'shiny');shoeShell(k,m,.68,1.02);solePad(k,k.mat('#ffffff','shiny'),.02,.112,.232);const lm=k.mat('#e8d5a8');
    k.legs.forEach(l=>{beltRing(k,lm,l.an,.05,.004,.022).scale.set(1.1,1,1.6);k.P(box(.03,.004,.012),lm,l.an,.02,.03,.09);});},
  // 🧢 Flat cap: a low flat crown with a short brim
  flatcap(k,c){const m=fabMat(k,c,'knit',{rough:.9});const cr=k.P(new THREE.SphereGeometry(.15,24,12,0,Math.PI*2,0,Math.PI/2),m,k.head,0,.04,.01);cr.scale.set(1.04,.55,1.14);cr.rotation.x=.18;
    const b=k.P(new THREE.CylinderGeometry(.1,.1,.012,24,1,false,-1.4,2.8),m,k.head,0,.06,.1);b.scale.z=.7;b.rotation.x=.25;k.P(sph(.01,8,6),m,k.head,0,.12,.02);},
  // 🧢 Trucker hat: a tall front panel, a mesh back and a curved brim
  trucker(k,c){const m=k.mat(c),w=k.mat('#ffffff');const back=k.P(new THREE.SphereGeometry(.15,28,14,Math.PI*.6,Math.PI*.8,0,Math.PI/2),w,k.head,0,.025,-.005);back.scale.set(1.02,1.02,1.04);
    const fr=k.P(new THREE.SphereGeometry(.152,28,14,-Math.PI*.4,Math.PI*1.2,0,Math.PI/2),m,k.head,0,.025,-.005);fr.scale.set(1.02,1.04,1.04);
    const b=k.P(cyl(.11,.11,.012,24),m,k.head,0,.05,.15);b.scale.z=.85;b.rotation.x=.12;k.P(sph(.012,8,6),m,k.head,0,.18,-.005);},
  // 👜 Crossbody bag: a strap across the chest and a small bag on the hip
  crossbody(k,c){const m=k.mat(c,'shiny'),dk=k.mat(shadeC(c,-.3));frontStrip(k,dk,lineOf(.085,.45,-.11,.1,.009,.009,10),.012);
    const back=k.P(box(.018,.36,.008),dk,k.spine,.03,.27,-.11);back.rotation.z=.55;
    const bag=k.P(new RoundedBoxGeometry(.13,.09,.045,2,.015),m,k.spine,-.12,.08,.07);bag.rotation.y=-.5;k.P(box(.08,.008,.004),k.mat('#d9d9d9','metal'),bag,0,.025,.024);},
  // 🤠 Neckerchief: a bandana tied round the neck with a point in front
  neckerchief(k,c){const m=fabMat(k,c,'gingham',{rep:6});const r=k.P(new THREE.TorusGeometry(.064,.018,8,24),m,k.spine,0,.465,0);r.rotation.x=Math.PI/2;
    const t=k.P(new THREE.ConeGeometry(.05,.09,3),m,k.spine,0,.415,shellZ(k,.42)+.01);t.rotation.x=Math.PI;t.scale.z=.25;},

  /* ===== girls ===== */
  // 🥂 Satin slip dress: thin straps, a shiny midi skirt and lace at the neckline
  slipdress(k,c){const m=satin(k,c);k.topShell(m,'strap');k.skirt(m,.62,.27,{curve:.9,folds:.04,k:10});bodyBand(k,k.mat('#ffffff'),.4,.006);k.av.legAmp=.32;},
  // 🎀 Wrap dress: crossed front, a tie belt with a bow and a swishy skirt
  wrapdress(k,c){const m=k.mat(c),dk=k.mat(shadeC(c,-.2));k.topShell(m,'short');for(const s of [-1,1])frontStrip(k,dk,lineOf(s*.055,.46,-s*.04,.2,.004,.004,8),.004);
    beltRing(k,dk,k.hips,.14,.012,.1);for(const s of [-1,1]){const l=k.P(new THREE.ConeGeometry(.02,.05,10),dk,k.hips,.08+s*.025,.1,.12);l.rotation.z=s*Math.PI/2;l.scale.z=.5;}
    k.P(capTop(.006,.1),dk,k.hips,.085,.09,.125);k.skirt(m,.5,.3,{curve:.85,folds:.08,k:9});},
  // 🧶 Sweater dress: cozy knit with a tall collar and long sleeves
  sweaterdress(k,c){const m=fabMat(k,c,'knit');k.topShell(m,'long');standCollar(k,m,.058,.07);cuffs(k,m,.046,.016);k.skirt(m,.34,.18,{curve:1,folds:.02,k:12});},
  // 🧺 Gingham dress: little checks, puff sleeves and a round white collar
  gingham(k,c){const m=fabMat(k,c,'gingham',{rep:5});k.topShell(m,'puff');k.skirt(m,.45,.32,{curve:.8,folds:.07,k:12});const w=k.mat('#ffffff');
    for(const s of [-1,1]){const d=k.P(cyl(.03,.03,.006,20),w,k.spine,s*.028,.44,shellZ(k,.44,s*.028)+.004);d.rotation.x=Math.PI/2-.3;}},
  // 👚 Puff-sleeve blouse: big puffy shoulders and buttons down the front
  puffblouse(k,c){const m=k.mat(c);k.topShell(m,'puff');for(const a of k.arms)k.P(capTop(.042,.15),m,a.el);const bm=k.mat(trimOf(c),'shiny');[.4,.34,.28,.22].forEach(y=>frontDot(k,bm,y,0,.005));},
  // 🧥 Cardigan: a soft knit open over a white top, with buttons
  cardigan(k,c){const m=fabMat(k,c,'knit');k.topShell(m,'long');frontStrip(k,k.mat('#ffffff'),lineOf(0,.46,0,.07,.03,.03,10),.003);
    for(const s of [-1,1])frontStrip(k,k.mat(shadeC(c,-.15)),lineOf(s*.034,.46,s*.036,.07,.005,.005,10),.004);
    const bm=k.mat('#ffffff','shiny');[.38,.3,.22,.14].forEach(y=>frontDot(k,bm,y,-.034,.006));cuffs(k,m,.046,.014);waistband(k,m);},
  // 🧥 Trench coat: long, with lapels, a belt with a buckle and two rows of buttons
  trench(k,c){const m=k.mat(c);k.topShell(m,'long');const hem=k.skirt(m,.48,.24,{r0:.15,curve:1,folds:.03,k:8});hem.scale.set(k.av.shellX/1.12*1.04,1,.84);
    const dk=k.mat(shadeC(c,-.2));for(const s of [-1,1])frontStrip(k,dk,lineOf(s*.04,.46,s*.012,.3,.016,.006,6),.005);bodyBand(k,dk,.12,.014);
    k.P(box(.03,.026,.01),k.mat('#d9d9d9','metal'),k.spine,0,.12,shellZ(k,.12)+.012);const bm=k.mat(shadeC(c,-.4),'shiny');for(const x of [-.04,.04])[.27,.21].forEach(y=>frontDot(k,bm,y,x,.0065));cuffs(k,dk,.046,.012);},
  // ⚓ Striped top: a sailor-style top with thin stripes and long sleeves
  stripetop(k,c){const m=fabMat(k,c,'breton');k.topShell(m,'long');crewNeck(k,k.mat(c),.06,.008);},
  // 👖 Wide-leg jeans: high waist and wide legs
  widejeans(k,c){const m=k.mat(c,'denim');k.waist(m);looseLegs(k,m,.084,{hem:1.18});bodyBand(k,k.mat(shadeC(c,-.15),'denim'),.035,.012);},
  // 🏫 Plaid skirt: a pleated mini in a plaid
  plaidskirt(k,c){const m=plaidMat(k,c);k.waist(m);k.skirt(m,.3,.25,{curve:.6,folds:.1,k:20});},
  // 🌙 Satin skirt: a shiny midi skirt that swishes
  satinskirt(k,c){const m=satin(k,c);k.waist(m);k.skirt(m,.6,.3,{curve:.9,folds:.05,k:12});k.av.legAmp=.32;},
  // 👟 Platform sneakers: tall white soles that make you taller
  platsneaks(k,c){shoeShell(k,k.mat(c),.86,1.04);const w=k.mat('#ffffff','shiny');k.legs.forEach(l=>k.P(new RoundedBoxGeometry(.12,.07,.24,2,.015),w,l.an,0,-.07,.045));
    shoeTrim(k,k.mat(trimOf(c),'shiny'));k.av.lift=.04;},
  // 🤠 Western boots: tall, with a pointy toe, a heel and stitching
  westernboots(k,c){const m=k.mat(c,'shiny');shoeShell(k,m,.85,1).forEach(sh=>{sh.scale.z*=1.12;});bootLeg(k,m,.066,.24);const g=k.mat('#d4af37','metal');
    k.legs.forEach(l=>{k.P(box(.06,.05,.045),k.mat(shadeC(c,-.3),'shiny'),l.an,0,-.05,-.03);for(const s of [-1,1]){const st=k.P(box(.004,.14,.004),g,l.kn,s*.05,-.29-k.av.legX,.045);st.rotation.y=s*.6;}});},
  // 🥿 Mules: slip-on shoes with a pointy toe and a little heel
  mules(k,c){const m=k.mat(c,'shiny');shoeShell(k,m,.6,1);k.legs.forEach(l=>{k.P(cyl(.014,.01,.045,8),m,l.an,0,-.045,-.035);k.P(box(.03,.006,.02),k.mat('#d4af37','metal'),l.an,0,.005,.09);});},
  // 💇‍♀️ Claw clip: a big clip holding your hair up at the back
  clawclip(k,c){const m=k.mat(c,'shiny');m.transparent=true;m.opacity=.92;for(const s of [-1,1]){const t=k.P(new THREE.TorusGeometry(.04,.01,8,16,Math.PI),m,k.head,0,.08,-.15+s*.012);t.rotation.y=Math.PI/2;t.rotation.z=s*.3;}
    for(let i=-2;i<=2;i++)k.P(new THREE.ConeGeometry(.007,.03,6),m,k.head,i*.012,.05,-.16).rotation.x=Math.PI;},
  // 🌸 Bandana headband: a printed scarf tied round your head with a knot at the back
  headscarf(k,c){const m=fabMat(k,c,'gingham',{rep:6});const b=k.P(new THREE.TorusGeometry(.142,.018,8,40),m,k.head,0,.085,-.01);b.rotation.x=Math.PI/2-.35;b.scale.set(1.04,1.08,1);
    k.P(sph(.018,10,8),m,k.head,0,.035,-.15);for(const s of [-1,1]){const t=k.P(new THREE.ConeGeometry(.02,.08,3),m,k.head,s*.022,-.01,-.155);t.rotation.z=s*.35;t.scale.z=.3;}},
  // 👜 Shoulder bag: a little bag tucked under your arm on a short strap
  shoulderbag(k,c){const a=k.arms[1],m=k.mat(c,'shiny');const s=k.P(new THREE.TorusGeometry(.06,.006,6,20),k.mat(shadeC(c,-.25)),a.sh,0,-.05,0);s.rotation.y=Math.PI/2;
    k.P(new RoundedBoxGeometry(.04,.09,.17,2,.015),m,a.sh,a.sx*.05,-.13,.0);k.P(box(.006,.02,.03),k.mat('#d4af37','metal'),a.sh,a.sx*.072,-.12,.0);},
  // ⭕ Hoop earrings: big gold hoops
  hoops(k,c){const m=k.mat(c,'metal');for(const s of [-1,1]){const h=k.P(new THREE.TorusGeometry(.03,.004,8,24),m,k.head,s*.13*k.av.hs.x,-.075,.0);h.rotation.y=Math.PI/2;}},
};
Object.assign(OUTFITS2D,FASHION_WEAR);

