const joy={id:null,x0:0,y0:0,x:0,y:0};const look={id:null,x:0,y:0};const joyEl=$('#joy'),knob=$('#knob');
let closetOpen=false;
const ray=new THREE.Raycaster(),ndc=new THREE.Vector2();
const brush={c:'#2b1d16',size:'thin',erase:false,last:null,id:null};const BRUSH={thin:5,medium:12,thick:26};const undo=[];
function faceHit(e){ndc.set(e.clientX/innerWidth*2-1,-(e.clientY/innerHeight)*2+1);ray.setFromCamera(ndc,camera);const h=ray.intersectObject(av.overlay,false)[0];return h&&h.uv?h.uv:null;}
function paintAt(uv){const cv=av.paintCv,W=cv.width,x=cv.getContext('2d');const px=uv.x*W,py=(1-uv.y)*W;
  x.globalCompositeOperation=brush.erase?'destination-out':'source-over';x.strokeStyle=brush.c;x.fillStyle=brush.c;x.lineCap=x.lineJoin='round';x.lineWidth=BRUSH[brush.size]*W/1024*(brush.erase?2:1);x.globalAlpha=brush.size==='thick'&&!brush.erase?.55:1;
  x.beginPath();if(brush.last){x.moveTo(brush.last[0],brush.last[1]);x.lineTo(px,py);x.stroke();}else{x.arc(px,py,x.lineWidth/2,0,Math.PI*2);x.fill();}
  x.globalAlpha=1;x.globalCompositeOperation='source-over';brush.last=[px,py];av.renderFace();}
function savePaint(){try{SAVE.facePaint=av.paintCv.toDataURL('image/png');}catch(e){}persist();}
const drawing=()=>closetOpen&&!parlorOpen&&!shopOpen&&ctab==='makeup'&&(!glamOpen||mTool==='paint');
canvas.addEventListener('pointerdown',e=>{e.preventDefault();
  if(pinchDown(e))return;
  if(parlorOpen){parlorDown(e);return;}
  if(bakeryOpen){bakeryDown(e);return;}
  if(garageOpen){garageDown(e);return;}
  if(sandOpen){sandDown(e);return;}
  if(beautyDown(e))return;
  if(drawing()&&brush.id===null){const uv=faceHit(e);if(uv){brush.id=e.pointerId;brush.last=null;const x=av.paintCv.getContext('2d');undo.push(x.getImageData(0,0,av.paintCv.width,av.paintCv.height));if(undo.length>5)undo.shift();paintAt(uv);try{canvas.setPointerCapture(e.pointerId);}catch(_){}return;}}
  if(closetOpen||e.pointerType==='mouse'||e.clientX>innerWidth*.5){if(look.id===null){look.id=e.pointerId;look.x=e.clientX;look.y=e.clientY;try{canvas.setPointerCapture(e.pointerId);}catch(_){}}return;}
  if(joy.id===null){joy.id=e.pointerId;joy.x0=e.clientX;joy.y0=e.clientY;joy.x=joy.y=0;joyEl.style.left=e.clientX+'px';joyEl.style.top=e.clientY+'px';joyEl.style.display='block';knob.style.transform='';try{canvas.setPointerCapture(e.pointerId);}catch(_){}fadeHint();}});
canvas.addEventListener('pointermove',e=>{
  if(pinchMove(e))return;
  if(parlorOpen){parlorMove(e);return;}
  if(bakeryOpen){bakeryMove(e);return;}
  if(garageOpen){garageMove(e);return;}
  if(sandOpen){sandMove(e);return;}
  if(beautyMove(e))return;
  if(e.pointerId===brush.id){const uv=faceHit(e);if(uv)paintAt(uv);else brush.last=null;return;}
  if(e.pointerId===joy.id){let dx=e.clientX-joy.x0,dy=e.clientY-joy.y0;const d=Math.hypot(dx,dy),max=56;if(d>max){dx*=max/d;dy*=max/d;}joy.x=dx/max;joy.y=dy/max;knob.style.transform=`translate(${dx}px,${dy}px)`;}
  if(e.pointerId===look.id){const dx=e.clientX-look.x,dy=e.clientY-look.y;look.x=e.clientX;look.y=e.clientY;
    if(closetOpen){if(barberOpen||glamOpen&&guyGlamTab())bview-=dx*.012;else if(!drawing()&&!(ct.on&&!ct.sub)&&!(glamOpen&&ctab!=='hair'))player.face+=dx*.012;}else{cam.yaw-=dx*.006;cam.pitch=Math.min(1.25,Math.max(-.15,cam.pitch+dy*.004));fadeHint();}}});
const endPtr=e=>{pinchUp(e);parlorUp(e);bakeryUp(e);garageUp(e);sandUp(e);beautyUp(e);if(e.pointerId===brush.id){brush.id=null;brush.last=null;savePaint();}if(e.pointerId===joy.id){joy.id=null;joy.x=joy.y=0;joyEl.style.display='none';}if(e.pointerId===look.id)look.id=null;};
canvas.addEventListener('pointerup',endPtr);canvas.addEventListener('pointercancel',endPtr);canvas.addEventListener('lostpointercapture',endPtr);
canvas.addEventListener('wheel',e=>{zoomBy(Math.exp(Math.max(-60,Math.min(60,e.deltaY))*.004));e.preventDefault();},{passive:false});
canvas.addEventListener('contextmenu',e=>e.preventDefault());
$('#jump').addEventListener('pointerdown',e=>{e.preventDefault();jump();});
function jump(){if(closetOpen)return;if(skyJump())return;// hang gliding or skydiving: jump out of the plane, or pull (26i-sky-sports.js)
  if(heliJump())return;// in the helicopter: lift off (26h-helicopter.js)
  if(flyJump())return;// on a flying ride: take off (24h-flying.js)
  if(window.__daddy?.jump())return;// DADDY POWERS (27-daddy-powers.js): does nothing once that file is gone
  if(jpJump())return;// bouncing on a trampoline: bounce higher next time (26e-jump-park.js)
  if(skateParkJump())return;// on wheels at the skate park: an ollie, or hop off a rail (24k-skate-park.js)
  if(player.onGround){player.vy=6.2;player.onGround=false;sfx('jump');}}
let hintFaded=false;function fadeHint(){if(hintFaded)return;hintFaded=true;setTimeout(()=>$('#hint').style.opacity=0,2500);setTimeout(()=>$('#hint').style.display='none',3200);}
if(!isTouch)$('#hint').innerHTML='Walk with W A S D or the arrow keys.<br>Drag to look around. Space to jump.';

// ---- src/17b-zoom.js ----
/* ================= ZOOM ================= */
// Pinch with two fingers, scroll the mouse wheel, or tap the ➕ and ➖ buttons on the left to zoom in and out.
// Walking around, that moves the camera closer or further (cam.dist). At the pet parlor and the bakery it changes how
// far back the close-up camera stands (ZOOM.k), so you can always back away if your pet or cake is too close.
const ZOOM={k:Math.min(2.6,Math.max(.7,+SAVE.zoomK||1)),min:.7,max:2.6},PLAY_MIN=2.5,PLAY_MAX=14;
const zoomEl=$('#zoomCtl');
function zoomWhere(){if(parlorOpen||bakeryOpen||garageOpen||sandOpen)return 'station';if(!closetOpen)return 'play';return null;}
let zoomSaveT=0;
function zoomBy(f){const w=zoomWhere();
  if(w==='play')cam.dist=Math.min(PLAY_MAX,Math.max(PLAY_MIN,cam.dist*f));
  else if(w==='station'){ZOOM.k=Math.min(ZOOM.max,Math.max(ZOOM.min,ZOOM.k*f));clearTimeout(zoomSaveT);zoomSaveT=setTimeout(()=>{SAVE.zoomK=+ZOOM.k.toFixed(2);persist();},800);}}
// how far the parlor and bakery cameras stand back: a bit further on a tall phone, where the panel covers the bottom
const stationZoom=()=>ZOOM.k*(innerWidth>innerHeight*1.25?1:1.2);

/* two-finger pinch */
const pinch={pts:new Map(),d:0,on:false};
const pinchDist=()=>{const [a,b]=[...pinch.pts.values()];return Math.hypot(a[0]-b[0],a[1]-b[1]);};
function pinchDown(e){if(e.pointerType==='mouse')return false;pinch.pts.set(e.pointerId,[e.clientX,e.clientY]);
  if(pinch.pts.size!==2||!zoomWhere())return false;
  // a second finger: stop walking, looking around or scrubbing, and zoom instead
  pinch.on=true;pinch.d=pinchDist();joy.id=null;joy.x=joy.y=0;joyEl.style.display='none';look.id=null;pcam.id=null;bcam.id=null;
  if(rub.id!==null){rub.id=null;persist();renderMeters();}return true;}
function pinchMove(e){if(!pinch.pts.has(e.pointerId))return false;pinch.pts.set(e.pointerId,[e.clientX,e.clientY]);if(!pinch.on)return false;
  const d=pinchDist();if(d>10&&pinch.d>10)zoomBy(pinch.d/d);pinch.d=d;return true;}
function pinchUp(e){pinch.pts.delete(e.pointerId);if(pinch.pts.size<2)pinch.on=false;}

/* the ➕ ➖ buttons: tap to zoom a step, or hold to keep zooming */
let zoomHold=null;
function zoomPress(f){zoomBy(f);sfx('pop');clearInterval(zoomHold);let n=0;zoomHold=setInterval(()=>{if(++n>3)zoomBy(Math.pow(f,.35));},90);}
const zoomStop=()=>{clearInterval(zoomHold);zoomHold=null;};
[['#zoomIn',1/1.25],['#zoomOut',1.25]].forEach(([id,f])=>{const b=$(id);b.addEventListener('pointerdown',e=>{e.preventDefault();e.stopPropagation();zoomPress(f);});
  ['pointerup','pointercancel','pointerleave'].forEach(t=>b.addEventListener(t,zoomStop));});
let zoomShown=null;
function zoomTick(){const s=started&&!!zoomWhere();if(s!==zoomShown){zoomShown=s;zoomEl.classList.toggle('show',s);if(!s)zoomStop();}}
// ---- src/17c-skateboard.js ----
/* ================= 🛹 SKATEBOARD =================
   The skateboard is a guy's extra (14c-guy.js). It is carried in the hand while walking around, and:
   - it is put away (hidden) during sports and other hands-on games, so it's not in the way of the bat or the ball,
     and while you wear roller skates (14f-roller-skates.js), since you're already on wheels.
   - tap 🛹 Ride in the moves wheel to hop on and skate around town: faster than walking, you keep rolling when
     you let go of the joystick, you lean into turns, and JUMP does an ollie. Tap 🛹 Hop off to carry it again. */
const SK={on:false,v:0,dir:0,air:false,lean:0};
const hasBoard=()=>!!(SAVE.look&&SAVE.look.extras&&SAVE.look.extras.skateboard);
// busy with something that needs your hands (or a seat): the board goes away until you're done
const handsBusy=()=>!!SP.mode||garageOpen||sandOpen||bakeryOpen||parlorOpen||barnOpen||glamOpen||barberOpen||ck.on||pc.on||ct.on;
// also put away while riding a horse or a bike (17d-bicycle.js)
const boardBusy=()=>handsBusy()||!!barnRide||BIKE.on;
const skateBoost=()=>SK.on?1.55:1;
const skateActs=()=>hasBoard()?[['skate','🛹',SK.on?'Hop off':'Ride']]:[];
function startSkate(){if(SK.on||!hasBoard()||closetOpen||!started||boardBusy())return;SK.on=true;SK.v=0;SK.dir=player.face;av.emote=null;
  if(player.onGround){player.vy=3.2;player.onGround=false;}sfx('jump');renderActions();did('skate');
  if(!SAVE.skated){SAVE.skated=1;persist();toast('🛹 Skate anywhere in town! Tap JUMP to ollie, tap 🛹 Hop off to carry it again');}}
function stopSkate(quiet){if(!SK.on)return;SK.on=false;SK.v=0;av.skating=false;av.g.rotation.z=0;if(av.deck)av.deck.rotation.x=0;if(!quiet)sfx('pop');renderActions();}
function toggleSkate(){if(SK.on)stopSkate();else startSkate();}
// the stance: turn the hips side-on (feet across the board), turn the chest and head back toward where you're going
function skatePose(a,tgt,sp,air,t){const push=a.skating&&!air&&sp>.05&&a.skatePush;
  tgt.sy=-1.35;tgt.st=.75;tgt.hy=.55;tgt.lean=.06;tgt.hd=0;tgt.spin=0;
  tgt.l0=tgt.l1=-.32;tgt.k0=tgt.k1=.62;tgt.an=-.25;tgt.l0z=-.2;tgt.l1z=.2;tgt.bob=-.07;
  tgt.a0x=tgt.a1x=0;tgt.a0z=-.9-Math.sin(t*2.3)*.12;tgt.a1z=.9-Math.sin(t*2.3+1)*.12;tgt.e0=tgt.e1=-.35;
  // push off with the back foot now and then while speeding up
  if(push){const k=Math.max(0,Math.sin(t*5));tgt.l1=-.32+k*.6;tgt.k1=.62-k*.4;}
  if(air){tgt.k0=tgt.k1=1.1;tgt.l0=tgt.l1=-.7;tgt.bob=-.12;tgt.a0z=-1.4;tgt.a1z=1.4;}}
anims.push((t,dt)=>{if(!started||!av)return;
  // the board in the hand: hidden while riding it, during games that need your hands, and while wearing roller skates
  if(SK.on&&(!hasBoard()||closetOpen||boardBusy()))stopSkate(true);
  if(av.board)av.board.visible=!SK.on&&!boardBusy()&&!av.rollers;
  if(av.deck)av.deck.visible=SK.on;
  av.skating=SK.on;av.skatePush=SK.pushing;if(!SK.on){if(av.g.rotation.z)av.g.rotation.z=0;return;}
  // keep rolling after you let go of the joystick, slowing down little by little
  let ix=joy.x,iy=joy.y;if(keys.KeyA||keys.ArrowLeft)ix-=1;if(keys.KeyD||keys.ArrowRight)ix+=1;if(keys.KeyW||keys.ArrowUp)iy-=1;if(keys.KeyS||keys.ArrowDown)iy+=1;
  const p=player.pos,pushing=Math.hypot(ix,iy)>.08;SK.pushing=pushing&&player.speed>SK.v+.05;
  const turn=((player.face-SK.dir+Math.PI)%(Math.PI*2)+Math.PI*2)%(Math.PI*2)-Math.PI;
  if(SKP.on){SK.v=player.speed;SK.dir=player.face;}// at the skate park, 24k-skate-park.js does the rolling
  else if(pushing){SK.v=player.speed;SK.dir=player.face;}
  else if(SK.v>.15){SK.v*=Math.pow(.45,dt);const old=p.clone();p.x+=Math.sin(SK.dir)*SK.v*dt;p.z+=Math.cos(SK.dir)*SK.v*dt;collide(p);
    if(groundAt(p.x,p.z)-p.y>.45||p.distanceTo(old)<SK.v*dt*.3){p.x=old.x;p.z=old.z;SK.v=0;}player.speed=SK.v;}
  else SK.v=0;
  // lean into turns, pop the nose up for an ollie, clack when you land
  SK.lean+=(Math.max(-.3,Math.min(.3,-turn/Math.max(dt,.001)*.012))-SK.lean)*Math.min(1,dt*6);
  av.g.position.copy(p);av.g.position.y+=.1;av.g.rotation.z=SK.lean;
  const air=!player.onGround;if(av.deck)av.deck.rotation.x+=((air&&player.vy>0?-.28:0)-av.deck.rotation.x)*Math.min(1,dt*14);
  if(SK.air&&!air)tone(170,.06,'square',.06);SK.air=air;});
// ---- src/17d-bicycle.js ----
/* ================= 🚲 BICYCLE and 🐎 HORSE (rides from the moves wheel) =================
   - 🚲 Bike: an extra you buy in the shop with ⭐ stars, in the closet's Extras like in the 2D studio (index.html).
     While you wear it, tap 🚲 Bike in the moves wheel to hop on and pedal around town: faster than walking,
     you sit on the saddle with your hands on the grips and your feet pedaling the cranks round (faster the faster you go),
     you coast with the pedals still when you let go of the joystick, the bike leans and the handlebars turn in turns,
     a foot comes down when you stop, and JUMP does a little bunny hop.
     Tap 🚲 Hop off to walk again.
   - 🐎 Horse: once you adopt a horse (or a pony, unicorn, donkey... any animal you can ride) at the Happy Barn, tap it in
     the moves wheel and it trots over to you wherever you are, so you can ride it around town (24d-barn.js does the riding).
     Before you have one, the button shows the way to the barn.
   Only barn animals made for riding can be ridden (never pets like dogs and cats).
   Both are put away during sports, contests and other hands-on games, the same as the skateboard. */
const BIKE={on:false,v:0,dir:0,lean:0,crank:0,spin:0,steer:0,stand:0,still:0,pedal:false,air:false,col:''};
const bikeBoost=()=>BIKE.on?1.7:1;
// "rideActs" are added to the front of the moves wheel (19-ui-closet.js); the horse one comes from the barn
const hasBike=()=>!!(SAVE.look&&SAVE.look.extras&&SAVE.look.extras.bicycle)&&owns('look:bicycle');
const RIDE_ACTS=[()=>hasBike()?[['bike','🚲',BIKE.on?'Hop off':'Bike']]:[]];
// in the closet's Extras (girls and guys), and in the shop for ⭐ stars; its color is the bike's color
EXTRAS.push(['bicycle','🚲','Bicycle','#ff6fae']);GUY_EXTRAS.push(['bicycle','🚲','Bicycle','#3a8dff']);
SHOP.push({k:'look:bicycle',tab:'outfits',e:'🚲',n:'Bicycle',stars:10,d:'Your own bike! Find it in Extras, then tap 🚲 Bike with your moves to ride it around town.'});
const rideActs=()=>RIDE_ACTS.flatMap(f=>f());

/* ---------- the bike model: chunky and cute like the rest of the town ---------- */
// makeBike() builds one; friends online get their own (26c-friends-see.js)
// It is a grown-up size so a rider's legs reach the pedals: the seat slides up or down to fit whoever rides it,
// the handlebars and front wheel turn when you steer, and the pedals stay flat under your feet as the cranks go round.
const BIKE_S=1.2,BIKE_GEAR=2.4;// how big the bike is, and how many times the back wheel turns for each turn of the pedals
function makeBike(){const g=new THREE.Group();g.visible=false;scene.add(g);
  // everything sits in "in": scaled up, and moved forward so the seat is right under the rider's hips
  const inn=new THREE.Group();inn.scale.setScalar(BIKE_S);inn.position.z=.17;g.add(inn);
  const frame=phys('#ff6fae',{roughness:.3,clearcoat:1}),tire=std('#2d2d3a',{roughness:.9}),rim=phys('#e8e8ee',{metalness:.7,roughness:.25}),
    seat=std('#3a2a30',{roughness:.6}),grip=std('#ffffff',{roughness:.5}),bask=std('#d9a066',{roughness:.9});
  const R=.27,WB=.47,BB=[0,.3,.02];// wheel radius, half the wheelbase, where the pedals turn
  // a tube from one point to another
  const tube=(a,b,r=.022,m=frame,par=inn)=>{const A=new THREE.Vector3(...a),B=new THREE.Vector3(...b),d=B.clone().sub(A),t=M(cyl(r,r,d.length(),10),m,0,0,0,par);
    t.position.copy(A).add(B).multiplyScalar(.5);t.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());return t;};
  const wheel=(par,x,y,z)=>{const w=new THREE.Group();w.position.set(x,y,z);par.add(w);
    const ti=M(new THREE.TorusGeometry(R-.025,.03,10,32),tire,0,0,0,w);ti.rotation.y=Math.PI/2;
    const ri=M(new THREE.TorusGeometry(R-.06,.012,6,28),rim,0,0,0,w,false);ri.rotation.y=Math.PI/2;
    for(let i=0;i<6;i++){const s=M(cyl(.005,.005,(R-.06)*2,4),rim,0,0,0,w,false);s.rotation.x=i*Math.PI/6;}
    M(cyl(.03,.03,.06,12),rim,0,0,0,w,false).rotation.z=Math.PI/2;return w;};
  const back=[0,R,-WB],front=[0,R,WB],seatP=[0,.6,-.14],head=[0,.66,.36],bb=BB;
  tube(back,bb);tube(back,seatP,.02);tube(bb,[0,.62,-.13],.026);tube(bb,head,.028);tube([0,.6,-.12],[0,.64,.34],.024);
  // the seat on its post: slides up and down to fit the rider (bikeRide)
  const seatG=new THREE.Group();inn.add(seatG);
  tube([0,.5,-.125],[0,.64,-.145],.016,rim,seatG);M(new RoundedBoxGeometry(.13,.04,.2,3,.018),seat,0,.635,-.15,seatG);
  // the front: fork, front wheel, handlebars and basket all turn together around the head tube
  const axis=new THREE.Vector3(0,.66-R,-(.36-WB)).normalize(),steer=new THREE.Group();steer.position.set(...head);inn.add(steer);
  const rel=p=>[p[0]-head[0],p[1]-head[1],p[2]-head[2]];
  const wheels=[wheel(inn,...back),wheel(steer,...rel(front))];
  tube(rel(head),rel(front),.022,frame,steer);tube(rel(head),rel([0,.93,.31]),.024,frame,steer);
  M(cyl(.018,.018,.46,10),frame,...rel([0,.93,.31]),steer).rotation.z=Math.PI/2;
  const grips=[];for(const x of [-.21,.21]){M(cyl(.024,.024,.08,10),grip,...rel([x,.93,.31]),steer).rotation.z=Math.PI/2;const o=new THREE.Object3D();o.position.set(...rel([x,.93,.31]));steer.add(o);grips.push(o);}
  // a little basket on the front with flowers in it
  M(new RoundedBoxGeometry(.24,.13,.16,2,.02),bask,...rel([0,.85,.47]),steer);
  for(const [x,c] of [[-.06,'#ff8fc8'],[0,'#ffd23f'],[.06,'#8fd8ff']])M(sph(.03,8,6),std(c),...rel([x,.93,.47]),steer,false);
  // the cranks go round with your feet, and each pedal stays flat under your shoe
  const crank=new THREE.Group();crank.position.set(...bb);inn.add(crank);M(cyl(.06,.06,.02,16),rim,0,0,0,crank).rotation.z=Math.PI/2;
  const pedals=[];for(const s of [-1,1]){M(box(.016,.15,.03),rim,s*.05,-s*.06,0,crank,false);const pd=new THREE.Group();pd.position.set(s*.09,-s*.13,0);crank.add(pd);M(box(.08,.02,.05),tire,0,0,0,pd,false);pedals.push(pd);}
  return {g,inn,wheels,crank,pedals,grips,seatG,steer,axis,frame,R:R*BIKE_S,crankR:.13*BIKE_S,seatTop:.655*BIKE_S};}
const BK=makeBike();

/* ---------- riding it for real: bikeRide() puts the rider's body on the bike every frame ----------
   Hips on the saddle, hands on the grips, the balls of the feet on the pedals as they go round (the legs bend to
   follow them exactly), a little rock of the hips with each push, the body leaning forward more the faster you go,
   and when you stop, one foot comes down to the ground and the bike tips onto it.
   s is the ride: {crank, lean, steer, stand (0..1 foot down), air, v}. Used for you and for friends online. */
const BKR={v:new THREE.Vector3(),w:new THREE.Vector3(),u:new THREE.Vector3(),c:new THREE.Vector3(),n:new THREE.Vector3(),z:new THREE.Vector3(),
  m:new THREE.Matrix4(),inv:new THREE.Matrix4(),mh:new THREE.Matrix4(),ms:new THREE.Matrix4(),qp:new THREE.Quaternion(),q:new THREE.Quaternion(),q2:new THREE.Quaternion(),e:new THREE.Euler(),
  pv:[new THREE.Vector3(),new THREE.Vector3()],gv:[new THREE.Vector3(),new THREE.Vector3()],cc:new THREE.Vector3(),gr:new THREE.Vector3()};
// two-bone reach (thigh+shin or upper arm+forearm): bend toward "pole", returns the root's local turn and how much the middle joint bends
function reach2(J,T,a,b,pole,qParent,bendSign,out){const t=BKR.v.copy(T).sub(J);let d=t.length();d=Math.min((a+b)*.999,Math.max(Math.abs(a-b)+.001,d));t.normalize();
  const cb=Math.min(1,Math.max(-1,(a*a+d*d-b*b)/(2*a*d))),cg=Math.min(1,Math.max(-1,(a*a+b*b-d*d)/(2*a*b))),be=Math.acos(cb);
  const p=BKR.w.copy(pole).addScaledVector(t,-pole.dot(t)).normalize();
  const u=BKR.u.copy(t).multiplyScalar(Math.cos(be)).addScaledVector(p,Math.sin(be)).normalize();
  const c=BKR.c.copy(p).addScaledVector(u,-p.dot(u)).normalize();
  const n=bendSign>0?BKR.n.crossVectors(c,u):BKR.n.crossVectors(u,c);
  const ny=BKR.z.copy(u).negate(),nz=new THREE.Vector3().crossVectors(n,ny);
  BKR.m.makeBasis(n,ny,nz);out.q.setFromRotationMatrix(BKR.m);out.q.premultiply(BKR.q2.copy(qParent).invert());out.bend=bendSign*(Math.PI-Math.acos(cg));return out;}
const KNEE_POLE=[new THREE.Vector3(-.15,.3,1),new THREE.Vector3(.15,.3,1)],ELBOW_POLE=[new THREE.Vector3(-.6,-1,-.7),new THREE.Vector3(.6,-1,-.7)];
const BK_RX=new THREE.Vector3(1,0,0);
function bikeRide(a,bk,s,dt){if(!a||!a.legs||!bk)return;
  a.bikeW=Math.min(1,(a.bikeW||0)+dt*4);const W=a.bikeW;
  // where the bike's pedals, grips and cranks are, seen from the rider's body
  bk.steer.quaternion.setFromAxisAngle(bk.axis,s.steer||0);
  for(const p of bk.pedals)p.rotation.x=0;
  bk.g.updateMatrixWorld(true);a.g.updateMatrix();BKR.inv.copy(a.g.matrix).invert();
  const loc=(o,v)=>o.getWorldPosition(v).applyMatrix4(BKR.inv);
  const cc=loc(bk.crank,BKR.cc);
  const L=a.legs,A=a.arms,th=-L[0].kn.position.y,sh=-L[0].an.position.y,leg=th+sh;
  // the saddle goes to the height where your leg is nearly straight at the bottom of each push
  const fb=.15,ay=.014+.062*Math.cos(fb)+.045*Math.sin(fb),az=.062*Math.sin(fb)-.045*Math.cos(fb);
  const dx=Math.abs(bk.pedals[1].position.x*BIKE_S)-Math.abs(L[1].hp.position.x),dz=cc.z+az;
  const sitY=cc.y-bk.crankR+ay+Math.sqrt(Math.max(.01,(leg*.94)**2-dz*dz-dx*dx))-L[0].hp.position.y;
  bk.seatG.position.y=(sitY-.0975-bk.seatTop)/BIKE_S;
  // one foot down on the ground when stopped (the left one), the bike tipped onto that side
  const st=s.stand||0;let foot=null;
  if(st>.001){const P=BKR.gr.set(-.26,0,.14).applyMatrix4(a.g.matrix);P.y=a.g.position.y-(s.groundDrop||0)+.07;foot=P.applyMatrix4(BKR.inv);}
  const standY=foot?foot.y+Math.sqrt(Math.max(.01,(leg*.97)**2-(Math.abs(foot.x)-Math.abs(L[0].hp.position.x))**2-(foot.z-.1)**2))-L[0].hp.position.y:sitY;
  const v=s.v||0,ped=s.pedal?1:0;
  const hy=sitY+(s.air?.035:0)+(Math.min(sitY,standY)-sitY)*st,hz=.1*st;
  const rock=Math.sin(s.crank||0)*.035*ped*(1-st);
  const lean=(.42+Math.min(.12,v*.014))*(1-st)+.24*st;
  // hips and back
  const H=a.hips,SP=a.spine;
  H.position.set(H.position.x*(1-W),H.position.y+(hy-H.position.y)*W,H.position.z+(hz-H.position.z)*W);
  H.quaternion.slerp(BKR.q.setFromEuler(BKR.e.set(0,0,rock)),W);SP.quaternion.slerp(BKR.q.setFromEuler(BKR.e.set(lean,0,-rock*.6)),W);
  a.head.rotation.x=-lean*.55*W;a.head.rotation.z=-(s.lean||0)*.5*W;
  H.updateMatrix();SP.updateMatrix();BKR.mh.copy(H.matrix);BKR.ms.multiplyMatrices(BKR.mh,SP.matrix);
  const out={q:new THREE.Quaternion(),bend:0};
  // legs: balls of the feet on the pedals, toes dipping a little at the bottom and back of each turn
  BKR.qp.setFromRotationMatrix(BKR.mh);
  for(let i=0;i<2;i++){const l=L[i],sx=l.sx,pd=bk.pedals[sx<0?0:1];
    const P=loc(pd,BKR.pv[i]),psi=Math.atan2(P.z-cc.z,P.y-cc.y);let fp=.15-.15*Math.sin(psi);
    pd.rotation.x=fp-bk.crank.rotation.x;
    const T=BKR.gv[i].set(P.x,P.y+.014+.062*Math.cos(fp)+.045*Math.sin(fp),P.z+.062*Math.sin(fp)-.045*Math.cos(fp));
    if(foot&&sx<0){T.lerp(foot,st);fp*=1-st;}
    const J=l.hp.position.clone().applyMatrix4(BKR.mh);
    reach2(J,T,th,sh,KNEE_POLE[sx<0?0:1],BKR.qp,1,out);
    l.hp.quaternion.slerp(out.q,W);l.kn.quaternion.slerp(BKR.q.setFromAxisAngle(BK_RX,out.bend),W);
    // the foot's turn in the body = hips * hip * knee * ankle, so pick the ankle turn that gives the wanted toe dip
    BKR.q2.copy(BKR.qp).multiply(l.hp.quaternion).multiply(l.kn.quaternion).invert();l.an.quaternion.slerp(BKR.q2.multiply(BKR.q.setFromAxisAngle(BK_RX,fp)),W);}
  // arms: hands on the grips, elbows a little bent and pointing out
  BKR.qp.setFromRotationMatrix(BKR.ms);
  for(let i=0;i<2;i++){const ar=A[i],sx=ar.sx,g=bk.grips[sx<0?0:1];
    const T=loc(g,BKR.gv[i]),J=ar.sh.position.clone().applyMatrix4(BKR.ms);
    reach2(J,T,-ar.el.position.y,-ar.hand.position.y+.04*ar.hand.scale.x,ELBOW_POLE[sx<0?0:1],BKR.qp,-1,out);
    ar.sh.quaternion.slerp(out.q,W);ar.el.quaternion.slerp(BKR.q.setFromAxisAngle(BK_RX,out.bend),W);}}
// back to normal when you hop off
function bikeUnride(a){if(!a||!a.legs)return;a.bikeW=0;a.hips.position.z=0;a.head.rotation.x=0;
  for(const l of a.legs){l.hp.rotation.y=0;l.kn.rotation.y=l.kn.rotation.z=0;l.an.rotation.y=l.an.rotation.z=0;}
  for(const r of a.arms){r.sh.rotation.y=0;r.el.rotation.y=0;}}
// how the bike moves for one step: pedals turn with the back wheel while you pedal, spin free when you coast
// (and come round level, ready for the next push), the front wheel steers and you lean into turns like a real bike,
// and after you stop for a moment a foot comes down. Shared with friends online (26c-friends-see.js).
function bikeStep(s,bk,dt,v,pedal,yawRate,ground){
  s.v=v;s.pedal=pedal;s.spin+=v*dt/bk.R;for(const w of bk.wheels)w.rotation.x=s.spin;
  s.still=v<.15&&!pedal&&ground?(s.still||0)+dt:0;
  if(pedal)s.crank+=dt*v/bk.R/BIKE_GEAR;
  else{const want=s.still>.25?-Math.PI/2-.5:Math.PI/2,k=Math.PI*(s.still>.25?2:1);const tgt=want+Math.round((s.crank-want)/k)*k;s.crank+=(tgt-s.crank)*Math.min(1,dt*3);}
  bk.crank.rotation.x=s.crank;
  const lean=-Math.max(-.35,Math.min(.35,Math.atan(v*yawRate/9.8)*.8));
  s.stand=(s.stand||0)+((s.still>.25?1:0)-(s.stand||0))*Math.min(1,dt*(s.still>.25?3:8));
  s.lean+=((lean+.1*s.stand)-s.lean)*Math.min(1,dt*6);
  s.steer+=(Math.max(-.5,Math.min(.5,yawRate*.35/(1+v*.4)))-s.steer)*Math.min(1,dt*8);}

function bikeBusy(){return closetOpen||!started||handsBusy()||!!barnRide||!hasBike();}
function startBike(){if(BIKE.on||bikeBusy())return;if(SK.on)stopSkate(true);BIKE.on=true;BIKE.v=0;BIKE.dir=player.face;BIKE.stand=1;BIKE.still=1;BIKE.crank=-Math.PI/2-.5;av.emote=null;av.bikeW=0;
  sfx('pop');tone(880,.05,'triangle',.08);tone(1180,.06,'triangle',.08,.08);// ring ring!
  renderActions();did('bike');
  if(!SAVE.biked){SAVE.biked=1;persist();toast('🚲 Ride your bike anywhere in town! Tap JUMP to hop, tap 🚲 Hop off to walk');}}
function stopBike(quiet){if(!BIKE.on)return;BIKE.on=false;BIKE.v=0;av.biking=false;av.g.rotation.z=0;bikeUnride(av);BK.g.visible=false;if(!quiet)sfx('pop');renderActions();}
function toggleBike(){if(BIKE.on)stopBike();else startBike();}
// the walking pose while bikeRide() takes over (it sets the arms, legs, hips and back exactly every frame)
function bikePose(a,tgt,sp,air,t){tgt.lean=.42;tgt.sy=0;tgt.st=0;tgt.hy=0;tgt.hd=0;tgt.spin=0;tgt.l0z=tgt.l1z=0;tgt.hx=0;tgt.hr=0;tgt.sz=0;tgt.tilt=0;
  tgt.bob=-(a.hip-(.66+a.legX));tgt.l0=tgt.l1=-1.05;tgt.k0=tgt.k1=1.15;tgt.an=.1;tgt.a0x=tgt.a1x=-1.05;tgt.a0z=.12;tgt.a1z=-.12;tgt.e0=tgt.e1=-.35;}
anims.push((t,dt)=>{if(!started||!av)return;
  if(BIKE.on&&bikeBusy())stopBike(true);
  av.biking=BIKE.on;
  // the bike is the color you picked for it in the closet
  const col=hasBike()&&SAVE.look.extras.bicycle;if(col&&BIKE.col!==col){BIKE.col=col;BK.frame.color.set(col);}
  // in the closet it stands next to you so you can see it
  const parked=!BIKE.on&&hasBike()&&closetOpen&&$('#closet').classList.contains('show');BK.g.visible=BIKE.on||parked;
  if(parked){const f=player.face;BK.g.position.set(player.pos.x+Math.cos(f)*.85,player.pos.y,player.pos.z-Math.sin(f)*.85);BK.g.rotation.set(0,f+.5,0);BK.crank.rotation.x=.6;BK.steer.quaternion.identity();}
  if(!BIKE.on)return;
  // keep rolling after you let go of the joystick, slowing down little by little
  let ix=joy.x,iy=joy.y;if(keys.KeyA||keys.ArrowLeft)ix-=1;if(keys.KeyD||keys.ArrowRight)ix+=1;if(keys.KeyW||keys.ArrowUp)iy-=1;if(keys.KeyS||keys.ArrowDown)iy+=1;
  const p=player.pos,pushing=Math.hypot(ix,iy)>.08;
  const turn=((player.face-BIKE.dir+Math.PI)%(Math.PI*2)+Math.PI*2)%(Math.PI*2)-Math.PI;
  if(SKP.on){BIKE.v=player.speed;BIKE.dir=player.face;}// at the skate park, 24k-skate-park.js does the rolling
  else if(pushing){BIKE.v=player.speed;BIKE.dir=player.face;}
  else if(BIKE.v>.15){BIKE.v*=Math.pow(.5,dt);const old=p.clone();p.x+=Math.sin(BIKE.dir)*BIKE.v*dt;p.z+=Math.cos(BIKE.dir)*BIKE.v*dt;collide(p);
    if(groundAt(p.x,p.z)-p.y>.45||p.distanceTo(old)<BIKE.v*dt*.3){p.x=old.x;p.z=old.z;BIKE.v=0;}player.speed=BIKE.v;}
  else BIKE.v=0;
  const sp=pushing?player.speed:BIKE.v;
  bikeStep(BIKE,BK,dt,sp,SKP.on?SKP.push:pushing&&sp>.15,turn/Math.max(dt,.001),player.onGround);
  av.g.position.copy(p);av.g.rotation.z=BIKE.lean;
  BK.g.position.copy(p);BK.g.rotation.set(0,player.face,0);BK.g.rotateZ(BIKE.lean);
  const air=!player.onGround;if(BIKE.air&&!air)tone(220,.05,'triangle',.05);BIKE.air=air;
  bikeRide(av,BK,BIKE,dt);});

/* ---------- 🐎 call your horse (or any ride you own) from anywhere ---------- */
// the animal that comes when you call: the last one you rode, or else your horse, unicorn, pony... (riding: 24d-barn.js)
const STEED_ORDER=['horse','unicorn','pony','donkey','cow','trike','trex','longneck','kitty','crest','pegacorn','ptero','eagle','nova'];
function myRides(){const own=(SAVE.barn&&SAVE.barn.own)||{};return Object.keys(own).filter(k=>FK[k]&&FK[k].ride).sort((a,b)=>(STEED_ORDER.indexOf(a)+99)%99-(STEED_ORDER.indexOf(b)+99)%99);}
function mySteed(){const r=myRides();return r.includes(SAVE.barn&&SAVE.barn.steed)?SAVE.barn.steed:r[0]||null;}
// (the moves wheel is first drawn before the barn file has loaded, so skip the horse button until it has)
// with more than one ride (barn animals plus rides from the shop) the button says 🏇 Rides and opens a list to pick from (24g-mounts.js)
// the button shows a little picture of your real 3D animal once it's drawn (24d-barn.js), or its emoji until then
const ridePic=k=>FTHUMB[k]?`<img class="actPic" src="${FTHUMB[k]}" alt="">`:FK[k].e;
RIDE_ACTS.push(()=>{try{if(barnRide)return [['horse',ridePic(barnRide.k),'Hop off']];if(myRides().length>1)return [['horse','🏇','Rides']];const k=mySteed();return [['horse',k?ridePic(k):'🐎',k?FK[k].n:'Horse']];}catch(e){return [];}});
function toggleHorse(){if(barnRide){sfx('pop');stopRide();return;}
  if(closetOpen||!started)return;
  if(handsBusy()){toast('Finish what you are doing first, then saddle up! 🐎');return;}
  const k=mySteed();
  if(!k){setDest(Z.barn);sfx('star');toast('Adopt a horse at the 🐴 Happy Barn, or get a ride in the 🛍️ shop, then ride it anywhere! 💗');return;}
  if(myRides().length>1){openRides();return;}
  callSteed(k);}
function callSteed(k){if(barnRide||closetOpen||!started||handsBusy()||!BS.own[k]||!FK[k]||!FK[k].ride)return;
  if(BIKE.on)stopBike(true);if(SK.on)stopSkate(true);
  const a=farmAnimal(k),P=player.pos;
  // trot over from the barn with a puff of sparkles
  burst(new THREE.Vector3(P.x,P.y+.6,P.z),'#ffd23f',30,2);
  a.y=0;a.vy=0;a.face=player.face-BZ.rot;a.pos.set(P.x,P.y,P.z);a.g.position.copy(a.pos);
  startRide(a);}
// ---- src/18-sound.js ----
/* ================= SOUND ================= */
let AC=null;function ac(){if(!AC)try{AC=new (window.AudioContext||window.webkitAudioContext)();}catch(e){}return AC;}
function tone(f,dur,type='sine',vol=.15,when=0,slide){const a=ac();if(!a)return;const o=a.createOscillator(),g=a.createGain();o.type=type;o.frequency.setValueAtTime(f,a.currentTime+when);if(slide)o.frequency.exponentialRampToValueAtTime(slide,a.currentTime+when+dur);g.gain.setValueAtTime(0,a.currentTime+when);g.gain.linearRampToValueAtTime(vol,a.currentTime+when+.01);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+when+dur);o.connect(g).connect(a.destination);o.start(a.currentTime+when);o.stop(a.currentTime+when+dur+.05);}
function sfx(k){if(k==='star'){tone(988,.15,'triangle',.18);tone(1319,.25,'triangle',.18,.08);tone(1760,.3,'sine',.12,.16);}
  if(k==='jump')tone(330,.18,'sine',.1,0,660);if(k==='pop')tone(660,.08,'triangle',.12);if(k==='bubble')tone(700+Math.random()*500,.07,'sine',.07,0,1500);if(k==='splash')tone(380,.14,'sine',.05,0,140);if(k==='blow')tone(200,.12,'sawtooth',.02,0,260);if(k==='munch'){tone(160,.06,'square',.05);tone(130,.06,'square',.05,.12);}if(k==='brush')tone(1300,.1,'sine',.07,0,1900);if(k==='tada'){[523,659,784,1047].forEach((f,i)=>tone(f,.4,'triangle',.15,i*.1));}}
const music=new Audio();music.loop=true;music.volume=.45;let musicOn=SAVE.music!==false,curTrack='';
const sndCam=new Audio('../audio/camera.mp3'),sndCheer=new Audio('../audio/stadium-cheer.mp3');sndCheer.volume=.5;
/* ---- your own songs: saved in this browser with IndexedDB ---- */
let myMode=SAVE.musicMode==='mine',mySongs=[],myIdx=-1,myUrl='';
const songDB=(()=>{let p;const open=()=>p||(p=new Promise((ok,no)=>{if(!window.indexedDB)return no(new Error('no idb'));const r=indexedDB.open('brynny3d-songs',1);r.onupgradeneeded=()=>r.result.createObjectStore('songs',{keyPath:'id'});r.onsuccess=()=>ok(r.result);r.onerror=()=>no(r.error);}));
  const tx=(mode,fn)=>open().then(db=>new Promise((ok,no)=>{const t=db.transaction('songs',mode);const st=t.objectStore('songs');const r=fn(st);t.oncomplete=()=>ok(r&&r.result);t.onerror=t.onabort=()=>no(t.error);}));
  return{all:()=>tx('readonly',st=>st.getAll()),put:o=>tx('readwrite',st=>st.put(o)),del:id=>tx('readwrite',st=>st.delete(id))};})();
const playingMine=()=>myMode&&mySongs.length>0;
// 🎶 a place's music can be a list of songs instead of one: PLAYLISTS[name] plays them one after another (starting at a random one)
const PLAYLISTS={},plAt={};
function trackFile(t){const L=PLAYLISTS[t];if(!L||!L.length)return t;plAt[t]=plAt[t]==null?Math.floor(Math.random()*L.length):(plAt[t]+1)%L.length;return L[plAt[t]];}
function placeSrc(t){const L=PLAYLISTS[t];music.loop=!(L&&L.length>1);music.src=`../audio/${trackFile(t)}.mp3`;music.play().catch(()=>{});}
function playMine(i){if(!mySongs.length)return;myIdx=((i%mySongs.length)+mySongs.length)%mySongs.length;if(myUrl)URL.revokeObjectURL(myUrl);myUrl=URL.createObjectURL(mySongs[myIdx].blob);music.loop=mySongs.length===1;music.src=myUrl;music.volume=.45;if(musicOn)music.play().catch(()=>{});renderMusicPanel();}
music.addEventListener('ended',()=>{if(playingMine())playMine(myIdx+1);else if(musicOn&&PLAYLISTS[curTrack])placeSrc(curTrack);});
function setTrack(t){if(t===curTrack)return;curTrack=t;if(!musicOn||playingMine())return;const v0=music.volume;let k=0;const fade=setInterval(()=>{k++;music.volume=Math.max(0,v0*(1-k/8));if(k>=8){clearInterval(fade);if(playingMine())return;music.volume=.45;placeSrc(t);}},40);}
function startMusic(){if(!musicOn)return;if(playingMine())playMine(myIdx<0?0:myIdx);else placeSrc(curTrack||'sparkle-room');}
function renderMusicBtn(){$('#musicBtn').classList.toggle('off',!musicOn);}
const escH=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderMusicPanel(){$('#mOnOff').textContent=musicOn?'🔊 Music is on':'🔇 Music is off';$('#mOnOff').classList.toggle('on',musicOn);
  document.querySelectorAll('[data-mmode]').forEach(b=>b.classList.toggle('on',(b.dataset.mmode==='mine')===myMode));
  $('#mNow').textContent=!musicOn?'Turn music on to hear it':playingMine()&&mySongs[myIdx]?'Now playing: '+mySongs[myIdx].name:myMode?'Upload a song to play it here':'Each place plays its own song';
  $('#mList').innerHTML=mySongs.length?mySongs.map((s,i)=>`<li class="${playingMine()&&i===myIdx?'playing':''}"><button data-mplay="${i}" aria-label="Play">${playingMine()&&i===myIdx&&musicOn?'🎶':'▶'}</button><span class="mname">${escH(s.name)}</span><button data-mdel="${i}" aria-label="Delete">🗑️</button></li>`).join(''):'<li class="mempty">No songs yet. Tap ➕ to add one from your device!</li>';}
function setMusicMode(mine){if(mine===myMode)return;myMode=mine;SAVE.musicMode=mine?'mine':'place';persist();if(!musicOn||!started)return renderMusicPanel();if(playingMine())playMine(myIdx<0?0:myIdx);else placeSrc(curTrack||'sparkle-room');renderMusicPanel();}
songDB.all().then(a=>{mySongs=(a||[]).sort((x,y)=>x.added-y.added);if(myMode&&started&&musicOn&&mySongs.length&&!music.src.startsWith('blob:'))playMine(0);renderMusicPanel();}).catch(()=>{});
$('#musicBtn').onclick=()=>{joy.id=null;joy.x=joy.y=0;joyEl.style.display='none';renderMusicPanel();$('#musicM').classList.add('show');};
$('#mClose').onclick=()=>$('#musicM').classList.remove('show');
$('#musicM').onclick=e=>{if(e.target.id==='musicM')$('#musicM').classList.remove('show');};
$('#mOnOff').onclick=()=>{musicOn=!musicOn;SAVE.music=musicOn;persist();renderMusicBtn();if(musicOn){if(started)startMusic();}else music.pause();renderMusicPanel();};
document.querySelectorAll('[data-mmode]').forEach(b=>b.onclick=()=>{if(b.dataset.mmode==='mine'&&!mySongs.length)toast('Upload a song first! ➕');setMusicMode(b.dataset.mmode==='mine');});
$('#mList').onclick=e=>{const p=e.target.closest('[data-mplay]'),d=e.target.closest('[data-mdel]');
  if(p){const i=+p.dataset.mplay;if(!musicOn){musicOn=true;SAVE.music=true;persist();renderMusicBtn();}if(!myMode){myMode=true;SAVE.musicMode='mine';persist();}playMine(i);}
  else if(d){const i=+d.dataset.mdel,s=mySongs[i];if(!s)return;songDB.del(s.id).catch(()=>{});mySongs.splice(i,1);
    if(myIdx===i){if(mySongs.length)playMine(i);else{myIdx=-1;if(myUrl){URL.revokeObjectURL(myUrl);myUrl='';}if(musicOn&&started)placeSrc(curTrack||'sparkle-room');}}else if(myIdx>i)myIdx--;
    toast('Song removed 🗑️');renderMusicPanel();}};
$('#mFile').onchange=async e=>{const files=[...e.target.files];e.target.value='';let added=0,first=-1;
  for(const f of files){if(f.size>40*1024*1024){toast(`"${f.name}" is too big (max 40 MB)`);continue;}
    const o={id:Date.now().toString(36)+Math.random().toString(36).slice(2,7),name:f.name.replace(/\.[^.]+$/,'').slice(0,60)||'My song',blob:f,added:Date.now()+added};
    try{await songDB.put(o);}catch(err){toast('Could not save that song — your device may be out of space');continue;}
    if(first<0)first=mySongs.length;mySongs.push(o);added++;}
  if(!added)return renderMusicPanel();
  toast(added>1?`Added ${added} songs! 💖`:'Song added! 💖');
  if(!musicOn){musicOn=true;SAVE.music=true;persist();renderMusicBtn();}
  if(!myMode){myMode=true;SAVE.musicMode='mine';persist();}
  if(started)playMine(first);else renderMusicPanel();};
renderMusicBtn();

// ---- src/19-ui-closet.js ----
/* ================= UI ================= */
let toastT;function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toastT);toastT=setTimeout(()=>el.classList.remove('show'),2200);}
let bannerT;function banner(t){const el=$('#banner');el.textContent=t;el.classList.add('show');clearTimeout(bannerT);bannerT=setTimeout(()=>el.classList.remove('show'),1800);}
/* action buttons around the jump button */
const ACTIONS=[['wave','👋','Wave'],['dance','💃','Dance'],['twirl','🌀','Twirl'],['kiss','😘','Kiss'],['clap','👏','Clap'],['cheer','🙌','Cheer'],['flip','🤸','Flip'],['sit','🧘‍♀️','Sit'],['pose','✨','Pose'],['bow','👑','Curtsy'],['magic','🪄','Magic'],['jumpjack','⭐','Star jump']];
// guys get their own buttons: the same ids (so quests and challenges still count them), guy names, and a Flex.
// Avatar.play swaps in the guy animation (GUY_MOVES in 14d-dances.js).
const GUY_ACTIONS=[['wave','👋','Wave'],['dance','🕺','Dance'],['twirl','🌀','Spin'],['kiss','👉','Pew pew'],['clap','👏','Clap'],['cheer','🙌','Cheer'],['flip','🤸','Flip'],['sit','🧘‍♂️','Sit'],['pose','😎','Cool pose'],['bow','🙇‍♂️','Bow'],['flex','💪','Flex'],['magic','🪄','Magic'],['jumpjack','⭐','Star jump']];
let actPage=0;const PER=4;
// ACT_HOOKS: modules outside game.js (like christmas.js) add their own buttons: {acts:()=>[[id,emoji,label]], run:id=>true if it was theirs}
const ACT_HOOKS=[];const hookActs=()=>ACT_HOOKS.flatMap(h=>{try{return h.acts()||[];}catch(e){return [];}});
const allActs=()=>hookActs().concat(ballActs()).concat(skateActs()).concat(rideActs(),isGuy(SAVE.look)?GUY_ACTIONS:ACTIONS).concat(SHOP.filter(s=>s.tab==='moves'&&owns(s.k)).map(s=>[s.k.slice(5),s.e,s.lab]));
function renderActions(){const el=$('#actions'),A=allActs();const pages=Math.ceil(A.length/PER);if(actPage>=pages)actPage=0;const list=A.slice(actPage*PER,actPage*PER+PER);
  const R=112,cx=66,cy=72,pos=(deg,half)=>{const a=deg*Math.PI/180;return `right:calc(env(safe-area-inset-right) + ${(cx-Math.cos(a)*R-half).toFixed(0)}px);bottom:calc(env(safe-area-inset-bottom) + ${(cy+Math.sin(a)*R-half).toFixed(0)}px)`;};
  el.innerHTML=list.map((a,i)=>`<button class="act pop" data-act="${a[0]}" style="${pos([165,135,105,75][i],27)}">${a[1]}<span>${a[2]}</span></button>`).join('')+
   `<button class="act more" data-more="1" style="${pos(196,22)}" aria-label="More moves">⋯<span>${actPage+1}/${pages}</span></button>`;}
$('#actions').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.more){actPage=(actPage+1)%Math.ceil(allActs().length/PER);renderActions();sfx('pop');return;}if(owns('move:'+b.dataset.act))doMove(b.dataset.act);else doAction(b.dataset.act);});
const heartTex={};function floaties(pos,emoji,n=6){if(!heartTex[emoji])heartTex[emoji]=canvasTex(64,64,(x)=>{x.font='52px serif';x.textAlign='center';x.textBaseline='middle';x.fillText(emoji,32,36);});
  for(let i=0;i<n;i++){const s=sprite(heartTex[emoji],.2,.2);s.position.copy(pos).add(new THREE.Vector3((Math.random()-.5)*.4,Math.random()*.2,(Math.random()-.5)*.4));scene.add(s);const v=new THREE.Vector3((Math.random()-.5)*.6,.9+Math.random()*.6,(Math.random()-.5)*.6);let life=1.4+Math.random()*.5;
    const f=(t,dt)=>{life-=dt;s.position.addScaledVector(v,dt);s.material.opacity=Math.min(1,life);s.scale.setScalar(.2+(1.6-life)*.06);if(life<=0){scene.remove(s);s.material.dispose();anims.splice(anims.indexOf(f),1);}};anims.push(f);}}
function headPos(){return av.head.getWorldPosition(new THREE.Vector3());}
function doAction(id,picked){if(closetOpen||!started)return;const P=player.pos;
  for(const h of ACT_HOOKS)if(h.run(id))return;
  if(id==='kick'){kickBall();return;}
  if(id==='skate'){toggleSkate();return;}
  if(id==='bike'){toggleBike();return;}
  if(id==='horse'){toggleHorse();return;}
  if(id==='heli'){heliCall();return;}// 🚁 26h-helicopter.js
  if(SK.on)stopSkate(true);
  if(BIKE.on)stopBike(true);
  if(id==='dance'&&!picked){openDances();return;}
  // a dance picked from the Dance list counts as dancing for quests and challenges
  const dancing=DANCE_IDS.has(id);questEvent('act',dancing?'dance':id);const G=isGuy(av.look);
  if(id==='flip'){if(!player.onGround)return;player.vy=7.6;player.onGround=false;sfx('jump');}
  if(id==='cheer'||id==='jumpjack'){if(player.onGround){player.vy=5;player.onGround=false;}}
  if(id==='jumpjack'){av.play('cheer');burst(new THREE.Vector3(P.x,P.y+1.2,P.z),'#ffd23f',30,2.5,.18);return;}
  av.play(id);
  if(id==='twirl')burst(new THREE.Vector3(P.x,P.y+1,P.z),G?'#8fd8ff':'#ffb3e0',30,2,.18);
  if(id==='kiss')setTimeout(()=>floaties(headPos(),G?'😎':'💖',G?4:7),G?250:650);
  if(id==='flex')setTimeout(()=>floaties(headPos(),'💪',4),400);
  if(id==='breakdance')setTimeout(()=>burst(new THREE.Vector3(P.x,P.y+.4,P.z),'#8fd8ff',40,2.5,.16),1900);
  if(dancing)setTimeout(()=>floaties(headPos(),'🎵',4),300);
  if(id==='clap')setTimeout(()=>floaties(headPos(),'✨',4),300);
  if(id==='magic')for(let k=0;k<4;k++)setTimeout(()=>burst(new THREE.Vector3(P.x,P.y+1.4,P.z),rnd(['#ff8fc8','#ffd23f','#8fd8ff','#c6a6ff']),36,3,.2),k*350);
  // townspeople never copy your moves: only the one closest to you (and only if they're right there) waves back or claps for you
  if(dancing||id==='wave'){let fc=null,bd=4;for(const f of FRIENDS){const d=f.pos.distanceTo(P);if(d<bd){bd=d;fc=f;}}
    if(fc&&fc.cool<=0){fc.cool=14;setTimeout(()=>{fc.play(id==='wave'?'wave':'clap');friendBubble(fc,id==='wave'?`Hi ${SAVE.name||'friend'}! 👋`:'Nice moves! 👏');},300+Math.random()*500);}}
  if(myPet()&&myPet().pos.distanceTo(P)<5&&(dancing||id==='cheer'||id==='magic'))myPet().happy=1.5;}
renderActions();
function updateStars(){did('stars');}
(SAVE.stars||[]).forEach(i=>{if(STARS[i]){STARS[i].got=true;STARS[i].m.visible=false;}});updateStars();

/* photo */
let wantPhoto=false;$('#photoBtn').onclick=()=>{wantPhoto=true;};
function takePhoto(){questEvent('act','photo');const url=canvas.toDataURL('image/png');$('#flash').style.transition='none';$('#flash').style.opacity=.9;requestAnimationFrame(()=>{$('#flash').style.transition='opacity .5s';$('#flash').style.opacity=0;});
  try{sndCam.currentTime=0;sndCam.play().catch(()=>{});}catch(e){}$('#photoImg').src=url;$('#photoSave').href=url;setTimeout(()=>$('#photo').classList.add('show'),350);}
$('#photoClose').onclick=()=>$('#photo').classList.remove('show');
$('#setBtn').onclick=()=>{joy.id=null;joy.x=joy.y=0;joyEl.style.display='none';$('#setName').value=SAVE.name||'';$('#settings').classList.add('show');renderMe();};
/* you at the top left: your picture (the same choice as the 2D studio, kept by pics.js) and your name */
const PIC=window.BrynnyPic||{current:()=>'',html:()=>isGuy(SAVE.look)?'👦':'👧',picker:()=>'',set(){}};
// "Match my look" here is the live close-up of your 3D character (26b-portrait.js)
if(window.BrynnyPic)BrynnyPic.match=()=>{const im=BrynnyPic.liveImg('@me3d');return im?`<img class="picimg" src="${im}" alt="">`:null;};
function renderMe(){$('#mePic').innerHTML=PIC.html(PIC.current());$('#meName').textContent=SAVE.name||'Me';if($('#settings').classList.contains('show'))$('#picRow').innerHTML=PIC.picker(true);}
$('#picRow').addEventListener('click',e=>{const b=e.target.closest('[data-pic]');if(!b)return;PIC.set(b.dataset.pic);sfx('pop');renderMe();});
addEventListener('storage',e=>{if(!e.key||e.key.startsWith('brynny.'))renderMe();});
// change your name (the 2D studio gets it too, see 01b-shared-name.js)
function saveNameFromSettings(){const el=$('#setName'),n=el.value.trim();if(!n){el.value=SAVE.name||'';el.focus();toast('Type your name first ✏️');return;}
  if(n.slice(0,16)===SAVE.name){toast(`Your name is ${SAVE.name} 💖`);return;}
  setMyName(n);el.value=SAVE.name;el.blur();rebuildPlayer();renderMe();sfx('tada');toast(`✨ Hi ${SAVE.name}! Your new name is saved`);}
$('#setNameGo').onclick=saveNameFromSettings;
$('#setName').addEventListener('keydown',e=>{if(e.key==='Enter')saveNameFromSettings();});
// a name changed in the 2D studio (in another tab) shows up when you come back
document.addEventListener('visibilitychange',()=>{if(document.hidden)return;if(pullName()){rebuildPlayer();if($('#settings').classList.contains('show'))$('#setName').value=SAVE.name;}renderMe();});
// picture quality switch (see LITE in 01-setup.js); the game starts again to use it
const renderQ=()=>{$('#qFull').classList.toggle('on',!LITE);$('#qLite').classList.toggle('on',LITE);};renderQ();
const pickQ=lite=>{if(lite===LITE)return;try{localStorage.setItem('brynny.lite3d',lite?'on':'off');}catch(e){}persist();location.reload();};
$('#qFull').onclick=()=>pickQ(false);$('#qLite').onclick=()=>pickQ(true);
$('#setClose').onclick=()=>$('#settings').classList.remove('show');
$('#settings').onclick=e=>{if(e.target.id==='settings')$('#settings').classList.remove('show');};

/* runway pose */
$('#poseBtn').onclick=()=>{av.play('pose');try{sndCheer.currentTime=0;sndCheer.play().catch(()=>{});}catch(e){}setTimeout(()=>{wantPhoto=true;},700);burst(new THREE.Vector3(player.pos.x,player.pos.y+1.2,player.pos.z),'#ffd6f0',60,3);};

/* closet */
const TABS=[['hair','💇','Hair'],['skin','🙂','Face'],['makeup','💄','Makeup'],['dresses','👗','Dresses'],['tops','👕','Tops'],['bottoms','👖','Bottoms'],['shoes','👟','Shoes'],['hats','👑','Hats'],['extras','👜','Extras']];
let ctab='dresses',lastExtra=null,czoom='body';
const MK_SHADOW=['#ff6fae','#ffb3d1','#b388ff','#8e6cff','#4fb6ff','#2fd1c5','#7ee081','#ffd23f','#d4af37','#c0c0c0','#ff8a1f','#8a5a3b','#2d2d3a'];
const MK_LIPS=['#ff3b6b','#e0263b','#c2185b','#ff6fae','#ffb3d1','#e89aa0','#b5655b','#8e2b5b','#ff8a1f','#8e6cff','#4fb6ff','#2d2d3a'];
const MK_BRUSH=['#2b1d16','#000000','#ffffff','#ff3b6b','#c2185b','#ff6fae','#b388ff','#4fb6ff','#2fd1c5','#7ee081','#ffd23f','#d4af37','#c0c0c0','#8a5a3b'];
function renderCloset(){const L=SAVE.look;if(!glamOpen&&!barberOpen&&!storeOpen&&!tabsOf().some(t=>t[0]===ctab))ctab=isGuy(L)?'tops':'dresses';
  $('#tabs').innerHTML=(glamOpen?glamTabs():barberOpen?BARBER_TABS:storeOpen?storeTabs():tabsOf()).map(([id,ico,n])=>`<button class="tab${id===ctab?' on':''}" data-tab="${id}"><b>${ico}</b>${n}</button>`).join('');
  let h='';const sw=(list,cur,kind)=>`<div class="swatches">${list.map(c=>`<button class="sw${c===cur?' on':''}" style="background:${c}" data-sw="${kind}" data-c="${c}" aria-label="color ${c}"></button>`).join('')}</div>`;
  const gh=glamOpen&&glamHTML()||barberOpen&&barberHTML()||storeOpen&&storeHTML();if(gh)h=gh;
  else if(ctab==='hair'){h+=`<h3>Hair style</h3><div class="grid">${hairsOf(L).map(([id,ico,n])=>`<button class="item${L.hair.id===id?' on':''}" data-hair="${id}"><b>${ico}</b><span>${n}</span></button>`).join('')}</div><h3>Hair color</h3>`+sw(myColors(HAIRC),L.hair.c,'hair');}
  else if(ctab==='makeup'){const mk=L.makeup;const swn=(list,cur,kind)=>`<div class="swatches"><button class="sw none${!cur?' on':''}" data-sw="${kind}" data-c="" aria-label="none">🚫</button>${list.map(c=>`<button class="sw${c===cur?' on':''}" style="background:${c}" data-sw="${kind}" data-c="${c}"></button>`).join('')}</div>`;
    const ch=(key,opts)=>`<div class="chips">${opts.map(([v,n])=>`<button class="${String(mk[key])===String(v)?'on':''}" data-mk="${key}" data-v="${v}">${n}</button>`).join('')}</div>`;
    h+=`<div class="zoomrow">${[['eyes','👁️ Eyes'],['lips','👄 Lips'],['face','🙂 Face']].map(([z,n])=>`<button class="${czoom===z?'on':''}" data-zoom="${z}">${n}</button>`).join('')}</div>
      <h3>🖌️ Draw on the face</h3><p class="drawhint">Drag your finger on the face to draw liner, lashes, freckles or face paint.</p>
      <div class="chips">${[['thin','✏️ Thin'],['medium','🖍️ Medium'],['thick','🎨 Thick']].map(([v,n])=>`<button class="${!brush.erase&&brush.size===v?'on':''}" data-brush="${v}">${n}</button>`).join('')}<button class="${brush.erase?'on':''}" data-brush="erase">🧽 Eraser</button><button data-brush="undo">↩️ Undo</button><button data-brush="clear">🗑️ Clear</button></div>
      <div style="height:8px"></div>`+sw(MK_BRUSH,brush.erase?null:brush.c,'brush')+
      `<h3>👁️ Eyeshadow</h3>`+swn(MK_SHADOW,mk.shadow,'shadow')+
      `<h3>Eyeliner</h3>`+ch('liner',[['none','None'],['thin','Thin'],['bold','Bold'],['wing','Cat eye']])+`<div style="height:8px"></div>`+sw(['#2b1d16','#000000','#6a3df0','#3a5bd9','#2fd1c5','#d4af37','#ff3b6b'],mk.linerC,'linerC')+
      `<h3>Lashes</h3>`+ch('lashes',[['natural','Natural'],['long','Long'],['bold','Dramatic']])+
      `<h3>✨ Face gems</h3>`+ch('gems',[[false,'Off'],[true,'Sparkly gems']])+
      `<h3>👄 Lipstick</h3>`+swn(MK_LIPS,mk.lips,'lips')+
      `<h3>Lip liner</h3>`+swn(MK_LIPS,mk.lipLiner,'lipLiner')+
      `<h3>Lip gloss</h3>`+ch('gloss',[[false,'Matte'],[true,'Shiny gloss']])+
      `<h3>🌸 Blush</h3>`+ch('blush',[['none','None'],['pink','Pink'],['peach','Peach'],['rose','Rose']]);}
  else if(ctab==='skin'){const G=isGuy(L);h+=`<h3>Girl or guy</h3><div class="grid">${[['girl','👧','Girl'],['guy','👦','Guy']].map(([v,e,n])=>`<button class="item${(G?'guy':'girl')===v?' on':''}" data-body="${v}"><b>${e}</b><span>${n}</span></button>`).join('')}</div><h3>Look style</h3><div class="grid">${[['glam',G?'😎':'💃',G?'Real guy':'Glam girl'],['cute','🧸','Cute cartoon']].map(([v,e,n])=>`<button class="item${(L.style||'glam')===v?' on':''}" data-style="${v}"><b>${e}</b><span>${n}</span></button>`).join('')}</div>`+((L.style||'glam')!=='cute'?FACEOPT.filter(o=>!G||o[0]!=='lips').map(([k,t,opts])=>`<h3>${t}</h3><div class="grid">${opts.map(([v,e,n])=>`<button class="item${faceVal(L,k)===v?' on':''}" data-face="${k}:${v}"><b>${e}</b><span>${n}</span></button>`).join('')}</div>`).join(''):'')+`<h3>Skin tone</h3>`+sw(SKIN,L.skin,'skin')+`<h3>Eye color</h3>`+sw(EYES,L.eyes,'eyes');}
  else{const list=catOf(ctab),k=KEY[ctab];
    if(ctab==='extras'){h+=`<h3>Tap to add or take off</h3><div class="grid">${inSeason(list).map(([id,ico,n])=>lockBtn('look:'+id,ico,n)||`<button class="item${L.extras[id]?' on':''}" data-item="${id}"><b>${ico}</b><span>${n}</span></button>`).join('')}</div>`;
      if(lastExtra&&L.extras[lastExtra])h+=`<h3>Color</h3>`+sw(myColors(COLORS),L.extras[lastExtra],'item');}
    else{const cur=L[k];const none=ctab!=='shoes'&&ctab!=='dresses'?`<button class="item${!cur?' on':''}" data-item=""><b>🚫</b><span>None</span></button>`:'';
      h+=`<div class="grid">${none}${inSeason(list).map(([id,ico,n])=>lockBtn('look:'+id,ico,n)||`<button class="item${cur&&cur.id===id?' on':''}" data-item="${id}"><b>${ico}</b><span>${n}</span></button>`).join('')}</div>`;
      if(cur)h+=`<h3>Color</h3>`+sw(myColors(COLORS),cur.c,'item');
      if(ctab==='shoes'&&isRoller(cur))h+=`<h3>🛼 Wheels</h3>`+sw(myColors(COLORS),cur.w||ROLLERS[cur.id].w,'wheels');}}
  $('#ccontent').innerHTML=h;}
function rebuildPlayer(){scene.remove(av.g);freeObj(av.g);av=new Avatar(SAVE.look,SAVE.name||'Brynny',tagColor(SAVE.look),true);scene.add(av.g);loadPaint(av);av.g.position.copy(player.pos);av.g.rotation.y=player.face;renderActions();}
function changed(){if(glamOpen){persist();sfx('pop');glamSeat(true);renderCloset();return;}av.dress(SAVE.look);persist();renderActions();sfx('pop');if(ctab==='makeup'){renderCloset();return;}av.play('hop');burst(new THREE.Vector3(player.pos.x,player.pos.y+1.1,player.pos.z),'#ffd6f0',24,1.6,.1);renderCloset();}
function setZoom(z){czoom=z;if(z!=='body')player.face=cam.closetYaw;}
$('#tabs').onclick=e=>{const b=e.target.closest('[data-tab]');if(!b)return;ctab=b.dataset.tab;setZoom(ctab==='makeup'||ctab==='skin'?'face':'body');if(glamOpen){gcam.init=false;if(BVIEW[ctab]!=null)bview=BVIEW[ctab];glamSeat(false);}renderCloset();$('#ccontent').scrollTop=0;};
$('#ccontent').onclick=e=>{const L=SAVE.look;const b=e.target.closest('button');if(!b)return;if(glamOpen&&glamClick(b))return;
  if(b.dataset.lock){askBuy(b.dataset.lock);return;}
  if(b.dataset.hair){L.hair.id=b.dataset.hair;return changed();}
  if(b.dataset.face){const [k,v]=b.dataset.face.split(':');L.face=Object.assign({},L.face,{[k]:v});persist();rebuildPlayer();if(glamOpen)glamSeat(false);sfx('pop');renderCloset();return;}
  if(b.dataset.body){if(switchBody(b.dataset.body)){rebuildPlayer();sfx('tada');wsRender();}renderCloset();return;}
  if(b.dataset.style){if(L.style!==b.dataset.style){L.style=b.dataset.style;persist();rebuildPlayer();sfx('pop');}renderCloset();return;}
  if(b.dataset.zoom){setZoom(b.dataset.zoom);if(b.dataset.zoom==='lips'){brush.c=L.makeup.lips||'#c2185b';brush.size='thin';brush.erase=false;}if(b.dataset.zoom==='eyes'){brush.c='#2b1d16';brush.size='thin';brush.erase=false;}renderCloset();return;}
  if(b.dataset.brush){const v=b.dataset.brush,x=av.paintCv.getContext('2d');
    if(v==='erase')brush.erase=!brush.erase;else if(v==='undo'){const d=undo.pop();if(d){x.putImageData(d,0,0);av.renderFace();savePaint();}else toast('Nothing to undo');}
    else if(v==='clear'){undo.push(x.getImageData(0,0,av.paintCv.width,av.paintCv.height));x.clearRect(0,0,av.paintCv.width,av.paintCv.height);av.renderFace();savePaint();}
    else{brush.size=v;brush.erase=false;}renderCloset();return;}
  if(b.dataset.mk){const v=b.dataset.v;L.makeup[b.dataset.mk]=v==='true'?true:v==='false'?false:v;return changed();}
  if(b.dataset.sw==='brush'){brush.c=b.dataset.c;brush.erase=false;renderCloset();return;}
  if(['shadow','lips','lipLiner','linerC'].includes(b.dataset.sw)){L.makeup[b.dataset.sw]=b.dataset.c||null;if(b.dataset.sw==='linerC'&&L.makeup.liner==='none')L.makeup.liner='thin';return changed();}
  if(b.dataset.sw){const c=b.dataset.c,k=b.dataset.sw;if(k==='hair')L.hair.c=c;else if(k==='wheels'){if(L.shoes)L.shoes.w=c;}else if(k==='skin')L.skin=c;else if(k==='eyes')L.eyes=c;
    else if(ctab==='extras'){if(lastExtra)L.extras[lastExtra]=c;}else{const cur=L[KEY[ctab]];if(cur)cur.c=c;}return changed();}
  if('item' in b.dataset){const id=b.dataset.item;const list=catOf(ctab);const it=list.find(x=>x[0]===id);
    if(ctab==='extras'){if(L.extras[id]){delete L.extras[id];lastExtra=null;}else{applyItem(L,id);lastExtra=id;}return changed();}
    const k=KEY[ctab];if(!id){L[k]=null;}else{const prev=L[k];L[k]={id,c:prev&&prev.id===id?prev.c:(prev&&ctab!=='dresses'&&ctab!=='hats'?prev.c:it[3])};if(prev&&prev.id===id)L[k].c=prev.c;else L[k].c=it[3];}
    if(ctab==='dresses'&&id){L.top=null;L.bottom=null;}if((ctab==='tops'||ctab==='bottoms')&&id){if(L.dress){L.dress=null;if(ctab==='tops'&&!L.bottom)L.bottom=plainBottom(L);if(ctab==='bottoms'&&!L.top)L.top=plainTop(L);}}
    return changed();}};
function openCloset(){if(closetOpen)return;closeTalk();closetOpen=true;Z.studio.padLbl.visible=false;setZoom(ctab==='makeup'||ctab==='skin'?'face':'body');document.body.classList.add('dressing');renderCloset();$('#closet').classList.add('show');player.face=cam.yaw;cam.closetYaw=cam.yaw;joy.id=null;joy.x=joy.y=0;joyEl.style.display='none';}
function closeCloset(){if(glamOpen){closeGlam();return;}if(barberOpen){closeBarber();return;}if(storeOpen){closeStore();return;}closetOpen=false;Z.studio.padLbl.visible=true;czoom='body';document.body.classList.remove('dressing');$('#closet').classList.remove('show');cam.yaw=cam.closetYaw;player.face=cam.closetYaw+Math.PI;av.play('twirl');closeClosetHook();did('dress');}
function closeClosetHook(){if(ct.on&&ct.sub==='closet'){ct.sub=null;backToContest();}}
$('#done').onclick=closeCloset;

// ---- src/19b-pet-outfits.js ----
/* ================= MORE PET OUTFITS =================
   The newer hats, neck things, outfits, glasses, paw shoes and extras from the lists in 20-pet-parlor.js.
   dressPet() builds the first ones itself and then calls dressPetMore() for these. Sizes come from the pet:
   H is the head size, r and L the body's radius and length, so every outfit fits a chihuahua and a big dog alike.
   On the head, +y is up and +z is the face. On the body (pt.torso), +z points to the head and +y is the back. */
const batShape=(()=>{const s=new THREE.Shape();s.moveTo(0,0);s.lineTo(.25,.45);s.lineTo(1,.62);s.quadraticCurveTo(.86,.42,.9,.26);s.quadraticCurveTo(.72,.2,.66,.04);
  s.quadraticCurveTo(.48,.06,.42,-.1);s.quadraticCurveTo(.22,.02,0,0);return s;})();
const PET_FLOWER_C=['#ffffff','#ffd23f'];
function dressPetMore(pt,F,add,cloth,shiny){const D=pt.D,H=D.head,r=D.r,L=D.len,hd=pt.head,ts=pt.torso;
  const metal=c=>std(c,{metalness:1,roughness:.22});
  const glass=c=>phys(c,{roughness:.05,clearcoat:1,transparent:true,opacity:.55});
  const bowAt=(c,x,y,z,k,par)=>{for(const s of [-1,1]){const w=add(new THREE.ConeGeometry(k*.5,k,12),shiny(c),x+s*k*.45,y,z,par);w.rotation.z=s*Math.PI/2;w.scale.z=.5;}add(sph(k*.24,10,8),shiny(c),x,y,z,par);};
  const lathe=(pts,mat,y,par,z=-H*.05)=>add(new THREE.LatheGeometry(pts.map(([a,b])=>new THREE.Vector2(a,b)),36),mat,0,y,z,par);
  const h=F.hat,n=F.neck,b=F.body,gl=F.glasses,ft=F.feet,ex=F.extra;
  if(pt.sparkG){if(pt.sparkG.parent)pt.sparkG.parent.remove(pt.sparkG);pt.sparkG=null;}

  /* ---------- hats ---------- */
  if(h){const c=h.c,y0=H*.86,zc=-H*.05;
    if(h.id==='tiara'){const t=add(new THREE.TorusGeometry(H*.42,H*.03,8,32,Math.PI),metal(c),0,y0+H*.04,zc,hd);t.rotation.x=Math.PI/2;
      for(let i=0;i<7;i++){const a=(i+.5)/7*Math.PI,k=1-Math.abs(i-3)/4;const x=Math.cos(a)*H*.42,zz=zc+Math.sin(a)*H*.42;
        add(new THREE.ConeGeometry(H*.04,H*(.1+.16*k),6),metal(c),x,y0+H*(.1+.08*k),zz,hd);
        if(i%2===0)add(new THREE.OctahedronGeometry(H*(.04+.03*k)),shiny(['#ff6fae','#4fb6ff','#ff6fae','#8e6cff'][i/2]),x*1.03,y0+H*.06,zz+H*.02,hd);}}
    if(h.id==='tophat'){add(cyl(H*.55,H*.55,H*.04,32),cloth(c),0,y0,zc,hd);add(cyl(H*.32,H*.35,H*.6,28),cloth(c),0,y0+H*.32,zc,hd);
      add(cyl(H*.355,H*.355,H*.11,28,1,true),shiny('#ff3b6b'),0,y0+H*.09,zc,hd).material.side=THREE.DoubleSide;}
    if(h.id==='cowboy'){lathe([[0,0],[H*.5,0],[H*.7,H*.05],[H*.8,H*.17],[H*.79,H*.19]],cloth(c),y0,hd).scale.z=.8;
      add(sph(H*.38,20,14),cloth(c),0,y0+H*.12,zc,hd).scale.set(1,.85,.9);add(cyl(H*.39,H*.39,H*.07,24,1,true),cloth('#5a3a22'),0,y0+H*.06,zc,hd).material.side=THREE.DoubleSide;
      add(sph(H*.05,8,6),metal('#e8c25a'),0,y0+H*.07,zc+H*.36,hd);}
    if(h.id==='sunhat'){lathe([[0,0],[H*.6,-H*.02],[H*.9,-H*.1],[H*.98,-H*.16]],cloth(c),y0+H*.02,hd);
      add(new THREE.SphereGeometry(H*.42,24,12,0,Math.PI*2,0,Math.PI/2),cloth(c),0,y0,zc,hd);
      add(cyl(H*.425,H*.425,H*.1,28,1,true),cloth('#ff6fae'),0,y0+H*.05,zc,hd).material.side=THREE.DoubleSide;
      for(let i=0;i<5;i++){const a=-.6+i*.3;add(sph(H*.08,10,8),cloth(i%2?'#ffffff':'#ff6fae'),Math.sin(a)*H*.44,y0+H*.08,zc+Math.cos(a)*H*.44,hd);}}
    if(h.id==='cap'){add(new THREE.SphereGeometry(H*.45,24,12,0,Math.PI*2,0,Math.PI/2),cloth(c),0,y0-H*.04,zc,hd);
      add(new THREE.CylinderGeometry(H*.4,H*.4,H*.03,24,1,false,-Math.PI/2,Math.PI),cloth(c),0,y0-H*.02,zc+H*.28,hd).scale.z=1.25;
      add(sph(H*.06,8,6),cloth('#ffffff'),0,y0+H*.4,zc,hd);}
    if(h.id==='chef'){add(cyl(H*.36,H*.34,H*.32,24),cloth(c),0,y0+H*.12,zc,hd);add(sph(H*.46,20,14),cloth(c),0,y0+H*.42,zc,hd).scale.y=.65;
      for(let i=0;i<5;i++){const a=i/5*Math.PI*2;add(sph(H*.2,12,10),cloth(c),Math.sin(a)*H*.3,y0+H*.5,zc+Math.cos(a)*H*.3,hd);}}
    if(h.id==='bunny'){const band=add(new THREE.TorusGeometry(H*.62,H*.04,8,24,Math.PI),shiny(c),0,y0-H*.2,zc,hd);band.rotation.y=Math.PI/2;
      for(const s of [-1,1]){const e=add(new THREE.CapsuleGeometry(H*.12,H*.6,6,12),cloth(c),s*H*.24,y0+H*.48,zc,hd);e.rotation.z=-s*.22;e.scale.z=.55;
        const i=add(new THREE.CapsuleGeometry(H*.07,H*.48,6,10),cloth('#ff9eb5'),s*H*.24,y0+H*.48,zc+H*.06,hd);i.rotation.z=-s*.22;i.scale.z=.3;}}
    if(h.id==='pumpkin'){for(let i=0;i<4;i++){const p=add(sph(H*.42,20,14),cloth(c,{roughness:.6}),0,y0+H*.16,zc,hd);p.scale.set(.62,.72,1);p.rotation.y=i*Math.PI/4;}
      add(cyl(H*.05,H*.07,H*.2,8),cloth('#3f7a2c'),0,y0+H*.5,zc,hd);const lf=add(sph(H*.1,10,8),cloth('#5bb04a'),H*.1,y0+H*.47,zc,hd);lf.scale.set(1.4,.3,.8);}
    if(h.id==='antlers'){const m=cloth(c,{roughness:.7});
      for(const s of [-1,1]){const add2=(x,y,len,rz)=>{const p=add(cyl(H*.035,H*.05,len,8),m,s*x,y,zc,hd);p.rotation.z=-s*rz;};
        add2(H*.28,y0+H*.25,H*.55,.35);add2(H*.47,y0+H*.36,H*.3,1.05);add2(H*.38,y0+H*.62,H*.28,-.15);add2(H*.3,y0+H*.44,H*.22,-.6);}
      add(sph(H*.1,10,8),shiny('#e0263b'),0,-H*.05,H*1.05,hd);}}

  /* ---------- around the neck ---------- */
  if(n){const c=n.c,y=-H*.72,zc=-H*.05,R=H*.66;
    if(n.id==='lei'){for(let i=0;i<14;i++){const a=i/14*Math.PI*2,dip=Math.max(0,Math.cos(a))*H*.1;const x=Math.sin(a)*R,zz=zc+Math.cos(a)*R;
      add(sph(H*.13,10,8),cloth(i%2?c:PET_FLOWER_C[(i>>1)%2]),x,y-dip,zz,hd).scale.set(1,.65,1);add(sph(H*.045,8,6),shiny('#ffd23f'),x*1.08,y-dip,zc+(zz-zc)*1.08,hd);}}
    if(n.id==='tie'){add(new THREE.TorusGeometry(R,H*.05,8,28),cloth('#ffffff'),0,y,zc,hd).rotation.x=Math.PI/2;
      add(sph(H*.09,10,8),cloth(c),0,y,R+zc,hd).scale.set(1,.9,.6);const t=add(new THREE.ConeGeometry(H*.14,H*.62,4),cloth(c,{map:TEX.stripes}),0,y-H*.36,R+zc-H*.02,hd);t.rotation.x=Math.PI;t.rotation.y=Math.PI/4;t.scale.z=.35;}
    if(n.id==='medal'){for(const s of [-1,1]){const rb=add(box(H*.12,H*.5,H*.02),cloth(c),s*H*.12,y-H*.12,R+zc-H*.05,hd);rb.rotation.z=s*.35;}
      const m=add(cyl(H*.17,H*.17,H*.04,24),std('#e8c25a',{metalness:1,roughness:.2,emissive:new THREE.Color('#5a4000')}),0,y-H*.38,R+zc,hd);m.rotation.x=Math.PI/2;
      add(new THREE.ExtrudeGeometry(starShape,{depth:.3,bevelEnabled:false}),std('#fff1a8',{metalness:1,roughness:.3}),0,y-H*.38,R+zc+H*.02,hd).scale.set(H*.4,H*.4,H*.05);}
    if(n.id==='jewel'){add(new THREE.TorusGeometry(R,H*.025,6,32),metal('#e8e8f0'),0,y,zc,hd).rotation.x=Math.PI/2;
      const g=add(new THREE.OctahedronGeometry(H*.16),phys(c,{roughness:.05,clearcoat:1,iridescence:.6,transparent:true,opacity:.92}),0,y-H*.12,R+zc+H*.02,hd);g.scale.set(.9,1.25,.6);
      for(const s of [-1,1])add(new THREE.OctahedronGeometry(H*.07),shiny(c),s*H*.3,y-H*.04,zc+R*.93,hd);}
    if(n.id==='bell'){add(new THREE.TorusGeometry(R,H*.07,8,28),cloth(c),0,y,zc,hd).rotation.x=Math.PI/2;
      add(sph(H*.15,14,12),metal('#e8c25a'),0,y-H*.16,R+zc+H*.04,hd);add(box(H*.18,H*.02,H*.02),std('#4a3000'),0,y-H*.2,R+zc+H*.18,hd);}}

  /* ---------- outfits on the body ---------- */
  if(b){const c=b.c;const tube=(rad,len,mat,z)=>{const s=add(cyl(rad,rad,len,28,1,true),mat,0,0,z,ts);s.rotation.x=Math.PI/2;return s;};
    const ring=(rad,th,mat,z)=>add(new THREE.TorusGeometry(rad,th,8,28),mat,0,0,z,ts);
    if(b.id==='dress'){tube(r*1.07,L*.55,cloth(c),L*.18);const sk=add(cyl(r*1.08,r*1.6,L*.5,36,1,true),cloth(c,{transparent:true,opacity:.95}),0,0,-L*.32,ts);sk.rotation.x=Math.PI/2;
      ring(r*1.6,r*.06,cloth('#ffffff'),-L*.57);ring(r*1.08,r*.07,cloth('#ffffff'),L*.45);bowAt('#ffffff',0,r*1.08,-L*.08,r*.5,ts);}
    if(b.id==='tux'){tube(r*1.08,L*.8,cloth(c),L*.05);ring(r*1.08,r*.08,cloth(c),L*.45);
      add(sph(r*.62,16,12),cloth('#ffffff'),0,-r*.18,L*.48,ts).scale.set(1,1.15,.55);bowAt('#2d2d3a',0,r*.25,L*.5+r*.45,r*.32,ts);
      for(const k of [0,1])add(sph(r*.06,8,6),metal('#e8c25a'),0,-r*.2-k*r*.25,L*.5+r*.33,ts);
      for(const s of [-1,1]){const t=add(box(r*.3,r*.05,L*.45),cloth(c),s*r*.32,r*.75,-L*.55,ts);t.rotation.x=.55;t.rotation.z=s*.25;}}
    if(b.id==='raincoat'){const m=phys(c,{roughness:.15,clearcoat:1});tube(r*1.12,L*.9,m,L*.02);ring(r*1.12,r*.1,m,L*.47);
      for(let k=0;k<3;k++)add(sph(r*.08,8,6),shiny('#2d2d3a'),r*.55,r*.95,L*(.3-k*.25),ts);
      const hood=add(new THREE.SphereGeometry(r*.75,18,12,0,Math.PI*2,0,Math.PI/2),m,0,r*.95,L*.42,ts);hood.rotation.x=-.9;hood.scale.z=.6;}
    if(b.id==='bee'){tube(r*1.07,L*.85,cloth(c),L*.02);for(const z of [.25,0,-.25])ring(r*1.09,r*.1,cloth('#2d2d3a'),L*z);
      for(const s of [-1,1]){const w=add(new THREE.CircleGeometry(r*.7,20),phys('#ffffff',{side:THREE.DoubleSide,transparent:true,opacity:.7,iridescence:1}),s*r*.45,r*1.35,L*.05,ts);w.scale.set(1,.6,1);w.rotation.set(0,Math.PI/2,s*.55);}
      for(const s of [-1,1]){const a=add(cyl(H*.025,H*.025,H*.55,6),cloth('#2d2d3a'),s*H*.2,H*1.05,0,hd);a.rotation.z=-s*.3;add(sph(H*.08,8,6),shiny('#2d2d3a'),s*H*.28,H*1.3,0,hd);}}
    if(b.id==='dino'){const m=cloth(c,{roughness:.6});for(let i=0;i<7;i++){const t=i/6,k=Math.sin(.25+t*2.6);const s=add(new THREE.ConeGeometry(r*.22*k+r*.06,r*.55*k+r*.12,4),m,0,r*(.98+.1*k),L*(.55-t*1.2),ts);s.scale.z=.45;}
      for(let i=0;i<3;i++){const s=add(new THREE.ConeGeometry(H*.08,H*(.22-i*.04),4),m,0,H*(.92-i*.06),-H*(.1+i*.22),hd);s.scale.z=.45;s.rotation.x=-.3-i*.2;}}
    if(b.id==='angel'){const m=phys(c,{roughness:.6,sheen:1,sheenColor:new THREE.Color('#ffffff')});
      for(const s of [-1,1])for(let i=0;i<6;i++){const a=i/5;const f=add(sph(r*.32,10,8),m,s*r*(.45+a*.65),r*(1.15+a*.55),-L*.05-a*r*.25,ts);f.scale.set(.35,1.35-a*.4,.5);f.rotation.z=-s*(.3+a*.8);}}
    if(b.id==='bat'){const m=phys(c,{side:THREE.DoubleSide,roughness:.4,sheen:1,sheenColor:new THREE.Color('#8e6cff')});
      for(const s of [-1,1]){const w=add(new THREE.ShapeGeometry(batShape),m,s*r*.35,r*.85,-L*.05,ts);w.scale.set(s*r*1.9,r*1.6,1);w.rotation.y=s*.25;}}
    if(b.id==='floatie'){ring(r*1.3,r*.34,phys(c,{map:TEX.stripes,roughness:.2,clearcoat:1}),L*.05);}}

  /* ---------- glasses ---------- */
  if(gl){const c=gl.c,y=H*.12,zz=H*1.0;
    const bridge=(col)=>add(box(H*.26,H*.04,H*.04),shiny(col),0,y+H*.03,zz,hd);
    if(gl.id==='round'){for(const s of [-1,1]){add(new THREE.TorusGeometry(H*.19,H*.025,8,24),metal(c),s*H*.42,y,zz,hd);add(new THREE.CircleGeometry(H*.18,24),glass('#cfefff'),s*H*.42,y,zz-.001,hd);}bridge(c);}
    if(gl.id==='goggles'){for(const s of [-1,1]){add(new THREE.TorusGeometry(H*.19,H*.065,10,24),shiny(c),s*H*.4,y,zz,hd);add(new THREE.CircleGeometry(H*.19,24),glass('#8fd8ff'),s*H*.4,y,zz-.002,hd);}
      bridge(c);add(new THREE.TorusGeometry(H*.98,H*.04,6,32),cloth(c),0,y,0,hd).rotation.x=Math.PI/2;}
    if(gl.id==='monocle'){add(new THREE.TorusGeometry(H*.21,H*.03,8,24),metal(c),H*.42,y,zz,hd);add(new THREE.CircleGeometry(H*.2,24),glass('#e8f6ff'),H*.42,y,zz-.001,hd);
      const ch=add(cyl(H*.012,H*.012,H*.6,6),metal(c),H*.55,y-H*.42,zz-H*.08,hd);ch.rotation.z=.25;}
    if(gl.id==='flower'){for(const s of [-1,1]){for(let i=0;i<7;i++){const a=i/7*Math.PI*2;add(sph(H*.09,10,8),cloth(c),s*H*.42+Math.cos(a)*H*.2,y+Math.sin(a)*H*.2,zz,hd).scale.z=.4;}
      add(new THREE.CircleGeometry(H*.15,20),glass('#ffe6f2'),s*H*.42,y,zz,hd);}bridge('#7ee081');}
    if(gl.id==='mask'){const m=phys(c,{map:TEX.glitter,roughness:.3,clearcoat:1});for(const s of [-1,1]){const e=add(new THREE.TorusGeometry(H*.18,H*.09,10,24),m,s*H*.38,y,zz,hd);e.scale.set(1.25,.85,.45);}
      bridge(c);for(const s of [-1,1]){const f=add(sph(H*.1,10,8),cloth('#ff6fae'),s*H*.7,y+H*.28,zz-H*.05,hd);f.scale.set(.4,1.8,.3);f.rotation.z=-s*.5;}}}

  /* ---------- on the paws ---------- */
  if(ft){const c=ft.c;
    pt.legs.forEach(l=>{const pw=l.paw,par=pw.parent,R=pw.geometry.parameters.radius||r*.36,sc=pw.scale,p=pw.position,top=Math.max(R*2,Math.abs(p.y)*.55);
      const cover=(mat,k=1.08)=>{const m=add(sph(R*k,12,10),mat,p.x,p.y+R*.05,p.z,par);m.scale.copy(sc);return m;};
      const leg=(mat,hgt,rad)=>add(cyl(rad,rad,hgt,14,1,true),mat,p.x,p.y+hgt/2,p.z*.6,par);
      if(ft.id==='socks'){const m=cloth(c,{map:TEX.stripes});cover(m);leg(m,top,R*sc.x*.98);add(new THREE.TorusGeometry(R*sc.x*.98,R*.12,6,16),cloth('#ffffff'),p.x,p.y+top,p.z*.6,par).rotation.x=Math.PI/2;}
      if(ft.id==='boots'){const m=phys(c,{roughness:.15,clearcoat:1});cover(m,1.12);leg(m,top*.75,R*sc.x*1.05);const s=add(sph(R*1.14,12,8),std('#2d2d3a',{roughness:.8}),p.x,p.y-R*.3,p.z,par);s.scale.set(sc.x,.25,sc.z);}
      if(ft.id==='sneakers'){cover(cloth(c),1.1);const s=add(sph(R*1.16,12,8),cloth('#ffffff'),p.x,p.y-R*.28,p.z,par);s.scale.set(sc.x,.3,sc.z);
        for(const k of [0,1])add(box(R*.9,R*.08,R*.08),cloth('#ffffff'),p.x,p.y+R*.35,p.z+R*sc.z*(.25+k*.3),par);}
      if(ft.id==='slippers'){cover(phys(c,{roughness:1,sheen:1,sheenColor:new THREE.Color('#ffffff')}),1.14);add(sph(R*.32,10,8),cloth('#ffffff'),p.x,p.y+R*.45,p.z+R*sc.z*.7,par);}});}

  /* ---------- extras ---------- */
  if(ex){const c=ex.c;
    if(ex.id==='balloon'){const st=add(cyl(r*.012,r*.012,r*4,4),std('#ffffff'),r*.4,r*2.9,-L*.3,ts);st.rotation.z=-.12;
      const bl=add(sph(r*.75,20,14),phys(c,{roughness:.1,clearcoat:1}),r*.65,r*5.3,-L*.3,ts);bl.scale.y=1.18;add(new THREE.ConeGeometry(r*.12,r*.18,8),phys(c,{roughness:.1}),r*.62,r*4.4,-L*.3,ts).rotation.x=Math.PI;}
    if(ex.id==='backpack'){const bp=add(new THREE.CapsuleGeometry(r*.45,L*.25,6,12),cloth(c),0,r*1.25,-L*.05,ts);bp.rotation.x=Math.PI/2;bp.scale.x=1.2;
      add(new THREE.CapsuleGeometry(r*.28,L*.08,6,10),cloth('#ffd23f'),0,r*1.42,-L*.12,ts).rotation.x=Math.PI/2;
      for(const z of [.2,-.25])add(new THREE.TorusGeometry(r*1.04,r*.05,6,24),cloth(c),0,0,L*z,ts);}
    if(ex.id==='tailbow'&&pt.tail)bowAt(c,0,0,0,r*.55,pt.tail);
    if(ex.id==='sparkle'){const g=new THREE.Group();g.position.set(0,r*.2,0);ts.add(g);pt.sparkG=g;sparkPets.add(pt);const m=phys(c,{emissive:new THREE.Color(c),emissiveIntensity:.8,roughness:.2,metalness:.4});
      for(let i=0;i<9;i++){const a=i/9*Math.PI*2;const s=add(new THREE.ExtrudeGeometry(starShape,{depth:.3,bevelEnabled:false}),m,Math.sin(a)*r*1.9,Math.sin(a*3)*r*.5+r*.6,Math.cos(a)*(L*.5+r*1.3),g);s.scale.setScalar(r*.9);s.rotation.y=a;}}}}
// the ✨ stars spin around their pet
const sparkPets=new Set();
anims.push((t,dt)=>{for(const pt of sparkPets){if(!pt.sparkG||!pt.sparkG.parent){sparkPets.delete(pt);continue;}pt.sparkG.rotation.y+=dt*1.2;}});
// ---- src/19c-dance-picker.js ----
/* ================= DANCE LIST ================= */
// Tapping Dance opens a list of dances to pick from (the dances themselves are in 14d-dances.js).
// Your last dance is marked so it's easy to do it again. Friends nearby join in with the same dance.
let lastDance=SAVE.lastDance||'dance';
function renderDances(){const G=isGuy(SAVE.look);$('#dancesT').textContent=(G?'🕺':'💃')+' Pick a dance';
  $('#danceList').innerHTML=DANCES.map(d=>`<button data-dance="${d[0]}" class="${d[0]===lastDance?'last':''}">${d[0]==='dance'&&G?'🕺':d[1]}<span>${d[2]}</span></button>`).join('');}
function openDances(){if(closetOpen||!started)return;joy.id=null;joy.x=joy.y=0;joyEl.style.display='none';renderDances();$('#dances').classList.add('show');sfx('pop');}
function closeDances(){$('#dances').classList.remove('show');}
$('#danceList').addEventListener('click',e=>{const b=e.target.closest('[data-dance]');if(!b)return;const id=b.dataset.dance;
  lastDance=SAVE.lastDance=id;persist();closeDances();doAction(id,true);});
$('#dancesClose').onclick=closeDances;
$('#dances').onclick=e=>{if(e.target.id==='dances')closeDances();};
