  h+=`<div class="chips" style="margin-top:8px"><button data-mkoff="${mTool}">🧼 Wipe off ${t[2].toLowerCase()}</button><button data-mkoff="all">🧼 Wipe off everything</button></div>`;
  if(['shadow','liner','lashes'].includes(mTool))h+=eyeLooksHTML();
