  if(b.dataset.mtool){mTool=b.dataset.mtool;setZoom({lips:'lips',gloss:'lips',shadow:'eyes',liner:'eyes',lashes:'eyes',brows:'eyes'}[mTool]||'face');sfx('pop');renderCloset();return true;}
