  const tail=new THREE.Group();tail.position.set(0,by+r*.3,-(len/2+r*.85));g.add(tail);
  const tl=ch?.85:.8,pts=[fV(0,0,0),fV(0,-.18,-.25),fV(0,-.3,-.5),fV(0,-.2,-tl)];
