 SCX.spots=SC_SLOTS.map(([x,zz],i)=>{const r=M(new THREE.RingGeometry(i===4?.3:.2,i===4?.42:.3,32),spotM,x,.05,zz,root,false,false);r.rotation.x=-Math.PI/2;r.visible=false;return r;});
