  skPopText(c.map(x=>x.n).join(' + ')+'!',`+${pts}${n>1?` (combo ×${n})`:''}${best&&pts>=200?' 🏆 Best!':''}`);
  tone(660,.08,'triangle',.1);tone(990,.12,'triangle',.1,.07);if(n>1)tone(1320,.15,'triangle',.08,.14);
