  let want=null;if(mag>.08){const fx=-Math.sin(cam.yaw),fz=-Math.cos(cam.yaw),rx=-fz,rz=fx,n=Math.hypot(ix,iy)||1;want=Math.atan2((fx*-iy+rx*ix)/n,(fz*-iy+rz*ix)/n)-z.rot;}
