  const padD=Math.hypot(p.x-Z.studio.pad.x,p.z-Z.studio.pad.z);if(padD<Z.studio.pad.r&&player.onGround){if(!onPad&&started){onPad=true;openCloset();}}else if(padD>1.6)onPad=false;
