function resize(){camera.aspect=innerWidth/innerHeight;camera.fov=innerWidth<innerHeight?62:55;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight,false);}
addEventListener('resize',resize);resize();
document.addEventListener('visibilitychange',()=>{if(document.hidden)music.pause();else if(musicOn&&started&&music.src)music.play().catch(()=>{});});
// Start-up: wait until online.js, challenges.js and seasons.js have added their things too (seasons adds a light,
// and every new light makes the graphics card rebuild all of its shaders), then build the shaders once, in the
// background where the browser allows it, so Tiereyn keeps running on the loading screen. Then show the world.
function showWorld(){renderer.setAnimationLoop(tick);
  requestAnimationFrame(()=>requestAnimationFrame(()=>{const l=$('#loading');if(l){l.classList.add('done');setTimeout(()=>l.remove(),600);}$('#welcome').classList.add('show');}));}
// The glam-room mirror draws the world a second time into its own picture, and that picture needs its own set of
// shaders. Build those now too, or the game freezes for a few seconds the first time the mirror comes into view.
// Like three's compileAsync, but a material that gets thrown away while its shader is still building is skipped.
// three's own version crashes on that (only on phones and computers that build shaders in the background),
// so the loading screen sat there for the full 25 seconds below.
function compileWait(){const mats=renderer.compile(scene,camera);return new Promise(res=>{const check=()=>{
    try{mats.forEach(m=>{const pr=renderer.properties.get(m).currentProgram;if(!pr||pr.isReady())mats.delete(m);});}catch(e){mats.clear();}
    if(mats.size)setTimeout(check,10);else res();};setTimeout(check,10);});}
function warmUp(){try{shareShapes(scene);}catch(e){}// thousands of copies of the same shape become one each (01c-memory.js)
  scene.updateMatrixWorld(true);let c;try{c=compileWait();
    const rt=AG.mirror.getRenderTarget&&AG.mirror.getRenderTarget();if(rt){renderer.setRenderTarget(rt);const c2=compileWait();renderer.setRenderTarget(null);c=Promise.all([c,c2]);}}catch(e){renderer.setRenderTarget(null);c=null;}
  // never wait forever: if building the shaders takes too long, just start (the first frame finishes the job)
  Promise.race([c||Promise.resolve(),new Promise(r=>setTimeout(r,25000))]).catch(()=>{}).then(preUpload).then(showWorld);}
// The graphics chip only gets a shape or picture the first time it is on screen, so turning the camera used to stutter
// while thousands of them were sent over. Draw everything once, behind the loading screen, so they are all there already.
// On a phone, only the things near the start (the first places you see when you look around) are sent now: sending the whole
// island in one giant frame made iPhones run out of graphics memory a few seconds after opening.
function preUpload(){if(LITE)return;const off=[],near=isTouch?40:Infinity,v=new THREE.Vector3();try{scene.traverse(o=>{if(o.frustumCulled&&(near===Infinity||o.getWorldPosition(v).distanceTo(player.pos)<near)){o.frustumCulled=false;off.push(o);}});const au=renderer.shadowMap.autoUpdate;renderer.shadowMap.autoUpdate=false;// skip the shadow pass for this one giant frame
  try{renderer.render(scene,camera);}finally{renderer.shadowMap.autoUpdate=au;renderer.shadowMap.needsUpdate=true;}}catch(e){}off.forEach(o=>o.frustumCulled=true);}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(warmUp,0),{once:true});else setTimeout(warmUp,0);
// ---- src/26-map.js ----
/* ================= MAP ================= */
const MAPC={soccer:'#7cc35c',airfield:'#cfe6b4',arctic:'#e4f4ff',heli:'#c9d3de',studio:'#ffd6ea',birthday:'#ffb3c7',halloween:'#ff9a3c',christmas:'#e9f4ff',beach:'#ffe39a',runway:'#c9b6ff',spring:'#b8f0a8',parlor:'#ffd8b0',bakery:'#ffc4dd',agency:'#ffe066',court:'#ffb070',batting:'#a8e0a0',barn:'#f2b38a',zoo:'#f5d98a',garage:'#cfe0ff',barber:'#bcd7ff',store:'#d7ccb8',jump:'#c9b6ff',skate:'#c9ccd1',diner:'#f2c9a8',mountain:'#c8bfb2',ropes:'#9ed39a'};
const MAP_DRAW=[];// extra drawing under the place circles: f(ctx,w2s,k)
const zEmoji=z=>z.name.split(' ')[0],zLabel=z=>z.name.replace(/^\S+\s/,'');
let mapDest=null,mapOthers=null;
const miniCv=$('#miniCv'),miniX=miniCv.getContext('2d'),mapCv=$('#mapCv'),mapX=mapCv.getContext('2d');
// shared drawing of the island; w2s maps world (x,z) to canvas px, k = px per world unit
function drawWorld(x,w2s,k,size){
  x.fillStyle='#2ab0d4';x.fillRect(0,0,size,size);
  const [cx,cy]=w2s(0,0);
  worldMap(x,w2s,k);// the big world past the canal, blocked off for now (26z-big-world.js)
  canalBank(x,cx,cy,k);// the grassy far bank of the canal (26f-ocean.js)
  advMap(x,w2s,k);// the footbridge over to Lookout Mountain and the ropes course (26h-adventure.js)
  skyMap(x,w2s,k);// the footbridge over to the airfield (26i-sky-sports.js)
  for(const f of MAP_DRAW)f(x,w2s,k);// places on the far bank draw themselves (26w-waterpark.js)
  x.beginPath();x.arc(cx,cy,(R+2.4)*k,0,Math.PI*2);x.fillStyle='#f1d9a6';x.fill();
  x.beginPath();x.arc(cx,cy,R*k,0,Math.PI*2);x.fillStyle='#8fd36f';x.fill();
  // beach dock
  {const b=Z.beach;if(b.dock){const [a1,a2]=[b.toWorld(b.dock.lx,b.dock.lz0),b.toWorld(b.dock.lx,b.dock.lz1)];const p1=w2s(...a1),p2=w2s(...a2);x.strokeStyle='#9a6a43';x.lineWidth=Math.max(2,1.6*k);x.lineCap='butt';x.beginPath();x.moveTo(...p1);x.lineTo(...p2);x.stroke();}}
  // paths
  x.strokeStyle='#efe6da';x.lineCap='round';x.lineWidth=Math.max(2,2.6*k);
  x.beginPath();x.arc(cx,cy,7.15*k,0,Math.PI*2);x.stroke();
  for(const z of ZONES){if(!z.d||z.nopath)continue;const [px,py]=w2s(z.x,z.z),f=(z.p0||7)/z.d;x.beginPath();x.moveTo(cx+(px-cx)*f,cy+(py-cy)*f);x.lineTo(px,py);x.stroke();}
  // zones
  for(const z of ZONES){const [px,py]=w2s(z.x,z.z);x.beginPath();x.arc(px,py,z.r*k,0,Math.PI*2);x.fillStyle=MAPC[z.id]||'#fff3b0';x.fill();
    x.lineWidth=Math.max(1.5,.35*k);x.strokeStyle=mapDest===z?'#ff4d8d':'rgba(255,255,255,.9)';x.stroke();}
  skyMapTop(x,w2s,k);// the airfield's runway and landing target (26i-sky-sports.js)
}
function drawArrow(x,px,py,ang,s,fill){x.save();x.translate(px,py);x.rotate(ang);x.beginPath();x.moveTo(0,-s);x.lineTo(s*.72,s*.7);x.lineTo(0,s*.32);x.lineTo(-s*.72,s*.7);x.closePath();
  x.fillStyle=fill;x.fill();x.lineWidth=s*.22;x.strokeStyle='#fff';x.lineJoin='round';x.stroke();x.restore();}
