    if(showFly(f,d,dt,h))return;// 🪽 up in the air on a flying ride (24h-flying.js)
    a.pos.copy(f.pos);a.g.position.copy(a.pos);a.g.rotation.y=f.cur??f.face;a.update(dt,(f.sp||0)*.55);
    A.g.position.y=f.pos.y+a.F.ride-.42;
