/* ---------- what online.js calls ---------- */
// everything about you, for friends
function myShow(){const r={};for(const s of SHOW){try{const d=s.mine();if(d!=null)r[s.k]=d;}catch(e){}}return r;}
// build, change or take away what friend f has, from what their phone sent
function friendShow(f,all){if(!f)return;const A=all&&typeof all==='object'?all:{};f.shows||(f.shows={});
  for(const s of SHOW){const d=A[s.k]==null?null:A[s.k],j=JSON.stringify(d),cur=f.shows[s.k];
    if(cur&&cur.j===j&&cur.av===f.a)continue;
    if(cur){try{s.off(f,cur.h,cur.d);}catch(e){}delete f.shows[s.k];}
    if(d!=null&&typeof d==='object'){let h=null;try{h=s.on(f,d);}catch(e){h=null;}if(h)f.shows[s.k]={j,d,h,av:f.a};}}}
function friendShowStep(f,dt){if(!f.shows)return;for(const s of SHOW){const c=f.shows[s.k];if(c&&s.step)try{s.step(f,c.d,dt,c.h);}catch(e){}}}
Object.assign(window.__game,{SHOW,myShow,friendShow,friendShowStep,friendShowClear:f=>friendShow(f,{})});
// ---- src/26d-ball-play.js ----
/* ================= ⚽🏀 BALL PLAY: dribble, kick and pass =================
   Wear the ⚽ Soccer ball or the 🏀 Basketball (Extras) and take it for a walk around town:
   - ⚽ Walk and the ball drops to your feet. You dribble it ahead with little touches; turn and it follows.
     Stand still for a moment and you pick it back up.
   - 🏀 Walk and you bounce it beside you. Stop and you hold it.
   - ⚽ Kick / 🏀 Pass (in the moves wheel) sends it to the nearest townsperson or online friend, and they send
     it back to you. With nobody near, a kick boots it up the field (go get it!) and a pass throws it ahead.
   - The ball is put away during sports, riding and the other hands-on games, like the skateboard (17c).
   Online (bottom of this file): friends see your ball, and a pass to an online friend makes it their ball
   to dribble and pass back. */
const BALL_R={soccer:.11,bball:.12};
// textures, made once per color (called while avatars are built, so these are hoisted functions)
function bbMat(c){const C=bbMat.c||(bbMat.c={});if(C[c])return C[c];const m=phys('#ffffff',{roughness:.6,clearcoat:.15});
  m.map=canvasTex(256,128,(x)=>{x.fillStyle=c;x.fillRect(0,0,256,128);x.strokeStyle='#2a1406';x.lineWidth=5;
    x.beginPath();x.moveTo(0,64);x.lineTo(256,64);x.stroke();for(const v of [64,192]){x.beginPath();x.moveTo(v,0);x.lineTo(v,128);x.stroke();}
    for(const v of [0,128,256]){x.beginPath();x.ellipse(v,64,46,64,0,0,Math.PI*2);x.stroke();}});return C[c]=m;}
function sbMat(c){const C=sbMat.c||(sbMat.c={});if(C[c])return C[c];const m=phys('#ffffff',{roughness:.45,clearcoat:.3});
  m.map=canvasTex(256,128,(x)=>{x.fillStyle=c;x.fillRect(0,0,256,128);x.fillStyle='#2d2d3a';
    const pent=(cx,cy,r)=>{x.beginPath();for(let i=0;i<5;i++){const a=-Math.PI/2+i*Math.PI*2/5;x.lineTo(cx+Math.cos(a)*r,cy+Math.sin(a)*r);}x.closePath();x.fill();};
    for(let i=0;i<5;i++){pent(i*51+25,40,15);pent(i*51,92,15);}pent(256,92,15);x.fillRect(0,0,256,6);x.fillRect(0,122,256,6);});return C[c]=m;}
const ballMat=(kind,c)=>kind==='soccer'?sbMat(c||'#ffffff'):bbMat(c||'#ff7a1f');
function ballMesh(kind){const m=M(sph(BALL_R[kind],24,16),ballMat(kind),0,-50,0,scene,true,false);m.visible=false;m.userData.kind=kind;return m;}

/* ---------- the poses (called from Avatar.update for you, townspeople and online friends) ---------- */
// a.ballMove = {drib: 0..1 how high the bouncing basketball is, act:'kick'|'pass', t0: when it started}
function ballPose(a,tgt,sp,t){const b=a.ballMove;
  if(b.drib!=null&&!b.act){tgt.a0x=-.42;tgt.a0z=-.12;tgt.e0=-.3-b.drib*.6;}
  if(!b.act)return;const k=performance.now()/1000-b.t0;
  if(b.act==='kick'){if(k<.13){tgt.l0=.6;tgt.k0=1.05;tgt.a1x=.3;tgt.a0x=-.3;}else if(k<.42){tgt.l0=-1.15;tgt.k0=.08;tgt.a1x=-.45;tgt.a0x=.35;tgt.lean=-.06;}else{b.act=null;if(b.drib==null)a.ballMove=null;}}
  else if(b.act==='pass'){if(k<.16){tgt.a0x=tgt.a1x=-1.15;tgt.e0=tgt.e1=-1.7;tgt.a0z=.2;tgt.a1z=-.2;}else if(k<.45){tgt.a0x=tgt.a1x=-1.5;tgt.e0=tgt.e1=-.1;tgt.a0z=.1;tgt.a1z=-.1;tgt.lean=.08;}else{b.act=null;if(b.drib==null)a.ballMove=null;}}}
const ballAct=(a,act)=>{a.ballMove=Object.assign(a.ballMove||{},{act,t0:performance.now()/1000});};
// where an avatar's held ball is: the soccer ball in the left hand, the basketball in the right
const handSpot=(a,kind,out)=>kind==='soccer'?a.arms[1].hand.localToWorld(out.set(0,-.11,.05)):a.arms[0].hand.localToWorld(out.set(0,-.15,.05));
// bouncing the basketball beside you: right under the hand, from the hand down to the ground and back
const DRIB_HZ=2.4;
function dribbleSpot(a,t,out){const u=(t*DRIB_HZ)%1,s=Math.abs(Math.cos(Math.PI*u));handSpot(a,'bball',out);
  const g=groundAt(out.x,out.z)+BALL_R.bball;out.y=g+(Math.max(g,out.y)-g)*s;return {u,s};}
// rolling: turn the ball around the axis across the way it's going
const ballAxis=new THREE.Vector3();
function ballRoll(m,vx,vz,dt,r){const s=Math.hypot(vx,vz);if(s<.01)return;ballAxis.set(vz/s,0,-vx/s);m.rotateOnWorldAxis(ballAxis,s*dt/r);}

/* ---------- my ball ---------- */
var BP={kind:null,st:'hand',p:new THREE.Vector3(),v:new THREE.Vector3(),m:{},to:null,npc:null,hold:0,flyT:0,still:0,passes:0,
  borrowed:null,awayT:0,u:0,sendT:0,sentNone:true,actsKey:'',col:null};
function ownKind(){const e=(SAVE.look&&SAVE.look.extras)||{};return e.ball?'soccer':e.bball?'bball':null;}
function ballKind(){return BP&&BP.borrowed?BP.borrowed.kind:ownKind();}
const ballColor=k=>BP.borrowed?BP.borrowed.c:((SAVE.look.extras||{})[k==='soccer'?'ball':'bball']);
function ballBusy(){return boardBusy()||SK.on;}
// (the moves wheel is first drawn before this file runs, so these are hoisted functions)
function ballActs(){const k=ballKind();return k&&!ballBusy()?[['kick',k==='soccer'?'⚽':'🏀',k==='soccer'?'Kick':'Pass']]:[];}
const ballNet=()=>{const n=window.__net;return n&&n.live()?n:null;};
function myBallMesh(kind){const m=BP.m[kind]||(BP.m[kind]=ballMesh(kind));const c=ballColor(kind);if(m.userData.c!==c){m.userData.c=c;m.material=ballMat(kind,c);}return m;}
function ballHome(quiet){BP.st='hand';BP.to=null;BP.npc=null;BP.v.set(0,0,0);if(!quiet)sfx('pop');}

// who to pass to: the closest townsperson or online friend, a bit more likely the one you're facing
function ballTarget(){const P=player.pos,fx=Math.sin(player.face),fz=Math.cos(player.face);let best=null,bs=1e9;
  const look=(pos,o)=>{const dx=pos.x-P.x,dz=pos.z-P.z,d=Math.hypot(dx,dz);if(d<1.2||d>15)return;const s=d-3.5*(dx*fx+dz*fz)/d;if(s<bs){bs=s;best=o;}};
  for(const f of FRIENDS)if(f.g.visible!==false)look(f.pos,{npc:f,pos:f.pos});
  if(ballNet()&&mapOthers)for(const [id,o] of mapOthers)look(o.pos,{net:id,pos:o.pos,name:o.name});
  return best;}
// throw or kick the ball from p toward a spot
function ballLaunch(kind,from,to){const p=BP.p,v=BP.v;p.copy(from);const dx=to.x-from.x,dz=to.z-from.z,d=Math.hypot(dx,dz)||1;
  if(kind==='soccer'){const s=Math.min(16,d*1.35+2.2);v.set(dx/d*s,d>8?2.6:.4,dz/d*s);}
  else{const T=.42+d*.045,ty=groundAt(to.x,to.z)+1.05;v.set(dx/T,(ty-from.y+.5*14*T*T)/T,dz/T);}
  BP.flyT=0;}
function kickBall(){const kind=ballKind();if(!kind||closetOpen||!started||ballBusy())return;const P=player.pos;
  if(BP.st==='fly'||BP.st==='npc'||BP.st==='away'){toast(kind==='soccer'?'Wait for the ball to come back! ⚽':'Wait for the ball to come back! 🏀');return;}
  if(BP.st!=='hand'&&Math.hypot(BP.p.x-P.x,BP.p.z-P.z)>1.7){toast(kind==='soccer'?'Run to the ball first! ⚽':'Go get the ball first! 🏀');return;}
  const fx=Math.sin(player.face),fz=Math.cos(player.face);
  // soccer: kicked off the ground in front of your feet. basketball: passed from the chest
  const from=kind==='soccer'?new THREE.Vector3(P.x+fx*.42,groundAt(P.x+fx*.42,P.z+fz*.42)+BALL_R.soccer,P.z+fz*.42):new THREE.Vector3(P.x+fx*.35,P.y+1.05,P.z+fz*.35);
  ballAct(av,kind==='soccer'?'kick':'pass');
  const tg=ballTarget();
  if(tg){ballLaunch(kind,from,tg.pos);BP.st='fly';BP.to=tg;
    if(tg.npc){tg.npc.tgt=null;tg.npc.wait=Math.max(tg.npc.wait,4);}
    if(tg.net){const n=ballNet();if(n){n.send({t:'ball',k:'pass',to:tg.net,kind,c:ballColor(kind),p:BP.p.toArray().map(x=>+x.toFixed(2)),v:BP.v.toArray().map(x=>+x.toFixed(2))});
      if(BP.borrowed)BP.borrowed.gone=true;}}}
  else{const d=kind==='soccer'?11:6;ballLaunch(kind,from,new THREE.Vector3(P.x+fx*d,0,P.z+fz*d));if(kind==='soccer')BP.v.y=3.2;BP.st='loose';BP.to=null;}
  BP.still=0;tone(kind==='soccer'?150:220,.08,'sine',.16);tone(kind==='soccer'?90:140,.06,'square',.05,.02);did('ball',kind==='soccer'?'kick':'pass');}

// the ball flying, bouncing and rolling. Returns true when it hits the ground hard enough to make a sound.
const ballOld=new THREE.Vector3();
function ballPhys(kind,p,v,dt){const R=BALL_R[kind];ballOld.copy(p);v.y-=14*dt;p.addScaledVector(v,dt);
  let g=groundAt(p.x,p.z)+R;if(g-ballOld.y>.42+R){p.x=ballOld.x;p.z=ballOld.z;v.x*=-.4;v.z*=-.4;g=groundAt(p.x,p.z)+R;}// a step too tall to roll up
  let thud=false;if(p.y<=g){p.y=g;if(v.y<-1.2){thud=v.y<-2;v.y=-v.y*(kind==='soccer'?.4:.74);}else v.y=0;}
  if(p.y<=g+.02){const f=Math.pow(kind==='soccer'?.32:.5,dt);v.x*=f;v.z*=f;}
  // trees, walls and the edge of the island
  const ox=p.x,oz=p.z;collide(p,R);const nx=p.x-ox,nz=p.z-oz,nl=Math.hypot(nx,nz);if(nl>1e-5){const ux=nx/nl,uz=nz/nl,dot=v.x*ux+v.z*uz;if(dot<0){v.x-=1.6*dot*ux;v.z-=1.6*dot*uz;}}
  return thud;}

const bTmp=new THREE.Vector3(),bTmp2=new THREE.Vector3();
anims.push((t,dt)=>{if(!started||!av)return;
  const kind=ballKind(),P=player.pos,now=performance.now()/1000;
  // the borrowed ball goes away if its owner leaves the room
  if(BP.borrowed&&(!ballNet()||!mapOthers||!mapOthers.has(BP.borrowed.from))&&BP.st!=='fly'){BP.borrowed=null;ballHome(true);return;}
  {const key=kind+(ballBusy()?'b':'');if(key!==BP.actsKey){BP.actsKey=key;renderActions();}}
  for(const k in BP.m)if(k!==kind)BP.m[k].visible=false;
  if(kind!==BP.kind){BP.kind=kind;ballHome(true);if(!kind)av.ballMove=null;}
  if(!kind){ballSend(null);return;}
  const m=myBallMesh(kind),R=BALL_R[kind],busy=ballBusy();
  // in the closet you see it in your hand; during games and skating it's put away
  if(closetOpen||busy){if(BP.st==='fly'&&BP.to&&BP.to.net){BP.st='away';BP.awayT=0;BP.to=null;}else if(BP.st!=='away')ballHome(true);m.visible=false;if(av.handBall)av.handBall.visible=!busy;av.ballMove=null;ballSend(null);return;}
  if(av.handBall)av.handBall.visible=false;m.visible=BP.st!=='away';
  const moving=player.speed>.6,fx=Math.sin(player.face),fz=Math.cos(player.face);
  if(BP.st==='hand'){
    if(kind==='soccer'){if(moving&&player.onGround){BP.st='loose';BP.flyT=1;BP.p.set(P.x+fx*.45,groundAt(P.x+fx*.45,P.z+fz*.45)+R,P.z+fz*.45);BP.v.set(fx*player.speed*1.3,0,fz*player.speed*1.3);BP.still=0;}
      else{handSpot(av,kind,BP.p);if(av.ballMove&&!av.ballMove.act)av.ballMove=null;}}
    else{if(moving&&player.onGround){const d=dribbleSpot(av,t,BP.p);if(BP.u<.5&&d.u>=.5)tone(110,.05,'sine',.07);BP.u=d.u;av.ballMove=Object.assign(av.ballMove||{},{drib:d.s});}
      else{handSpot(av,kind,BP.p);if(av.ballMove){av.ballMove.drib=null;if(!av.ballMove.act)av.ballMove=null;}}}
    m.position.copy(BP.p);}
  else{if(av.ballMove&&av.ballMove.drib!=null){av.ballMove.drib=null;if(!av.ballMove.act)av.ballMove=null;}}
  if(BP.st==='loose'||BP.st==='fly'){const vx=BP.v.x,vz=BP.v.z;
    if(ballPhys(kind,BP.p,BP.v,dt))tone(kind==='soccer'?95:115,.05,'sine',.07);
    ballRoll(m,vx,vz,dt,R);m.position.copy(BP.p);
    const dx=BP.p.x-P.x,dz=BP.p.z-P.z,d=Math.hypot(dx,dz),onG=BP.p.y<groundAt(BP.p.x,BP.p.z)+R+.05;
    if(BP.st==='loose'){BP.flyT+=dt;
      if(kind==='soccer'){
        // dribbling: the ball at your feet gets a little touch ahead the way you're walking
        if(d<.55&&onG&&BP.p.y<P.y+.5){if(moving){const s=player.speed*1.35+.5;BP.v.set(fx*s,0,fz*s);BP.still=0;if(!BP.tap)tone(140,.03,'sine',.05);BP.tap=1;}
          else if(BP.flyT>.4){BP.v.x*=.6;BP.v.z*=.6;if(d<.38&&d>1e-4){BP.p.x=P.x+dx/d*.38;BP.p.z=P.z+dz/d*.38;}}}else BP.tap=0;
        // stand still next to it and you pick it up
        if(!moving&&d<1.4&&Math.hypot(BP.v.x,BP.v.z)<.4){BP.still+=dt;if(BP.still>2.2)ballHome();}else BP.still=0;}
      else if(BP.flyT>.6&&d<.8&&BP.p.y<P.y+1.6){ballHome();}// walk up to the basketball to pick it up
      if(d>35){ballHome(true);toast(kind==='soccer'?'⚽ Your ball is back!':'🏀 Your ball is back!');}}
    else{// passing to someone: steer it toward them as it goes, and they catch it when it gets there
      BP.flyT+=dt;const tg=BP.to,tp=tg.me?P:tg.npc?tg.npc.pos:(mapOthers&&mapOthers.get(tg.net)||{}).pos;
      if(!tp){BP.st='loose';BP.to=null;}
      else{const ex=tp.x-BP.p.x,ez=tp.z-BP.p.z,ed=Math.hypot(ex,ez),hs=Math.hypot(BP.v.x,BP.v.z);
        if(kind==='soccer'&&onG&&hs>.3&&ed>.2){const k=Math.min(1,dt*5);BP.v.x+=(ex/ed*hs-BP.v.x)*k;BP.v.z+=(ez/ed*hs-BP.v.z)*k;}
        const reach=ed<.8&&BP.p.y<tp.y+1.8,stopped=hs<.6&&onG&&ed<5;
        if(reach||stopped||BP.flyT>5){
          if(tg.me){BP.passes++;BP.to=null;sfx('pop');
            if(kind==='soccer'){BP.st='loose';BP.flyT=1;BP.v.set(0,0,0);if(d>.5){BP.p.x=P.x+fx*.45;BP.p.z=P.z+fz*.45;}}else ballHome(true);
            if(BP.passes%5===0)banner(`${kind==='soccer'?'⚽':'🏀'} ${BP.passes} passes in a row!`);}
          else if(tg.npc){BP.st='npc';BP.npc=tg.npc;BP.hold=.9+Math.random()*.6;BP.to=null;const f=tg.npc;f.tgt=null;f.wait=Math.max(f.wait,3);
            friendBubble(f,rnd(kind==='soccer'?['Nice pass! ⚽','Got it! 🙌','Ooh, good kick!','Here it comes back!']:['Nice pass! 🏀','Got it! 🙌','Catch! 🏀','Good one!']));}
          else{BP.st='away';BP.awayT=0;BP.to=null;if(BP.borrowed&&BP.borrowed.gone){BP.borrowed=null;}}}}}}
  else if(BP.st==='npc'){const f=BP.npc;f.face=Math.atan2(P.x-f.pos.x,P.z-f.pos.z);f.g.rotation.y=f.face;f.tgt=null;f.wait=Math.max(f.wait,1.5);
    const ffx=Math.sin(f.face),ffz=Math.cos(f.face);
    if(kind==='soccer')BP.p.set(f.pos.x+ffx*.42,groundAt(f.pos.x+ffx*.42,f.pos.z+ffz*.42)+R,f.pos.z+ffz*.42);else handSpot(f,kind,BP.p);
    m.position.copy(BP.p);BP.hold-=dt;
    if(BP.hold<=0){ballAct(f,kind==='soccer'?'kick':'pass');if(kind==='bball')BP.p.set(f.pos.x+ffx*.35,f.pos.y+1.05,f.pos.z+ffz*.35);
      ballLaunch(kind,BP.p,P);BP.st='fly';BP.to={me:1};BP.npc=null;tone(kind==='soccer'?150:220,.08,'sine',.12);}
    if(Math.hypot(f.pos.x-P.x,f.pos.z-P.z)>40)ballHome(true);}
  else if(BP.st==='away'){m.visible=false;BP.awayT+=dt;// an online friend has it: they pass it back
    if(BP.awayT>45){ballHome(true);toast(kind==='soccer'?'⚽ Your ball is back!':'🏀 Your ball is back!');}}
  ballSend(kind,dt);});

/* ---------- online: friends see your ball (one entry in SHOW, 26c-friends-see.js) ----------
   SHOW sends what kind of ball you have and what it's doing when that changes: in your hand, bouncing beside you
   (their phone bounces it in time with your walk), out on the ground (then its spot comes 10 times a second as
   {t:'ball',k:'at',p}), put away, or gone to someone else. A pass is {t:'ball',k:'pass',to,kind,c,p,v}. */
function ballMd(){const k=ballKind();if(!k)return null;if(closetOpen)return 'hand';if(ballBusy())return 'away';
  if(BP.st==='away'||(BP.st==='fly'&&BP.to&&BP.to.net))return 'gone';
  if(BP.st==='hand')return av&&av.ballMove&&av.ballMove.drib!=null?'drib':'hand';return 'free';}
SHOW.push({k:'ball',
  mine(){const kind=ballKind();return kind?{kind,c:ballColor(kind)||null,md:ballMd()}:null;},
  on(f,d){if(d.kind!=='soccer'&&d.kind!=='bball')return null;const m=ballMesh(d.kind);m.material=ballMat(d.kind,typeof d.c==='string'?d.c.slice(0,30):null);return {m};},
  step(f,d,dt,h){const a=f.a,m=h.m,ex=(a.look&&a.look.extras)||{},theirs=!!a.handBall&&!!(d.kind==='soccer'?ex.ball:ex.bball);
    const drib=d.md==='drib';if(!drib&&a.ballMove&&a.ballMove.drib!=null){a.ballMove.drib=null;if(!a.ballMove.act)a.ballMove=null;}
    if(a.handBall)a.handBall.visible=d.md==='hand'&&theirs;
    m.visible=!(d.md==='hand'&&theirs)&&d.md!=='away'&&d.md!=='gone';if(!m.visible)return;
    if(drib){const r=dribbleSpot(a,performance.now()/1000,m.position);a.ballMove=Object.assign(a.ballMove||{},{drib:r.s});return;}
    if(d.md==='hand'){handSpot(a,d.kind,m.position);return;}
    if(!f.ballAt)return;bTmp2.copy(m.position);if(m.position.distanceTo(f.ballAt)>6)m.position.copy(f.ballAt);else m.position.lerp(f.ballAt,Math.min(1,dt*12));
    ballRoll(m,(m.position.x-bTmp2.x)/Math.max(dt,1e-3),(m.position.z-bTmp2.z)/Math.max(dt,1e-3),dt,BALL_R[d.kind]);},
  off(f,h){if(!h)return;scene.remove(h.m);const a=f.a;if(a){if(a.handBall)a.handBall.visible=true;if(a.ballMove&&a.ballMove.drib!=null){a.ballMove.drib=null;if(!a.ballMove.act)a.ballMove=null;}}}});
// while my ball is out on the ground, tell the room where it is
function ballSend(kind,dt){const n=ballNet();if(!n||!kind||ballMd()!=='free')return;BP.sendT-=dt;if(BP.sendT>0)return;BP.sendT=.1;
  n.send({t:'ball',k:'at',p:BP.p.toArray().map(x=>+x.toFixed(2))});}
function ballFromNet(id,name,d){if(!d||d.t!=='ball')return;const o=mapOthers&&mapOthers.get(id);
  if(d.k==='at'&&Array.isArray(d.p)&&o){(o.ballAt||(o.ballAt=new THREE.Vector3())).set(+d.p[0]||0,+d.p[1]||0,+d.p[2]||0);}
  else if(d.k==='pass'&&(d.kind==='soccer'||d.kind==='bball')){if(o&&o.a)ballAct(o.a,d.kind==='soccer'?'kick':'pass');
    const n=ballNet(),me=n&&n.id&&n.id();if(!me||d.to!==me)return;
    // it's coming to me: it's my ball now (my own again if it's the one I passed away)
    BP.borrowed=d.kind===ownKind()?null:{kind:d.kind,c:typeof d.c==='string'?d.c.slice(0,30):null,from:id};
    BP.kind=ballKind();BP.st='fly';BP.to={me:1};BP.flyT=0;BP.npc=null;
    if(Array.isArray(d.p))BP.p.set(+d.p[0]||0,+d.p[1]||0,+d.p[2]||0);if(Array.isArray(d.v))BP.v.set(+d.v[0]||0,+d.v[1]||0,+d.v[2]||0);
    toast(`${name||'Your friend'} passed you the ball! Tap ${d.kind==='soccer'?'⚽ Kick':'🏀 Pass'} to send it back`);}}
addEventListener('load',()=>{if(window.__net)window.__net.on(ballFromNet);if(window.__game)window.__game.ball=()=>BP;});
// ---- src/26e-jump-park.js ----
/* ================= 🤸 JUMP PARK: bouncing, flips, slam dunks and the foam pit =================
   The park itself (trampolines, pads, the block, the foam pit, the hoops) is built in 12e-place-jump-park.js.
   - Step onto any trampoline and you start bouncing on your own (25-game-loop.js asks jpLand() when you land).
   - Tap Jump (or Space) while bouncing and the next bounce goes higher, up to a big bounce. Big bounces do a trick:
     front flip, back flip, a spin, and a double flip at the very top.
   - Bounce up to a hoop on the back wall and grab the rim for a slam dunk.
   - Jump off the padded block into the foam pit and the cubes fly everywhere.
   - Friends online see your flips (the 'flip' entry in SHOW at the bottom); townspeople bounce when they're on a trampoline. */
const JPS={on:false,want:0,since:9,base:0,peaked:true,trick:null,trickN:0,cy:null,wade:0,hinted:false,tk:0};
const JP_MIN=5.4,JP_MAX=11,JP_FLIP=9;// bounce speeds: a gentle bounce, the biggest bounce, and how big a bounce does a trick
const JP_TRICKS=[{k:'front',name:'Front flip',ax:'x',full:Math.PI*2},{k:'back',name:'Back flip',ax:'x',full:-Math.PI*2},{k:'spin',name:'Spin',ax:'y',full:Math.PI*2},
  {k:'back',name:'Back flip',ax:'x',full:-Math.PI*2},{k:'front',name:'Front flip',ax:'x',full:Math.PI*2}];
const JP_DOUBLE=[{k:'dfront',name:'DOUBLE front flip',ax:'x',full:Math.PI*4},{k:'dback',name:'DOUBLE back flip',ax:'x',full:-Math.PI*4}];
const jpTrickById=k=>[...JP_TRICKS,...JP_DOUBLE].find(t=>t.k===k);
const jpSave=()=>SAVE.jump||(SAVE.jump={best:0,flips:0,dunks:0});
const jpBusy=()=>!!(barnRide||SK.on||BIKE.on);// on a ride, a skateboard or the bike you just roll over the trampolines
function jpLocal(x,z){const J=Z.jump;if(Math.abs(x-J.x)>9||Math.abs(z-J.z)>9)return null;return J.toLocal(x,z);}

// you just came down on the ground at height gy: if it's a trampoline, bounce (return true), otherwise land normally
function jpLand(p,gy){const L=jpLocal(p.x,p.z);if(!L||jpBusy()){if(JPS.on)jpStop();return false;}
  const T=jpMatAt(L[0],L[1]),impact=Math.max(0,-player.vy);
  if(!T){if(JPS.on)jpStop();const P=JP.pit;if(impact>2.5&&L[0]>P.x0&&L[0]<P.x1&&L[1]>P.z0&&L[1]<P.z1)jpSplash(L[0],L[1],impact);return false;}
  const v=JPS.want>0?Math.min(JP_MAX,Math.max(7.6,impact+2.1)):Math.max(JP_MIN,impact*.8);
  if(JPS.trick)jpTrickDone();
  p.y=gy;player.vy=v;player.onGround=false;JPS.on=true;JPS.want=0;JPS.since=0;JPS.base=gy;JPS.peaked=false;
  T.v-=Math.min(2.6,.6+impact*.2);// the mat sinks under you and springs back
  const k=v/JP_MAX;tone(150+k*120,.22,'sine',.13,0,420+k*380);tone(90,.12,'triangle',.07);
  if(v>=JP_FLIP-.01)jpTrickStart(v);
  if(!JPS.hinted&&JPS.since===0){JPS.hinted=true;setTimeout(()=>toast(isTouch?'Tap ⬆️ Jump each time you land to bounce higher! 🤸':'Press Space each time you land to bounce higher! 🤸'),400);}
  return true;}
// the Jump button while bouncing: bounce higher on the next landing (or right now, if you only just took off)
function jpJump(){if(!JPS.on||jpBusy())return false;
  if(JPS.since<.14&&player.vy>0){player.vy=Math.min(JP_MAX,player.vy+2.1);if(player.vy>=JP_FLIP&&!JPS.trick)jpTrickStart(player.vy);sfx('jump');}
  else JPS.want=.5;
  return true;}
function jpStop(){JPS.on=false;JPS.want=0;if(JPS.trick){JPS.trick=null;av.g.rotation.x=0;}}

function jpTrickStart(v){const S=jpSave();const list=v>=JP_MAX-.3?JP_DOUBLE:JP_TRICKS;const tr=list[(JPS.trickN++)%list.length];
  JPS.trick={...tr,t:0,T:2*v/18};toast(`🤸 ${tr.name}!`);}
function jpTrickDone(){const tr=JPS.trick;JPS.trick=null;av.g.rotation.x=0;if(!tr||tr.t<tr.T*.7)return;
  const S=jpSave();S.flips=(S.flips||0)+1;persist();if(window.__game&&window.__game.onJump)window.__game.onJump('flip',tr.k);
  burst(new THREE.Vector3(player.pos.x,player.pos.y+1,player.pos.z),rnd(['#ffd21f','#ff6fae','#b388ff','#4fb6ff']),18,2.2,.2);}
// turn an avatar for a trick: x tricks flip head over heels around the hips, y tricks spin around
function jpPose(g,tr,f){const ang=tr.full*f;g.rotation.order='YXZ';
  if(tr.ax==='y'){g.rotation.y+=ang;g.rotation.x=0;return;}
  const P=.85,th=g.rotation.y,s=Math.sin(ang);g.rotation.x=ang;g.position.x-=Math.sin(th)*P*s;g.position.z-=Math.cos(th)*P*s;g.position.y+=P-P*Math.cos(ang);}
const jpEase=f=>f>=1?1:(1-Math.cos(Math.PI*f))/2;

// the camera follows only part of each bounce, so the screen doesn't jump up and down with you
function jpCamY(py,dt){if(JPS.on){const tgt=JPS.base+(py-JPS.base)*.6;JPS.cy=JPS.cy==null?py:JPS.cy+(tgt-JPS.cy)*Math.min(1,dt*5);return JPS.cy;}
  if(JPS.cy!=null){JPS.cy+=(py-JPS.cy)*Math.min(1,dt*8);if(Math.abs(py-JPS.cy)<.01)JPS.cy=null;else return JPS.cy;}return py;}

// a big landing in the foam pit throws cubes everywhere
function jpSplash(lx,lz,impact){const P=JP.pit,k=Math.min(1.6,impact/8);
  for(const c of P.cubes){const dx=c.bx-lx,dz=c.bz-lz,d=Math.hypot(dx,dz);if(d>1.3*k+.4)continue;const f=1-d/(1.3*k+.5);
    c.live=true;c.vy=(2.5+Math.random()*3)*f*k+.8;c.vx=(dx/(d||1))*(1.5+Math.random()*2)*f;c.vz=(dz/(d||1))*(1.5+Math.random()*2)*f;}
  tone(220,.25,'sine',.12,0,90);tone(500,.18,'triangle',.05,.03,200);for(let i=0;i<5;i++)tone(300+Math.random()*500,.06,'sine',.04,.05+i*.04);
  if(window.__game&&window.__game.onJump)window.__game.onJump('pit');}

// grab the rim: a ball drops through the net
const JPB=[];
function jpDunk(h){const S=jpSave();S.dunks=(S.dunks||0)+1;persist();h.cool=1.4;h.swish=1;h.shake=1;
  const z=Z.jump,b=M(sph(.12,16,12),phys('#ff7a1f',{roughness:.6}),h.x,h.y+.3,h.z,z.g,true,false);JPB.push({m:b,vy:-1,t:0});
  tone(523,.1,'triangle',.12);tone(659,.1,'triangle',.12,.08);tone(784,.22,'triangle',.14,.16);tone(120,.15,'sine',.15,.02);
  const [wx,wz]=z.toWorld(h.x,h.z);burst(new THREE.Vector3(wx,h.y,wz),'#ff8a1f',30,2.6,.22);
  toast(S.dunks===1?'🏀 SLAM DUNK! You reached the rim!':`🏀 SLAM DUNK! (${S.dunks})`);if(window.__game&&window.__game.onJump)window.__game.onJump('dunk');}

onTick.push(dt=>{if(!Z.jump||!JP.block)return;const p=player.pos,t=clock.elapsedTime;
  // the mats spring back after you land
  for(const T of JP.mats){if(T.dip===0&&T.v===0)continue;T.v+=(-T.dip*160-T.v*11)*dt;T.dip+=T.v*dt;if(Math.abs(T.dip)<.001&&Math.abs(T.v)<.01){T.dip=0;T.v=0;}
    T.m.position.y=JP.MAT+Math.max(-.18,Math.min(.06,T.dip));}
  for(const h of JP.hoops)h.cool-=dt;
  for(let i=JPB.length-1;i>=0;i--){const b=JPB[i];b.t+=dt;b.vy-=12*dt;b.m.position.y+=b.vy*dt;b.m.rotation.x+=dt*6;if(b.m.position.y<JP.MAT+.12){b.m.position.y=JP.MAT+.12;b.vy=-b.vy*.55;}
    if(b.t>2.2){b.m.parent.remove(b.m);b.m.geometry.dispose();JPB.splice(i,1);}}
  // first time you walk in: how it works
  if(curZone===Z.jump&&!JPS.hinted&&started&&!JPS.tk){JPS.tk=1;setTimeout(()=>{if(!JPS.on)toast('Hop on a trampoline and bounce! 🤸 Tap Jump when you land to go higher');},1500);}
  // townspeople bounce when they're on a trampoline
  for(const f of FRIENDS){const L=jpLocal(f.pos.x,f.pos.z);if(L&&jpMatAt(L[0],L[1])){f.ph=f.ph??Math.random()*6;const s=Math.abs(Math.sin(t*3.6+f.ph));f.g.position.y=JP.MAT+s*.85;}}
  if(!JPS.on){
    // wading through the foam pit nudges the cubes
    const L=jpLocal(p.x,p.z),P=JP.pit;if(L&&L[0]>P.x0&&L[0]<P.x1&&L[1]>P.z0&&L[1]<P.z1&&player.speed>.5){JPS.wade-=dt;if(JPS.wade<=0){JPS.wade=.12;
      for(const c of P.cubes){if(c.live||c.by<0)continue;const d=Math.hypot(c.bx-L[0],c.bz-L[1]);if(d<.55&&Math.random()<.5){c.live=true;c.vy=1+Math.random()*1.4;c.vx=(c.bx-L[0])*2;c.vz=(c.bz-L[1])*2;}}}}
    return;}
  JPS.want-=dt;JPS.since+=dt;
  if(jpBusy()||!jpLocal(p.x,p.z)){jpStop();return;}
  // how high did that go?
  if(!JPS.peaked&&player.vy<=0){JPS.peaked=true;const hgt=p.y-JPS.base,S=jpSave();if(hgt>2&&hgt>(S.best||0)+.25){S.best=Math.round(hgt*10)/10;persist();if(hgt>3)toast(`🏆 Your highest bounce yet: ${S.best.toFixed(1)} m!`);}}
  // the trick
  if(JPS.trick){const tr=JPS.trick;tr.t+=dt;jpPose(av.g,tr,jpEase(Math.min(1,tr.t/(tr.T*.8))));}
  // a hoop right above you?
  const L=jpLocal(p.x,p.z);for(const h of JP.hoops){if(h.cool>0)continue;if(Math.hypot(L[0]-h.x,L[1]-h.z)<.9&&p.y+2.05>h.y&&p.y+1.2<h.y+.2)jpDunk(h);}});

// 👭 friends online see your flips and spins
SHOW.push({k:'flip',
  mine(){const tr=JPS.trick;return tr?{k:tr.k,n:JPS.trickN,T:Math.round(tr.T*100)/100}:null;},
  on(f,d){const tr=jpTrickById(d.k);return tr?{tr:{...tr,T:Math.max(.3,Math.min(2,+d.T||1))},t:0}:null;},
  step(f,d,dt,h){if(!h||!f.a)return;h.t+=dt;const tr=h.tr;if(h.t>tr.T){f.a.g.rotation.x=0;return;}jpPose(f.a.g,tr,jpEase(Math.min(1,h.t/(tr.T*.8))));},
  off(f,h){if(f.a)f.a.g.rotation.x=0;}});
// for the test (3d/tests/jump-park.mjs)
Object.assign(window.__game,{JP,jumpPark:()=>({on:JPS.on,trick:JPS.trick&&JPS.trick.k,save:{...jpSave()},pitLive:JP.pit.cubes.filter(c=>c.live).length})});
// ---- src/26f-ocean.js ----
/* ================= 🌊 THE CANAL AND DOLPHIN BAY: swim all the way around the island, with dolphins, a whale, a sea turtle and a seal =================
   - The coast is a canal: a ring of water (CANAL.inR to CANAL.outR) all the way around the island, with a grassy bank with palm trees on
     the far side. Walk off any shore (or jump off the dock) and you wade in, then swim. collide() (25-game-loop.js) asks seaKeep() whether
     you may be out there. The part right past the Beach is 🐬 Dolphin Bay (the 'bay' zone in 02-island.js); the rest is the 🌊 Canal.
   - For other files (the safari hippo swims here, zoo animals drink here): seaDepth(x,z) 0 on land .. 1 deep, inCanal(x,z),
     canalSpot(ang,t) a spot in the water (t 0 the island shore .. 1 the far bank), CANAL, WATER_Y the water line.
   - Swimming: the game still keeps you at ground height 0 (so the camera, stars and zones work as usual); this file just sinks
     your body into the water and poses you (crawl stroke when you move, treading water when you stop) after Avatar.update.
     Not on a bike, a skateboard or a barn ride: hop off first.
   - Sea animals: 🐬 three dolphins (one is Splash) and 🐋 Big Blue the humpback whale swim all the way round the canal, 🐢 Shelly the
     sea turtle paddles near the Beach, 🦭 Pip the seal sits on her rock in the bay, 🐠 Ray the manta ray glides round far out and
     🦦 Ollie the sea otter floats on his back off the Beach. They never follow you (only adopted pets do): swim
     up next to one and swim along beside it. They show on the minimap. Tap 🐟 Feed when you're close.
   - 🌊 Ocean challenges (the Ocean tab in challenges.js, ids in SEA_RIDES[].ids): finish all of an animal's challenges and you can
     ride it (🐢 Shelly, 🐬 Splash, 🐋 Big Blue, 🦭 Pip: she slides off her rock for you and swims home after).
   - 🦈 Ghost the great white swims round the canal by himself. Swim close to him and now and then he chases you (sharkStep below). Harmless:
     reach the shore to get away, or he bumps you and swims on. Finish his really hard 🌊 Ocean challenges and you can ride him.
   - Friends online see you swimming, and on your sea ride, through the 'sea' entry in SHOW (26c-friends-see.js).
   Everything is low-poly with a few shared materials and no textures, and each animal hides when it's far from you (iPhone memory). */
const BAY=Z.bay,WATER_Y=-.35,CANAL={inR:R+1.6,outR:R+17};
const CANAL_ZONE={id:'canal',name:'🌊 Canal',music:'sea-waves'};// where you are when you swim anywhere but the bay (25-game-loop.js)
MAPC.bay='#7fd6ee';
/* ---------- 🏝️ land on the far bank, and footbridges over the canal ----------
   Most of the far bank is scenery you can't reach, but an area listed in BANK_LAND is real land: walk over its footbridge (or swim
   across and wade out) and you can walk, ride and play there. a0..a1: the angles it covers (degrees, like ZONES), out: how far out
   from the middle of the island it reaches. own: it draws its own ground, so the bank's grass, sand and palm trees leave a gap there.
   BANK_BRIDGES: a footbridge at angle a (degrees), w wide. Its deck only counts as ground once you've stepped on it from one of its
   ends (BRG.on), so you can still swim under it. BANK_POOLS: pools on that land, f(x,z) gives how deep (0..1) it is there.
   BANK_GROUND: things you can stand on there, f(x,z) gives how high. */
// own: a place like the waterpark that does its own walking, wading and bridge (seaKeep, seaDepth and bankOK below), so bankLand leaves it out.
// Its entries are here, not in its own file, because the bank below is built before that file runs.
const BANK_LAND=[{id:'water',a0:220,a1:260,out:R+56,own:1}];// 💦 the waterpark (26w-waterpark.js)
const BANK_BRIDGES=[{id:'water',a:240,w:2.6,own:1,on:()=>false}];
const BANK_POOLS=[],BANK_GROUND=[],BRG={on:''};
var bankReady=false;// groundAt is asked before this file has run; it stays 0 until then
const bankAng=(x,z)=>(Math.atan2(x,z)*180/Math.PI+360)%360;
const bankSector=(x,z,m=0)=>{const a=bankAng(x,z);return BANK_LAND.find(s=>s.own&&a>=s.a0-m&&a<=s.a1+m);};
function onBankLand(x,z){const d=Math.hypot(x,z);if(d<CANAL.outR)return false;const s=bankSector(x,z);return !!s&&d<=s.out;}
// on a footbridge over the canal: {b, t 0 at the island .. 1 at the far bank, side: how far from its middle line}
function bridgeAt(x,z,any){const d=Math.hypot(x,z);if(d<R-1||d>BANK.in+2)return null;
  for(const b of BANK_BRIDGES){if(!b.own)continue;const a=deg(b.a),ux=Math.sin(a),uz=Math.cos(a),along=x*ux+z*uz,side=x*uz-z*ux;
    if(along>0&&(any||Math.abs(side)<b.w/2))return {b,t:(along-(R+.3))/(BANK.in+.8-(R+.3)),side,ux,uz,along};}
  return null;}
// the bridge deck arches up over the water
const bridgeH=t=>t<=0||t>=1?0:.12+1.25*Math.sin(Math.PI*t);
function bankGround(x,z){if(!bankReady||x*x+z*z<(R-1.5)*(R-1.5))return 0;let h=0;
  const b=bridgeAt(x,z);if(b&&(BRG.on||SW.k<.3))h=bridgeH(b.t);
  for(const f of BANK_GROUND){const g=f(x,z);if(g>h)h=g;}return h;}
// keeps p on the far-bank land it's standing on (and inside its edges). minD: how close to the water it may go
function bankHold(p,minD){const d=Math.hypot(p.x,p.z);if(d<minD)return false;const s=bankSector(p.x,p.z,4);if(!s)return false;
  const a=deg(Math.max(s.a0,Math.min(s.a1,bankAng(p.x,p.z)))),dd=Math.min(d,s.out-.5);p.x=Math.sin(a)*dd;p.z=Math.cos(a)*dd;return true;}
// for pets and friends (collide in 25-game-loop.js): they may be on the far-bank land and the bridges too
function bankOK(p){return bankReady&&(bankHold(p,CANAL.outR-.1)||!!bridgeAt(p.x,p.z));}
// how deep you are: 0 on the sand, 1 swimming (the island's sand edge ends at R+1.6)
// y (optional): how high you are; up on a footbridge over the water you're not swimming
function seaDepth(x,z,y){if(y>1.05)return 0;const d=Math.hypot(x,z);
  if(BRG.on&&bridgeAt(x,z))return 0;
  if(d>CANAL.outR-1.5&&bankReady&&bankSector(x,z)){// wading out onto the far-bank land, and its pools
    if(d<BANK.in)return Math.max(0,Math.min(1,(BANK.in-.2-d)/1.6));let m=0;for(const f of BANK_POOLS){const k=f(x,z);if(k>m)m=k;}return m;}
  return d>CANAL.outR?0:Math.max(0,Math.min(1,(d-(R+1.3))/2.6));}
function inCanal(x,z){const d=Math.hypot(x,z);return d>CANAL.inR&&d<CANAL.outR;}
// a spot in the canal at angle ang (like ZONES: x=sin, z=cos), t 0 at the island's shore .. 1 at the far bank
function canalSpot(ang,t){const r=CANAL.inR+(CANAL.outR-CANAL.inR)*t;return [Math.sin(ang)*r,Math.cos(ang)*r];}
let seaNoRideT=0;
// collide() asks: the player is past the island's edge; may they be out here? Keeps them on the water side of the far bank.
function seaKeep(p,lim){if(!started)return false;
  // on a footbridge: stay between its railings until you step off one end
  if(BRG.on){const b=bridgeAt(p.x,p.z,true);if(b){const w=b.b.w/2-.3,sd=Math.max(-w,Math.min(w,b.side));p.x=b.ux*b.along+b.uz*sd;p.z=b.uz*b.along-b.ux*sd;return true;}}
  const rider=(barnRide&&!barnRide.F.swim)||BIKE.on||SK.on;
  // on the far-bank land (the waterpark): walk and ride about, but riders don't go into the water
  if(bankHold(p,rider?BANK.in:CANAL.outR-.1))return true;
  const d=Math.hypot(p.x,p.z),sec=bankSector(p.x,p.z);
  if(rider){// a barn ride with swim:1 in FARM (the safari hippo) may go in
    if(sec&&d>(CANAL.inR+CANAL.outR)/2){p.x*=BANK.in/d;p.z*=BANK.in/d;return true;}// riding by the water on the far-bank land: stay on the land
    if(performance.now()>seaNoRideT){seaNoRideT=performance.now()+5000;toast('Hop off to go swimming 🏊');}return false;}
  const edge=sec?BANK.in:CANAL.outR-.5;if(d>edge){p.x*=edge/d;p.z*=edge/d;}// you can wade out onto the far-bank land
  return true;}

/* ---------- the far bank of the canal: sand, grass and palm trees all the way round ---------- */
const BANK={in:CANAL.outR+1.2,out:CANAL.outR+18};
// Other bits of the far bank you can walk on, and footbridges over to them, pushed into BANK_LAND and BANK_BRIDGES from their own files:
//   BANK_LAND:    {a0,a1,out}  a sector in degrees (like ZONES: 0 is +z, 90 is +x), walkable out to distance out from the middle
//   BANK_BRIDGES: {a,w,on(p)}  a footbridge at angle a (degrees), w wide; on(p) says if p is up on its deck
// collide() (25-game-loop.js) asks this when p is past the island's edge: true if p may be there (it may move p back onto the land)
function bankLand(p){const d=Math.hypot(p.x,p.z);if(d<R)return false;const a=bankAng(p.x,p.z);
  for(const b of BANK_BRIDGES){if(b.own)continue;const da=(((a-b.a)%360)+540)%360-180,side=Math.abs(Math.sin(da*Math.PI/180)*d);if(Math.abs(da)<90&&side<b.w/2&&d<BANK.in+3&&b.on(p))return true;}
  for(const L of BANK_LAND){if(L.own||a<L.a0||a>L.a1)continue;
    if(d>=CANAL.outR-.5){if(d>L.out){p.x*=L.out/d;p.z*=L.out/d;}return true;}
    // on a bike, a skateboard or a ride you can't go in the water, so you stay on the bank instead of popping back to the island
    if(p===player.pos&&d>CANAL.outR-4&&((barnRide&&!barnRide.F.swim)||BIKE.on||SK.on)){const k=(CANAL.outR-.4)/d;p.x*=k;p.z*=k;return true;}}
  return false;}
{const sand=std('#f1d9a6',{map:TEX.sand,roughness:1});
  // the sandy slope up out of the water (seen from the island side), the grass on top, and the slope down to the open sea
  const wall=M(new THREE.CylinderGeometry(BANK.in,CANAL.outR-1,3,128,1,true),sand.clone(),0,-1.5,0,scene,false,true);wall.material.side=THREE.BackSide;
  // the grass, the sand and the slope down to the open sea go all the way round, except where a BANK_LAND area draws its own ground
  const own=BANK_LAND.filter(s=>s.own).sort((a,b)=>a.a0-b.a0),spans=[];
  {let a=own.length?own[own.length-1].a1-360:0;for(const s of own){spans.push([a,s.a0]);a=s.a1;}if(!own.length)spans.push([0,360]);else spans.push([own[own.length-1].a1,own[0].a0+360]);}
  for(const [a0,a1] of spans){if(a1-a0<.5)continue;const n=Math.max(8,Math.round(128*(a1-a0)/360)),t0=deg(a0-90),tl=deg(a1-a0);// RingGeometry angle 0 is ZONES angle 90
    const top=M(new THREE.RingGeometry(BANK.in,BANK.out,n,1,t0,tl),groundMat,0,.004,0,scene,false,true);top.rotation.x=-Math.PI/2;
    const beach=M(new THREE.RingGeometry(BANK.in,BANK.in+2.2,n,1,t0,tl),sand,0,.012,0,scene,false,false);beach.rotation.x=-Math.PI/2;
    M(new THREE.CylinderGeometry(BANK.out,BANK.out+2,3,n,1,true,deg(a0),tl),sand,0,-1.5,0,scene,false,true);}
  sand.polygonOffset=true;sand.polygonOffsetFactor=-2;sand.polygonOffsetUnits=-2;
  const ownAt=(x,z)=>{const a=bankAng(x,z);return own.some(s=>a>s.a0-3&&a<s.a1+3);};
  // palm trees and bushes: one shape each for all of them (instanced), so the whole bank is only a few draws
  let sd=7;const rr=()=>((sd=(sd*16807)%2147483647)-1)/2147483646;
  const NP=46,NB=90,mx=new THREE.Matrix4(),q=new THREE.Quaternion(),e=new THREE.Euler(),v=new THREE.Vector3(),sc=new THREE.Vector3();
  const trunk=new THREE.InstancedMesh(cyl(.13,.2,4.2,7),std('#9a7046',{roughness:.9}),NP),leaf=new THREE.InstancedMesh(new THREE.ConeGeometry(.5,2.6,4,1),std('#3f9a3a',{roughness:.7,side:THREE.DoubleSide}),NP*6),
    bush=new THREE.InstancedMesh(sph(1,8,6),std('#4fa645',{roughness:.9}),NB);
  let li=0;
  const placeHere=(x,z)=>ZONES.some(o=>o.d>CANAL.outR&&Math.hypot(x-o.x,z-o.z)<o.r+4);// no palms where a place stands on the far bank
  for(let i=0;i<NP;i++){const a=(i+rr()*.6)/NP*Math.PI*2,r=BANK.in+3.5+rr()*9,x=Math.sin(a)*r,z=Math.cos(a)*r,lean=(rr()-.5)*.35;let s=.8+rr()*.5;if(placeHere(x,z)||ownAt(x,z))s=.001;
    e.set(lean,rr()*6,lean*.5);q.setFromEuler(e);mx.compose(v.set(x,2.1*s,z),q,sc.set(s,s,s));trunk.setMatrixAt(i,mx);
    const tx=x+Math.sin(e.y)*lean*2*s,tz=z+Math.cos(e.y)*lean*2*s;
    for(let k=0;k<6;k++){e.set(Math.PI/2+.55,k/6*Math.PI*2+rr(),0,'YXZ');q.setFromEuler(e);const d=new THREE.Vector3(0,0,1.1*s).applyQuaternion(new THREE.Quaternion().setFromEuler(new THREE.Euler(0,e.y,0)));
      mx.compose(v.set(tx+d.x,4.2*s,tz+d.z),q,sc.set(1.3*s,s,.15*s));leaf.setMatrixAt(li++,mx);}}
  for(let i=0;i<NB;i++){const a=rr()*Math.PI*2,r=BANK.in+2.6+rr()*13;let s=.5+rr()*.6;if(placeHere(Math.sin(a)*r,Math.cos(a)*r)||ownAt(Math.sin(a)*r,Math.cos(a)*r))s=.001;mx.compose(v.set(Math.sin(a)*r,s*.35,Math.cos(a)*r),q.identity(),sc.set(s*1.2,s*.75,s*1.2));bush.setMatrixAt(i,mx);}
  for(const m of [trunk,leaf,bush]){m.instanceMatrix.needsUpdate=true;m.castShadow=false;m.receiveShadow=false;m.computeBoundingSphere();scene.add(m);}}
// on the minimap and the big map (26-map.js drawWorld): the far bank all the way round
function canalBank(x,cx,cy,k){x.beginPath();x.arc(cx,cy,BANK.out*k,0,Math.PI*2);x.fillStyle='#8fd36f';x.fill();
  x.beginPath();x.arc(cx,cy,BANK.in*k,0,Math.PI*2);x.fillStyle='#f1d9a6';x.fill();
  x.beginPath();x.arc(cx,cy,(CANAL.outR+.2)*k,0,Math.PI*2);x.fillStyle='#2ab0d4';x.fill();}

/* ---------- the swimming pose (for you and for friends online) ---------- */
// k: 0 standing .. 1 swimming, mv: 0 still .. 1 full speed, ph: stroke time. Run it after Avatar.update. Returns how far to sink the body.
function swimPose(A,k,mv,ph){if(!A||!A.legs||k<.01)return 0;
  const stroke=k>.6&&mv>.2,pitch=k*(.22+.85*(stroke?mv:0));
  A.hips.rotation.x=pitch;A.head.rotation.x=-pitch*.8;
  A.arms.forEach((a,i)=>{const o=ph+i*Math.PI;
    if(stroke){a.sh.rotation.x=-(((o%(Math.PI*2))+Math.PI*2)%(Math.PI*2));a.sh.rotation.z=a.sx*.18;a.el.rotation.x=-.3;}
    else{a.sh.rotation.x+=(-.35+Math.sin(o*.8)*.3-a.sh.rotation.x)*k;a.sh.rotation.z+=(a.sx*(1+Math.sin(ph*1.6)*.2)-a.sh.rotation.z)*k;a.el.rotation.x+=(-.55-a.el.rotation.x)*k;}});
  A.legs.forEach((l,i)=>{const o=ph*(stroke?2.4:1.3)+i*Math.PI;l.hp.rotation.x+=(Math.sin(o)*(stroke?.32:.5)-(stroke?0:.25)-l.hp.rotation.x)*k;l.kn.rotation.x+=(.2+Math.max(0,Math.sin(o+1))*(stroke?.35:.6)-l.kn.rotation.x)*k;});
  // sink until the head is just above the water
  return k*(A.hip+.62*Math.cos(pitch)+.12);}

