const SEA_BUILD={dolphin:seaDolphin,whale:seaWhale,turtle:seaTurtle,seal:()=>{const m=seaSeal(true);m.g.scale.setScalar(SEAL_RIDE_S);m.seat*=SEAL_RIDE_S;return m;}};
