function skyCamBack(){const S=SKY;if(!S.mode)return 0;if(S.mode==='plane'||S.mode==='board')return S.mode==='plane'?6.5:0;if(S.mode==='ff')return 2.6;if(S.mode.startsWith('hg'))return S.mode==='hgRun'?2.4:4.4;return 3.4;}
